-- Six independently reviewed reading papers. Insert immutable versions only.
-- Historical banks, attempts, answers, scores, access and all other modules stay intact.
begin;
do $preflight$ begin
 if (select count(*) from academy_tcf_reading.published_papers)<>20 then
  raise exception 'Expected twenty published reading papers'; end if;
 if (select count(*) from academy_tcf_reading.published_papers
     where test_id in ('tcf-reading-01','tcf-reading-02','tcf-reading-03','tcf-reading-04','tcf-reading-05','tcf-reading-06') and version='tcf-reading-2026-11-advanced-v5')<>6 then
  raise exception 'All six prior publication pointers must match reviewed v5'; end if;
 if exists(select 1 from academy_tcf_reading.papers
     where id in ('tcf-reading-01','tcf-reading-02','tcf-reading-03','tcf-reading-04','tcf-reading-05','tcf-reading-06') and version='tcf-reading-2026-11-close-reading-v6') then
  raise exception 'Never overwrite an existing immutable reading version'; end if;
end $preflight$;

insert into academy_tcf_reading.papers(id,version,content) values
('tcf-reading-01','tcf-reading-2026-11-close-reading-v6',$paper${"id":"tcf-reading-01","version":"tcf-reading-2026-11-close-reading-v6","title":"TCF Reading · Test 01","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"Information à tous les voyageurs : En raison de fortes chutes de neige, tous les vols à destination de Genève sont annulés ce lundi. Les passagers concernés peuvent modifier leur billet sans frais. Aéroport International de Lyon","question":"Que doivent faire les passagers concernés par cette annonce ?","options":["Demander un nouveau trajet sans frais","Modifier la destination en payant un supplément","Se présenter pour un vol à l'heure prévue","Attendre une reprise des vols pour Genève"],"correct":"A","explanation":"« Les passagers concernés peuvent modifier leur billet sans frais » : le changement de vol est gratuit."},{"number":2,"points":3,"passage":"Message de la bibliothèque : Le retour des livres empruntés est prolongé jusqu’au 10 janvier, sans pénalité. Vous pouvez également utiliser la boîte extérieure prévue à cet effet. Bibliothèque municipale","question":"Que propose la bibliothèque à ses usagers ?","options":["Rendre les emprunts sans pénalité avant le 10 janvier","Déposer uniquement les livres le 10 janvier","Renouveler tous les prêts pour un mois","Retirer les livres à la bibliothèque après la date"],"correct":"A","explanation":"Le retour est prolongé « jusqu’au 10 janvier, sans pénalité ». Aucune prolongation sans limite n’est annoncée."},{"number":3,"points":3,"passage":"Cher(e)s client(e)s, Notre boutique en ligne sera en maintenance le jeudi 7 mars de 1 h à 5 h du matin. Pendant cette période, aucune commande ne pourra être passée. L’équipe de Maison Bio","question":"Que se passera-t-il entre 1 h et 5 h du matin le 7 mars ?","options":["Les commandes seront enregistrées avec retard","Les commandes seront possibles uniquement par téléphone","Les commandes ne pourront être modifiées qu'après cinq heures","Les commandes en ligne seront suspendues pendant la maintenance"],"correct":"D","explanation":"La maintenance a lieu de 1 h à 5 h ; « aucune commande ne pourra être passée » pendant cette période."},{"number":4,"points":3,"passage":"Annonce à tous les parents : L’école organise une sortie au musée pour les élèves de CE2 le mardi 17 avril. Les enfants doivent apporter un pique-nique, une bouteille d’eau et porter des chaussures confortables. École Les Érables","question":"Quel est l’objectif de ce message ?","options":["Demander aux parents de réserver les billets","Inviter les élèves à choisir leur musée préféré","Préciser le matériel nécessaire pour une sortie scolaire","Annoncer une réunion préparatoire à la sortie"],"correct":"C","explanation":"Le message précise la date de la sortie et ce que les enfants doivent apporter et porter."},{"number":5,"points":9,"passage":"Chers voisins, La fête de quartier annuelle aura lieu le samedi 15 juillet à partir de 16 h dans le parc du square des Lilas. Apportez un plat à partager et votre bonne humeur ! Jeux pour enfants, musique et tombola sont prévus. Le comité de quartier","question":"Pourquoi les voisins sont-ils invités au parc ?","options":["Participer à un repas associatif réservé aux enfants","Se réunir pour préparer la prochaine tombola","Faire connaissance pendant une fête de quartier","Se retrouver pour organiser un nettoyage du parc"],"correct":"C","explanation":"La fête de quartier prévoit un repas partagé, des jeux, de la musique et une tombola : il s’agit d’une célébration locale."},{"number":6,"points":9,"passage":"Annonce : Appartement 2 pièces à louer à partir du 1er septembre. 650 €/mois, charges comprises. Situé au 2e étage avec balcon, à 5 minutes du métro. Idéal pour une personne seule ou un jeune couple. Contact : immo.dubois@email.fr","question":"Quel type de logement est proposé ?","options":["Un appartement de deux pièces pour une ou deux personnes","Un studio à louer avec un espace extérieur","Un logement partagé entre plusieurs colocataires","Un appartement réservé aux familles nombreuses"],"correct":"A","explanation":"L’annonce indique un appartement de deux pièces, « idéal pour une personne seule ou un jeune couple »."},{"number":7,"points":9,"passage":"Bonjour ! Je viens d’avoir une excellente nouvelle : ma sœur attend un bébé ! Toute la famille est ravie, et je suis tellement impatiente de devenir tata ! On organise un petit repas dimanche prochain pour célébrer cette belle annonce. Tu veux venir ? Élodie","question":"Pourquoi Élodie est-elle heureuse ?","options":["Sa sœur prépare une fête d'anniversaire","Elle vient d'avoir un enfant","Elle retrouve sa sœur après un voyage","Elle va bientôt devenir tante"],"correct":"D","explanation":"Élodie annonce que sa sœur « attend un bébé » et qu’elle est impatiente de devenir tante."},{"number":8,"points":9,"passage":"Offre d’emploi – Assistant(e) administratif(ve) Entreprise locale recherche un(e) assistant(e) à mi-temps pour assurer l’accueil, la gestion des appels et le traitement des courriels. Expérience souhaitée, maîtrise de Word et Excel exigée. Envoyer CV à : emploi@bureauplus.fr","question":"Quel profil l’entreprise cherche-t-elle ?","options":["Une personne chargée uniquement des appels","Un responsable de recrutement à temps plein","Un spécialiste de la communication numérique","Un assistant administratif à l'aise avec la bureautique"],"correct":"D","explanation":"Le poste d’assistant administratif exige la maîtrise de Word et Excel, des outils bureautiques."},{"number":9,"points":9,"passage":"Invitation spéciale : Participez à notre soirée de réseautage pour les jeunes professionnels, jeudi 12 octobre à 18 h, au café Connect. Venez rencontrer des entrepreneurs, échanger des idées et élargir votre réseau. Entrée gratuite avec inscription en ligne.","question":"Quel est l’objectif principal de cet événement ?","options":["Obtenir un entretien d'embauche auprès des invités","Présenter un programme de formation diplômante","Faire des rencontres dans un cadre professionnel","Réserver un espace de travail au café"],"correct":"C","explanation":"La soirée permet de « rencontrer des entrepreneurs » et d’« élargir votre réseau »."},{"number":10,"points":9,"passage":"Chers amis, Cette année encore, nous organisons une collecte pour aider les familles en difficulté avant la rentrée. Vous pouvez déposer fournitures scolaires et vêtements en bon état à la mairie avant le 25 août. Merci pour votre générosité ! Association Entraide locale","question":"Quel est le but de cette collecte ?","options":["Aider les familles à préparer la rentrée scolaire","Collecter des dons pour un voyage des élèves","Financer une activité de loisirs à l'école","Réunir les familles pour une fête de quartier"],"correct":"A","explanation":"La collecte de fournitures et de vêtements aide les familles en difficulté « avant la rentrée »."},{"number":11,"points":15,"passage":"Cher Antoine, Je t’écris depuis le petit village de Kpalimé, au Togo, où je participe à un programme de volontariat depuis deux semaines. Nos journées sont bien remplies : nous aidons les instituteurs dans une école primaire, et l’après-midi, nous organisons des ateliers de lecture et d’hygiène pour les enfants. La chaleur est intense, mais l’ambiance est incroyable ! Je loge chez une famille locale très accueillante, et j’ai déjà goûté des plats typiques comme le fufu et l’igname pilée. Je prends beaucoup de photos et je t’enverrai un album à mon retour. À bientôt, Camille","question":"Pourquoi Camille est-elle au Togo ?","options":["Pour suivre une formation à l'université","Pour préparer un séjour touristique dans le pays","Pour participer bénévolement à un projet scolaire","Pour mener une enquête sur les entreprises locales"],"correct":"C","explanation":"Camille participe à un volontariat dans une école et organise des ateliers de lecture et d’hygiène."},{"number":12,"points":15,"passage":"Info aux parents : Nous vous informons qu’un mouvement de grève touchera l’ensemble des écoles primaires de la ville le jeudi 14 décembre. Il n’y aura ni cours, ni accueil périscolaire, ni cantine ce jour-là. Merci de prendre vos dispositions. Un service minimum d’accueil sera assuré à l’école Voltaire pour les enfants dont les deux parents travaillent et qui n’ont aucune solution de garde. Direction des affaires scolaires","question":"Quelle conséquence aura cette grève pour les familles ?","options":["Certains enfants suivront les cours dans une autre école","Les repas seront maintenus malgré l'arrêt des cours","Tous les élèves pourront être accueillis normalement","Des solutions d'accueil limitées seront prévues sous conditions"],"correct":"D","explanation":"Les cours et les services habituels sont supprimés. Seuls les enfants répondant aux conditions indiquées peuvent bénéficier de l’accueil à l’école Voltaire."},{"number":13,"points":15,"passage":"Technologie – Transports Depuis quelques semaines, des navettes électriques sans conducteur circulent dans certains quartiers de Lyon. Ces véhicules autonomes peuvent transporter jusqu’à 10 personnes et s’arrêtent à la demande, grâce à une application mobile. Ils roulent à faible vitesse, ce qui les rend très sûrs, notamment dans les zones piétonnes. Ce projet pilote est mené en partenariat avec la métropole de Lyon pour tester de nouvelles solutions de mobilité plus écologiques. Des questionnaires sont proposés aux passagers à la fin de chaque trajet pour recueillir leur avis sur le confort et la fiabilité du service.","question":"Que teste la ville de Lyon avec ce projet ?","options":["Une nouvelle ligne de métro souterraine","Des bus électriques avec chauffeur","Des navettes autonomes écologiques","Des vélos électriques à partager"],"correct":"C","explanation":"Les navettes sont électriques, « sans conducteur » et testées comme solution de mobilité écologique."},{"number":14,"points":15,"passage":"Cher Louis, Tu ne devineras jamais où je suis ! J’étais censée passer le week-end à Nantes, mais mon train a été annulé à cause d’un problème sur la ligne. J’ai donc pris un bus pour rejoindre une amie à La Rochelle, et nous avons décidé de passer deux jours ici. C’est une très belle ville ! On s’est promenées sur le port, et on a même visité l’aquarium. On profite du soleil et de l’air marin. Finalement, ce changement de programme était une bonne surprise. Je repars mardi matin. À très vite, Inès","question":"Dans quelle ville Inès a-t-elle passé le week-end ?","options":["À La Rochelle","À Nantes","À Paris","À Bordeaux"],"correct":"A","explanation":"Le train pour Nantes ayant été annulé, Inès a rejoint une amie à La Rochelle et y a passé deux jours."},{"number":15,"points":15,"passage":"Écologie – Actualité Le gouvernement a annoncé la mise en place progressive d’une interdiction des emballages plastiques à usage unique dans les commerces de proximité. Dès janvier prochain, les sacs plastiques seront bannis des boulangeries, des boucheries et des primeurs. Les clients devront venir avec leurs propres contenants, ou utiliser des sacs réutilisables en tissu ou en papier. Cette décision vise à réduire considérablement la production de déchets non recyclables, alors que la pollution plastique continue d’augmenter dans les milieux naturels. Des campagnes d'information sont prévues pour accompagner les professionnels et les consommateurs dans cette transition.","question":"Quel est l’objectif principal de cette mesure ?","options":["Favoriser la consommation locale","Réduire l’utilisation du plastique jetable","Protéger les commerces indépendants","Améliorer l’hygiène des produits vendus"],"correct":"B","explanation":"L’interdiction vise à « réduire considérablement la production de déchets non recyclables » liés aux plastiques à usage unique."},{"number":16,"points":15,"passage":"Vie locale Ce samedi, la maison des associations accueille un forum sur le thème “Grandir à l’ère numérique”. Parents, enseignants, psychologues et spécialistes du numérique interviendront pour échanger sur l’impact des écrans dans la vie des enfants et des adolescents. Des ateliers sont aussi prévus pour les jeunes, afin de leur apprendre à reconnaître les fausses informations, à limiter leur temps d’écran, et à mieux gérer les réseaux sociaux. L’entrée est libre, mais les places sont limitées. Renseignements sur le site de la mairie.","question":"Quel est le thème principal de cet événement ?","options":["L’impact de la technologie sur la santé physique","Les méthodes pour améliorer la mémoire","L’éducation des jeunes au numérique","Le développement de logiciels éducatifs"],"correct":"C","explanation":"Le forum « Grandir à l’ère numérique » porte sur les écrans, les fausses informations et les réseaux sociaux chez les jeunes."},{"number":17,"points":15,"passage":"Message d’Aurélie à son frère : Devine quoi ! J’ai enfin quitté mon travail au bureau pour me lancer dans ma passion : la pâtisserie. Je me suis inscrite à une formation intensive de six mois à Lyon pour apprendre les bases. Je me lève tôt, je finis tard, mais je n’ai jamais été aussi heureuse. Mon objectif est d’ouvrir ma propre boutique d’ici un an. Je commence à créer mes premières recettes, et mes collègues de cours sont super motivants. Tu peux venir goûter mes créations quand tu veux !","question":"Qu’a décidé de faire Aurélie ?","options":["Créer une école de cuisine","Faire une reconversion professionnelle","Ouvrir une boulangerie traditionnelle","Déménager à l’étranger"],"correct":"B","explanation":"Aurélie a quitté son emploi de bureau pour se former à la pâtisserie : elle change de métier."},{"number":18,"points":15,"passage":"Avis aux usagers du réseau TER À partir du 15 avril, le train de 7 h 22 entre Grenoble et Chambéry sera supprimé en raison de travaux sur la voie. Les voyageurs sont invités à prendre le train de 7 h 55, ou à utiliser les cars de substitution mis en place. Des retards sont également à prévoir sur les lignes voisines pendant la durée des travaux. Des annonces seront faites en gare, et les informations seront mises à jour chaque jour sur le site TER.","question":"Qu’indique cet avis aux voyageurs ?","options":["La suppression d’un train du matin","Un changement de gare de départ","L’ajout d’un nouveau train en matinée","La gratuité des trains pendant les travaux"],"correct":"A","explanation":"L’avis annonce que « le train de 7 h 22 […] sera supprimé » à partir du 15 avril."},{"number":19,"points":15,"passage":"Société – Médias Selon une étude récente, près de 40 % des adultes de moins de 30 ans s’informent exclusivement via les réseaux sociaux. Ce phénomène inquiète certains experts, car ces plateformes mélangent contenus d’information, opinions personnelles, publicités, et fausses nouvelles. De plus, les algorithmes montrent souvent aux utilisateurs les contenus qui renforcent leurs idées déjà existantes, ce qui limite l’ouverture d’esprit. Des associations proposent désormais des ateliers d’éducation aux médias, notamment dans les lycées et les universités.","question":"Quel problème est soulevé dans cet article ?","options":["Le manque de connexion dans les zones rurales","Le coût croissant des abonnements presse","L’augmentation du temps passé à lire les journaux papier","Les dangers d’une information non vérifiée en ligne"],"correct":"D","explanation":"Le texte évoque le mélange d’informations, d’opinions, de publicités et de fausses nouvelles sur les réseaux sociaux."},{"number":20,"points":21,"passage":"La municipalité de Saint-Alban a lancé un programme incitatif pour encourager les habitants à installer des panneaux solaires sur leurs toits. Toute personne qui s’inscrit avant le 30 septembre bénéficiera d’une subvention couvrant jusqu’à 40 % des frais d’installation. En plus de l’aide financière, des ateliers d’information sont organisés pour expliquer les avantages environnementaux et économiques de cette transition. Le maire espère ainsi faire de Saint-Alban un exemple en matière d’énergie renouvelable. Il espère aussi réduire à terme les factures d’électricité de la population locale et contribuer aux objectifs nationaux de réduction carbone.","question":"Quelle est l’intention principale de la municipalité ?","options":["Promouvoir une réduction de la consommation d’électricité","Accroître l’usage des énergies fossiles","Réduire le nombre de toitures anciennes","Encourager les résidents à adopter l’énergie solaire"],"correct":"D","explanation":"Le programme subventionne l’installation de panneaux solaires afin d’encourager l’énergie renouvelable."},{"number":21,"points":21,"passage":"Dans une petite ville du sud de la France, une école a décidé de remplacer tous les manuels papier par des tablettes numériques. L’objectif est de moderniser les méthodes d’enseignement tout en réduisant le poids des cartables. Certains parents s’inquiètent de l’exposition prolongée des enfants aux écrans, mais les enseignants affirment que les contenus numériques permettent une approche plus interactive et personnalisée de l’apprentissage. Un suivi statistique des résultats sera aussi mis en place pour évaluer l’impact réel sur les performances scolaires.","question":"Quel est le principal changement apporté à cette école ?","options":["La suppression des devoirs à domicile","La réduction du nombre d’élèves par classe","L’introduction de tablettes pour remplacer les livres","La mise en place d’activités sportives"],"correct":"C","explanation":"L’école « a décidé de remplacer tous les manuels papier par des tablettes numériques »."},{"number":22,"points":21,"passage":"La Bibliothèque Nationale a récemment lancé une campagne de collecte de livres rares auprès du public. L’idée est de constituer un fonds de documents historiques afin de préserver la mémoire culturelle. Les particuliers peuvent proposer des ouvrages anciens, qui seront ensuite évalués par une équipe de spécialistes. En échange, leur nom sera mentionné dans les archives numériques et ils recevront un certificat de contribution. L’initiative a déjà permis de rassembler plus de 800 ouvrages datant d’avant 1900.","question":"Quel est le but de cette campagne ?","options":["Enrichir les collections personnelles des donateurs","Créer un musée de livres contemporains","Revendre les livres rares à des collectionneurs privés","Préserver des livres historiques pour les générations futures"],"correct":"D","explanation":"La collecte constitue un fonds de documents historiques pour « préserver la mémoire culturelle »."},{"number":23,"points":21,"passage":"Le chef étoilé Alain Morel a décidé d’ouvrir un restaurant gastronomique 100 % végétarien, une première pour lui. Cette décision s’inscrit dans une volonté de proposer une cuisine durable sans sacrifier le goût. Dans ses plats, il utilise des légumes oubliés, des légumineuses locales et des épices rares. Le restaurant connaît un succès inattendu, attirant même des amateurs de viande curieux de cette nouvelle expérience culinaire. Il envisage déjà d’ouvrir une deuxième adresse dans une autre grande ville européenne.","question":"Quelle orientation a pris le chef Alain Morel ?","options":["Il a arrêté la cuisine pour se consacrer à l’agriculture","Il propose une cuisine végétarienne de haute qualité","Il a ouvert une école de cuisine spécialisée en viande","Il se consacre uniquement à la pâtisserie"],"correct":"B","explanation":"Le chef ouvre un restaurant gastronomique « 100 % végétarien » sans sacrifier le goût."},{"number":24,"points":21,"passage":"Depuis plusieurs années, la ville de Rouen est confrontée à une augmentation du nombre de vélos dans les rues, ce qui provoque parfois des conflits entre cyclistes et piétons. Pour remédier à cela, la mairie a décidé d’élargir certaines voies piétonnes et d’installer des pistes cyclables séparées. Une campagne de sensibilisation a également été lancée pour rappeler à chacun les règles de bonne conduite en ville. Les premières évaluations montrent déjà une baisse des incidents signalés.","question":"Quelle mesure la ville a-t-elle prise pour réduire les conflits ?","options":["Interdire les vélos dans le centre-ville","Séparer les pistes pour piétons et cyclistes","Créer des zones de circulation exclusivement piétonnes","Limiter le nombre de vélos autorisés"],"correct":"B","explanation":"La mairie installe « des pistes cyclables séparées » et élargit certaines voies piétonnes."},{"number":25,"points":21,"passage":"Une enquête sur le sommeil relève, chez des adultes dormant peu, des difficultés de concentration, des oublis et une humeur dégradée. Un suivi de six semaines compare ensuite deux groupes qui ont allongé leurs nuits d'une durée semblable. Dans le premier, les heures de coucher continuent de varier; dans le second, elles deviennent régulières. Les deux groupes déclarent une amélioration du moral. Aux exercices de concentration, en revanche, seul le second progresse nettement. Le compte rendu ne présente pas de nouvelle mesure de la mémoire. En conclusion, les auteurs recommandent des nuits suffisamment longues et des horaires stables. Ils conseillent également de limiter les écrans et les boissons stimulantes le soir, sans avoir mesuré leur usage pendant le suivi.","question":"Quelle synthèse respecte la répartition des améliorations observées pendant le suivi ?","options":["La concentration s'améliore avec l'allongement des nuits, tandis que le moral dépend de leur régularité.","Le moral s'améliore dans les deux groupes, tandis que la concentration distingue les horaires réguliers.","Le moral s'améliore avec la réduction des écrans, tandis que la concentration bénéficie des nuits prolongées.","La mémoire s'améliore avec la baisse des stimulants, tandis que le moral distingue les horaires réguliers."],"correct":"B","explanation":"B. Le moral s'améliore dans les deux groupes, mais seule la concentration du groupe aux horaires réguliers progresse nettement. A inverse ces résultats. C transforme un conseil sur les écrans en cause observée. D attribue un progrès à la mémoire, qui n'a pas été remesurée, et aux stimulants, dont l'usage n'a pas été suivi."},{"number":26,"points":21,"passage":"Après six mois d'atelier en ligne, Clémence envoie son premier roman à trois éditeurs. L'un refuse parce que son catalogue est complet; un autre apprécie la voix de la narratrice, mais trouve le dénouement trop rapide. Le groupe de l'atelier, qui avait surtout lu le début, l'encourage à ne rien changer. Deux lecteurs du manuscrit entier reconnaissent aussi la voix singulière du récit. Ils comprennent la lettre du dernier chapitre, qui annonce que la mère quitte le domicile familial, mais pas pourquoi l'héroïne renonce ensuite à son propre départ. Clémence insère une scène antérieure: l'héroïne y promet à sa sœur de rester auprès d'elle si leur mère s'en va. Le dernier chapitre conserve la lettre et la décision finale. Le deuxième éditeur propose un contrat après cette révision. Le second tome reste à concevoir: Clémence attendra les réactions au livre publié avant d'en construire l'intrigue.","question":"Quelle fonction la scène ajoutée remplit-elle dans le roman de Clémence ?","options":["Elle rend plus reconnaissable la voix de la narratrice dans les événements qui conduisent au dénouement.","Elle amorce le conflit du second tome dans une scène située avant la fin du premier roman.","Elle avance la révélation de la lettre dans une scène antérieure pour alléger les événements du dernier chapitre.","Elle donne un antécédent au choix de l'héroïne pour rendre sa décision finale compréhensible."],"correct":"D","explanation":"D. La promesse faite à la sœur fournit une raison antérieure au renoncement final, que les lecteurs ne comprenaient pas. A reprend une qualité déjà reconnue avant la révision. B attribue à la scène une fonction liée à une intrigue encore à concevoir. C confond préparation de la décision et déplacement de la révélation: la lettre reste au dernier chapitre."},{"number":27,"points":21,"passage":"Sur un itinéraire du Mont-Blanc, le formulaire de réservation des refuges recueille les dates, les coordonnées et l'expérience déclarée des visiteurs. Les places restent attribuées dans l'ordre des demandes complètes. Des guides constatent que certains inscrits prennent leur confirmation pour une validation de leur préparation. La nouvelle organisation prévoit un appel aux débutants: on discute avec eux du parcours et du matériel avant leur venue. Au départ, le contrôle de l'équipement reste effectué dans l'ordre d'arrivée, sans créneau associé à la réservation. Un bulletin peut aussi être envoyé à tous les inscrits lorsque les conditions changent. Les responsables renoncent à proposer automatiquement un parcours voisin quand le refuge est complet: les secteurs moins fréquentés ne sont pas forcément moins fragiles. Les informations recueillies servent ainsi à une intervention supplémentaire des guides.","question":"Comment les guides utilisent-ils les informations du formulaire dans la nouvelle organisation ?","options":["Ils organisent des échanges avec les inscrits selon leur expérience déclarée, avant le contrôle effectué sur place.","Ils classent les demandes d'hébergement selon l'expérience déclarée, afin de donner la priorité aux visiteurs les mieux préparés.","Ils répartissent les contrôles de matériel dans des créneaux calculés à partir des dates indiquées par les visiteurs.","Ils adressent aux inscrits des propositions de parcours voisins selon les places encore disponibles dans les refuges."],"correct":"A","explanation":"A. L'expérience déclarée et les coordonnées permettent aux guides de contacter les débutants avant leur arrivée. B transforme ces renseignements en critère d'attribution des places, qui restent accordées dans l'ordre des demandes. C invente des créneaux alors que les contrôles suivent l'ordre d'arrivée. D reprend la réorientation automatique que les responsables ont écartée."},{"number":28,"points":21,"passage":"Lors d'une nuit des musées à Nantes, les entrées augmentent. Une conservatrice rappelle toutefois qu'un habitué visitant trois établissements compte trois fois. L'enquête de sortie repère aussi des personnes qui n'étaient entrées dans aucun musée durant l'année précédente. Beaucoup sont venues pour un atelier ou un spectacle. Une médiatrice souhaiterait maintenant qu'elles consacrent plus de temps aux collections permanentes; un autre responsable propose d'encourager les parcours entre plusieurs musées. La conservatrice retient un autre critère prioritaire pour la prochaine édition: atteindre des habitants jusque-là éloignés de ces établissements, sans se laisser tromper par le cumul des passages. Elle demande que l'enquête distingue les personnes et leurs habitudes antérieures. Des invitations à revenir seront également distribuées. Leur utilisation fera l'objet d'un bilan distinct, plusieurs mois après l'événement: découvrir, approfondir et revenir ne seront pas confondus dans une même mesure.","question":"Quel résultat satisferait le critère retenu par la conservatrice pour la prochaine édition ?","options":["À fréquentation totale égale, davantage de visiteurs consacrent une part plus longue de leur soirée aux collections permanentes.","À fréquentation totale égale, davantage de visiteurs déjà venus auparavant effectuent un parcours dans plusieurs établissements de la ville.","À fréquentation totale égale, davantage de visiteurs déclarent n'être entrés dans aucun musée au cours de l'année précédente.","À fréquentation totale égale, davantage de visiteurs utilisent leur invitation pour une nouvelle visite après la fin de l'événement."],"correct":"C","explanation":"C. Le critère prioritaire concerne les personnes jusqu'alors éloignées des musées, en distinguant personnes et entrées. Le résultat C traduit cette ouverture à un total d'entrées identique. A mesure l'approfondissement proposé par la médiatrice; B, l'intensification du parcours des habitués. D renseigne la fidélisation, qui doit être évaluée dans un bilan séparé."},{"number":29,"points":21,"passage":"Deux quartiers testent des éclairages moins perturbants. Dans le premier, les lampadaires habituels s'éteignent à vingt-trois heures. Dans le second, des appareils dirigés vers le sol éclairent moins fortement dès la tombée de la nuit. Les deux solutions réduisent presque autant la consommation. Les astronomes constatent un ciel plus sombre dans le premier quartier après l'extinction; dans le second, le halo diminue plus tôt, mais reste perceptible. Les naturalistes suivent surtout des insectes actifs en début de soirée: leur dispersion autour des lampes recule davantage dans le second quartier. Les élus avaient prévu de retenir l'option produisant le plus beau ciel à minuit. Le rapport leur demande d'intégrer aussi l'horaire des phénomènes qu'ils cherchent à corriger.","question":"Quel rapprochement entre éclairage et dispersion des insectes correspond aux observations ?","options":["La moindre dispersion est observée dans le quartier qui retrouve l'obscurité la plus complète après vingt-trois heures.","La dispersion recule dans les mêmes proportions avec une lumière réduite tôt et avec une extinction plus tardive.","La moindre dispersion est observée dans le quartier où le halo a disparu dès le début de la soirée.","La moindre dispersion est observée dans le quartier où le halo est atténué pendant la première partie de la soirée."],"correct":"D","explanation":"D. Les insectes suivis sont actifs tôt et leur dispersion recule davantage dans le second quartier, où le halo diminue dès la tombée de la nuit. A attribue ce résultat au premier quartier, plus sombre seulement après l'extinction. B affirme une égalité d'effet que les observations contredisent. C transforme la diminution précoce du halo en disparition, alors que celui-ci reste perceptible."},{"number":30,"points":26,"passage":"En absorbant du CO₂ atmosphérique, les océans ralentissent son accumulation dans l'air. Le carbone dissous modifie cependant la chimie de l'eau et contribue à l'acidification, qui peut fragiliser les organismes calcaires. Une équipe compare deux stations côtières, A et B. Durant le suivi, les températures augmentent dans des proportions voisines et une restriction des prélèvements sur les récifs entre en vigueur à la même date. À la station A, une installation réduit en outre les rejets organiques dont la décomposition libère du CO₂ dans l'eau. L'acidité y recule et le récif reprend sa croissance; à B, les rejets restent élevés et cette reprise n'est pas observée. Les analyses distinguent le carbone provenant de l'atmosphère: sa quantité augmente de façon comparable aux deux stations. Plusieurs explications de la différence entre récifs sont discutées dans le rapport. L'équipe privilégie celle qui rend compte de cette combinaison de mesures, sans présenter la reprise locale comme la disparition du problème associé au rôle climatique de l'océan.","question":"Quel rapprochement étaye l'interprétation retenue par l'équipe pour expliquer la différence entre les récifs ?","options":["La reprise d'un récif accompagne un ralentissement local de l'absorption du carbone, alors que les apports organiques évoluent de façon comparable.","La reprise d'un récif accompagne la réduction d'une source locale d'acidité, alors que l'entrée de carbone atmosphérique progresse aux deux sites.","La reprise d'un récif accompagne un refroidissement local de l'eau, alors que l'acidité liée aux apports organiques évolue de façon comparable.","La reprise d'un récif accompagne une protection plus ancienne contre les prélèvements, alors que les températures évoluent de façon comparable."],"correct":"B","explanation":"B. Les températures, la date de protection et la progression du carbone atmosphérique sont comparables. La différence observée porte sur la réduction des rejets organiques à A, suivie d'un recul de l'acidité et d'une reprise du récif. A attribue la différence au carbone atmosphérique, dont la progression reste comparable. C introduit un refroidissement absent du suivi. D suppose un décalage de protection alors que la mesure commence à la même date. Le bénéfice local ne supprime donc pas l'acidification liée au CO₂ atmosphérique."},{"number":31,"points":26,"passage":"Dans une école expérimentale, les élèves organisent une partie de leur semaine autour de questions qu'ils ont choisies. Les enseignants les aident à chercher des sources et à discuter leurs conclusions, sans imposer un manuel commun. Après un an, les dossiers personnels sont plus documentés et les élèves prennent davantage la parole. Des parents y voient la preuve d'une autonomie acquise. L'équipe d'évaluation relève toutefois que les familles, qui ont choisi cette école, soutiennent beaucoup les projets à domicile. Pour le prochain suivi, chaque enfant conservera son projet et recevra aussi, par tirage au sort, un sujet éloigné de ses centres d'intérêt déclarés. Dans les deux cas, on consignera ses premières recherches avant l'intervention habituelle de l'enseignant. Les conditions d'accès aux documents et les occasions de discussion resteront identiques. L'équipe n'organisera pas de variation de l'aide familiale. Elle s'intéressera au démarrage individuel du travail, au-delà de la qualité du dossier achevé.","question":"Quel rapprochement entre deux séries d'observations correspond le mieux au prochain examen prévu ?","options":["La manière d'engager une recherche sur un même sujet avant et après une discussion de méthode entre élèves.","La manière d'engager une recherche sur un sujet choisi personnellement et sur un sujet attribué à l'élève.","La manière d'engager une recherche sur un sujet personnel avec et sans accompagnement du projet par la famille.","La manière d'engager une recherche avec un ensemble de sources fourni et avec des documents à trouver soi-même."],"correct":"B","explanation":"B. Chaque enfant travaillera sur son projet et sur un sujet attribué, avec des conditions documentaires et pédagogiques identiques; les premières démarches permettront d'examiner si l'autonomie observée dépend du choix du sujet. A introduit une variation des discussions qui n'est pas prévue. C transforme une limite reconnue du contexte familial en variable du prochain suivi. D suppose une différence d'accès aux sources que le dispositif maintient identique."},{"number":32,"points":26,"passage":"À Bordeaux, une ancienne voie ferrée est devenue une promenade plantée. Un immeuble la borde directement, mais le mur ferroviaire oblige ses habitants à rejoindre une entrée éloignée. Une rue située plus loin donne, elle, directement sur un accès. Les ateliers de jardinage attirent des visiteurs des deux secteurs. Pour un essai d'un mois, la ville ouvre un passage dans le mur, sans modifier les ateliers ni les zones de végétation spontanée. L'enquête reprend la même liste de ménages avant et pendant l'essai. Plusieurs riverains qui ne venaient jamais traversent désormais la promenade pour rejoindre le tramway ou les commerces. Les anciens usagers proches gardent approximativement leur rythme de visite. Les comptages aux accès des rues plus éloignées varient peu. Le total des entrées progresse donc, mais les inscriptions aux ateliers conservent leur effectif et leur répartition par secteur. Les observations montrent aussi que les nouveaux traversants s'arrêtent rarement dans les jardins. La ville souhaite pérenniser l'ouverture et doit préciser ce que ce succès permet de conclure sur le rôle social de la promenade.","question":"Quelle lecture du bilan distingue correctement le développement des usages et leur nature ?","options":["L'ouverture attire de nouveaux riverains pour leurs déplacements ordinaires; elle élargit l'usage du lieu sans accroître la participation aux ateliers.","L'ouverture intensifie les passages des riverains déjà usagers; elle augmente leur fréquentation sans renouveler sensiblement le public de la promenade.","L'ouverture redistribue les arrivées des habitués plus éloignés; elle déplace leurs trajets sans accroître sensiblement l'usage par les riverains proches.","L'ouverture attire de nouveaux riverains aux activités collectives; elle élargit d'abord leur participation aux ateliers avant leurs déplacements ordinaires."],"correct":"A","explanation":"A. Des ménages auparavant absents traversent désormais la promenade pour rejoindre le tramway ou les commerces, tandis que les ateliers gardent leur effectif et leur répartition. B confond l'arrivée de nouveaux usagers avec une hausse du rythme des habitués, qui reste comparable. C attribue la progression à une réorientation des accès éloignés, dont les comptages changent peu. D transforme le développement des traversées en hausse de la participation collective. L'ouverture élargit ici l'accès aux déplacements ordinaires, sans accroître la fréquentation des ateliers."},{"number":33,"points":26,"passage":"Dans Les Brumes du Nord, une expédition traverse une Scandinavie imaginaire pour retrouver un objet lié à une ancienne légende. Le critique admire les paysages et la fluidité des scènes de voyage; il ne reproche pas au roman de prendre son temps. Il remarque en revanche que le narrateur annonce très tôt la loyauté future de certains personnages et la trahison d'un autre. Plusieurs chapitres qui devraient mettre leurs intentions à l'épreuve ne font alors que confirmer ces indications. Les personnages secondaires parlent parfois d'une même voix, mais quelques échanges leur donnent une réelle épaisseur. Quant à la légende, elle reste suffisamment claire pour orienter la quête sans exiger de longues explications. Le dernier retournement produit ainsi moins une surprise qu'une vérification. Les amateurs d'atmosphères nordiques pourront apprécier le voyage; le lecteur venu chercher une aventure incertaine risque de rester à distance.","question":"Quelle modification répondrait le mieux à la réserve principale de ce critique ?","options":["Raccourcir les descriptions qui séparent les principales étapes du voyage.","Différencier davantage les façons de parler des compagnons de l'expédition.","Retarder les indications qui dévoilent les choix décisifs des personnages.","Développer les explications sur la légende qui donne son but à l'expédition."],"correct":"C","explanation":"C. Le suspense est affaibli parce que le narrateur annonce des décisions que les événements ne font ensuite que confirmer. A traite une lenteur que le critique ne reproche pas au roman. B améliorerait un défaut secondaire réel, sans répondre au problème central d'incertitude. D développe un élément déjà jugé suffisamment clair."},{"number":34,"points":26,"passage":"Une enquête demande à de jeunes adultes de décrire une vie réussie. Voyages, concerts et apprentissages nouveaux occupent plus de place que l'achat d'objets. Une sociologue compare ensuite leurs déclarations à leurs publications. Le matériel acquis pour pratiquer apparaît dans plusieurs images, mais les commentaires portent surtout sur l'accès à une destination rare ou à un événement difficile à réserver. Des progrès dans un cours de danse ordinaire suscitent peu de réactions, contrairement à un stage réputé, même lorsque son participant débute. Les projets encore inaccessibles sont évoqués dans les entretiens, mais restent peu visibles sur les profils; ce sont surtout les séjours accomplis qui y circulent. Les personnes disposant des revenus les plus élevés multiplient ces expériences valorisées. Plusieurs disent comparer leurs découvertes à celles de leurs proches. La sociologue reconnaît que les aspirations changent; elle discute ce que ce changement signifie pour les manières de se distinguer.","question":"Comment la sociologue interprète-t-elle le déplacement des signes de réussite ?","options":["Les équipements nécessaires redeviennent les principaux signes de réussite; les expériences servent surtout à mettre ces biens en scène.","Les projets annoncés deviennent des signes de réussite au même titre que les séjours accomplis; leur réalisation pèse moins dans les comparaisons.","Les savoir-faire acquis deviennent les principaux signes de réussite; la reconnaissance dépend surtout de la maîtrise montrée par les participants.","Les expériences rares deviennent des signes de réussite; leur accès inégal maintient le rôle des ressources financières dans les comparaisons."],"correct":"D","explanation":"D. Les réactions valorisent l'accès à des expériences rares, que les revenus élevés permettent de multiplier. La distinction change donc de support sans se détacher des ressources financières. A confond la présence du matériel dans les images avec ce que les commentaires valorisent. B met les projets au même rang que les réalisations malgré leur faible visibilité. C privilégie la maîtrise, alors que le contraste entre le cours ordinaire et le stage réputé montre une autre hiérarchie."},{"number":35,"points":26,"passage":"Dans un atelier destiné à des personnes âgées ayant des difficultés de mémoire, des chansons choisies avec leurs proches font émerger des récits personnels. Une équipe compare ces séances à des entretiens sans musique, menés par les mêmes soignants avec les mêmes questions. Pendant les chansons, davantage de lieux, de prénoms et de scènes de jeunesse sont évoqués. Les participants paraissent aussi plus détendus. Pour une chercheuse, les morceaux pourraient offrir des indices liés à l'histoire de chacun. Un collègue souligne que le plaisir d'écouter pourrait rendre les personnes plus disponibles pour raconter, sans que la chanson ait été associée à l'événement évoqué. L'équipe a par ailleurs constaté que les récits redeviennent rares après la séance et qu'un exercice d'apprentissage de mots nouveaux ne bénéficie pas du même effet. Elle ne cherche donc pas à démontrer une amélioration générale de la mémoire. Elle veut comprendre ce qui, dans l'écoute, facilite ces échanges autobiographiques avant de choisir les morceaux des prochains ateliers.","question":"Quelle comparaison supplémentaire départagerait le mieux les explications en présence ?","options":["Faire écouter le même air familier avec un soignant habituel puis avec un accompagnateur rencontré récemment.","Faire écouter un air familier puis un air inconnu, également appréciés et de tempo comparable.","Comparer les mêmes souvenirs pendant l'atelier puis le lendemain, avec une durée d'entretien et des questions identiques.","Comparer l'apprentissage d'une même liste avec une chanson familière puis sans musique, dans des conditions d'entretien identiques."],"correct":"B","explanation":"B. À plaisir musical comparable, la différence entre air familier et air inconnu teste le rôle des associations personnelles. A fait varier l'accompagnateur alors que le débat oppose deux mécanismes liés à l'écoute. C porte sur la persistance, déjà reconnue comme limitée. D teste un apprentissage nouveau, alors que l'équipe étudie l'accès à des souvenirs autobiographiques."},{"number":36,"points":33,"passage":"Dans plusieurs restaurants végétariens, les nouveaux clients se présentent moins souvent comme végétariens que les habitués. Une enquêtrice étudie un établissement dont la carte a été réécrite: les noms évoquent désormais une cuisson, une texture ou une association de saveurs. Les recettes ont peu changé. Les entretiens distinguent deux groupes. Les premiers habitués parlent surtout de leurs convictions et de leur attachement aux producteurs; les nouveaux venus, qui mangent souvent de la viande ailleurs, citent principalement le plaisir des plats. Le registre des réservations montre que les habitués reviennent aussi régulièrement qu'avant, mais occupent désormais moins de la moitié des tables. L'enquêtrice consulte ensuite les commandes et les contrats: la sélection des fournisseurs locaux et les engagements saisonniers demeurent ceux des années précédentes. Les informations correspondantes sont toujours données sur demande, bien qu'elles figurent moins en évidence sur la carte. Un commentateur voit dans la nouvelle présentation un effacement de l'identité du restaurant. Pour discuter ce jugement, l'enquêtrice rapproche les entretiens des documents d'approvisionnement.","question":"Quel constat permet à l'enquêtrice de nuancer le jugement du commentateur ?","options":["Les nouveaux clients viennent surtout pour le plaisir culinaire, tandis que les critères suivis dans les achats restent ceux de la période précédente.","Les nouveaux clients viennent surtout par conviction écologique, tandis que la présentation des plats met désormais leurs qualités gustatives en avant.","Les premiers habitués occupent encore la majorité des tables, tandis que les nouveaux clients expliquent surtout leur venue par le plaisir culinaire.","Les critères suivis dans les achats deviennent plus souples, tandis que les nouveaux clients citent surtout leur attachement aux producteurs locaux."],"correct":"A","explanation":"A. Les entretiens attribuent principalement aux nouveaux clients un motif culinaire; les contrats et commandes montrent pourtant la continuité des critères d'approvisionnement. Le changement de présentation et de public ne se confond donc pas avec un abandon de ces choix. B transfère aux nouveaux clients les convictions surtout exprimées par les habitués. C transforme la régularité des anciens clients en majorité numérique. D inverse à la fois la continuité des achats et le motif dominant du nouveau public."},{"number":37,"points":33,"passage":"Une entreprise de conception autorisait chacun à choisir ses jours de télétravail. Les tâches courantes étaient achevées à temps, mais certaines demandes des nouveaux recrutés restaient longtemps en attente. Elle expérimente deux jours de présence hebdomadaire pour tous. Chaque équipe fixe ses jours et dispose alors d'un créneau d'atelier réservé. Les concepteurs choisissent le lundi et le mardi; les chargés de clientèle, le mercredi et le jeudi. Les référents des deux services sont les mêmes depuis le début de l'année. Les dossiers numériques sont consultables à toute heure, au bureau comme à domicile. Après un mois, la présence moyenne augmente et les réunions internes à chaque équipe se tiennent plus facilement. Les demandes encore en attente concernent surtout des modifications de prototypes. Elles parviennent d'emblée au bon destinataire. Pour trancher, le concepteur doit examiner l'objet avec la personne qui connaît les engagements pris auprès du client; cet examen commun ne peut se faire qu'à l'atelier. Les équipes anciennes traitent plus vite les cas familiers. La direction hésite à étendre le dispositif sur la seule base du taux de présence.","question":"Quel mécanisme explique la persistance des demandes en attente malgré l'essai ?","options":["Les arrivées se concentrent sur les mêmes créneaux, de sorte que la concurrence pour l'atelier freine davantage les échanges que les absences.","Les jours choisis facilitent les échanges internes aux équipes, mais ne réunissent pas les personnes nécessaires aux décisions entre les deux services.","Les interlocuteurs changent plus souvent que les jours de présence, de sorte que les nouveaux recrutés doivent régulièrement reprendre leur recherche de contacts.","Les jours communs réunissent les interlocuteurs nécessaires, mais les dossiers ne sont accessibles que pendant une partie de leurs horaires de présence."],"correct":"B","explanation":"B. Les jours de présence des concepteurs et des chargés de clientèle ne se recoupent pas, alors que les modifications en attente nécessitent leur examen commun du prototype à l'atelier. La hausse de présence et l'amélioration des réunions internes ne garantissent donc pas cette rencontre. A suppose une concurrence sur des créneaux communs, contrairement aux jours distincts et aux créneaux réservés. C invoque un renouvellement des référents alors qu'ils sont stables et que les demandes arrivent au bon destinataire. D confond la rencontre physique nécessaire avec un accès documentaire disponible à toute heure."},{"number":38,"points":33,"passage":"Dans une école rurale, une enseignante travaille avec trois niveaux. Des parents voient dans l'entraide entre âges une manière de rendre chacun plus autonome. Pour préparer une réorganisation, l'enseignante rapproche deux relevés. Le premier comptabilise les exercices réussis: les aînés obtiennent de bons résultats sur les séries déjà étudiées, qu'ils savent aussi expliquer. Le second retrace l'emploi de leur temps. Deux d'entre eux sont interrompus plusieurs fois par séance pour reformuler les consignes des plus jeunes. Leurs carnets contiennent moins d'essais sur les problèmes inédits proposés à leur niveau que ceux des autres aînés. Les tablettes facilitent certaines activités individuelles, surtout pour les enfants capables de lire seuls; des demandes de reformulation subsistent. L'enseignante essaiera une rotation des rôles et une demi-journée de présence adulte supplémentaire pendant un mois. Le bilan réunira les totaux de la classe et les carnets individuels. Les parents souhaitent que les plus jeunes continuent à réussir les activités qu'ils terminaient avec cette aide. Aucun résultat de cette nouvelle organisation n'est encore disponible.","question":"Quel résultat vérifierait à la fois la correction de la difficulté relevée chez les aînés et la condition posée par les parents ?","options":["Le taux de réussite aux problèmes nouveaux augmente chez les aînés sollicités; les plus jeunes conservent leur réussite aux activités habituelles.","Les aînés sollicités abordent davantage de problèmes nouveaux; les plus jeunes déchiffrent davantage de consignes sans aide.","Les aînés sollicités abordent davantage de problèmes nouveaux; les plus jeunes conservent leur réussite aux activités habituelles.","Le taux de réussite aux problèmes nouveaux augmente chez les aînés sollicités; les plus jeunes déchiffrent davantage de consignes sans aide."],"correct":"C","explanation":"C. La difficulté documentée concerne le nombre de problèmes nouveaux abordés par les aînés sollicités, et les parents demandent le maintien des réussites des plus jeunes. A mesure l'exactitude des réponses des aînés, sans établir qu'ils abordent plus de problèmes. B mesure une autonomie de lecture chez les petits, sans vérifier le maintien de leurs réussites. D combine ces deux substitutions. Les quatre résultats seraient positifs, mais seul C vérifie directement les deux critères du texte."},{"number":39,"points":33,"passage":"Pour mieux intégrer les trottinettes en location, une ville réduit le parc disponible et impose de terminer les trajets sur des emplacements réservés. Un an plus tard, les plaintes pour trottoirs encombrés ont fortement diminué. Des observations sur place confirment que les véhicules sont mieux rangés. Le nombre d'accidents corporels baisse lui aussi, mais moins fortement que le nombre de trajets effectués. L'opérateur présente ces deux évolutions comme une amélioration générale de la sécurité. Une association de piétons reconnaît le progrès du stationnement, tout en demandant de distinguer les questions. Près de certaines stations, les usagers roulent désormais davantage sur la chaussée, où des conflits avec les véhicules sont encore signalés. Les fiches concernant les abords des stations décrivent les points de conflit, sans compter les trajets locaux ni distinguer systématiquement incidents évités et accidents. Le relevé des plaintes concerne, lui, l'encombrement des trottoirs. Avant de rétablir davantage de véhicules, la ville prévoit de comparer les accidents à l'usage réel et d'examiner les points de conflit autour des stations.","question":"Quelle lecture des évolutions à l'échelle de la ville et autour des stations est étayée par ce bilan ?","options":["La fréquence des accidents par trajet augmente dans la ville; son évolution autour des stations reste indéterminée dans ce bilan.","La fréquence des accidents par trajet augmente dans la ville; elle augmente aussi autour des stations par rapport à la période précédente.","La fréquence des accidents par trajet diminue dans la ville; elle augmente cependant autour des stations par rapport à la période précédente.","La fréquence des accidents par trajet diminue dans la ville; son évolution autour des stations reste indéterminée dans ce bilan."],"correct":"A","explanation":"A. Les trajets diminuent plus fortement que les accidents: la fréquence par trajet augmente donc à l'échelle de la ville. Les fiches autour des stations ne donnent ni le nombre de trajets ni un décompte homogène des accidents, ce qui empêche d'y mesurer cette évolution. B transforme les signalements de conflits en hausse de fréquence mesurée. C commet cette même extension tout en confondant baisse du nombre total et baisse de fréquence. D conserve la bonne réserve locale, mais inverse la tendance du rapport accidents/trajets."}]}$paper$::jsonb),
('tcf-reading-02','tcf-reading-2026-11-close-reading-v6',$paper${"id":"tcf-reading-02","version":"tcf-reading-2026-11-close-reading-v6","title":"TCF Reading · Test 02","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"Avis aux locataires : la cour sera nettoyée mercredi matin. Merci de retirer vos vélos mardi soir. Le local à vélos restera accessible.\n\nLes objets oubliés seront placés sous l'abri. L'entreprise doit pouvoir circuler librement avec son matériel de lavage.","question":"Que faut-il faire mardi soir ?","options":["Nettoyer les escaliers","Retirer les vélos de la cour","Fermer le local à vélos","Rapporter les clés"],"correct":"B","explanation":"Le passage indique : « Avis aux locataires : la cour sera nettoyée mercredi matin. Merci de retirer vos vélos mardi soir. Le local à vélos restera accessible. » Cela justifie la réponse : Retirer les vélos de la cour."},{"number":2,"points":3,"passage":"Le gardien sera absent vendredi. Pour une fuite urgente, appelez le numéro affiché dans le hall ; les demandes ordinaires attendront lundi.\n\nUn message vocal précisera la nature du problème.","question":"Quand faut-il appeler le numéro affiché ?","options":["En cas de fuite urgente","Pour changer de boîte aux lettres","Pour réserver une visite","Pour payer le loyer"],"correct":"A","explanation":"Le passage indique : « Le gardien sera absent vendredi. Pour une fuite urgente, appelez le numéro affiché dans le hall ; les demandes ordinaires attendront lundi. » Cela justifie la réponse : En cas de fuite urgente."},{"number":3,"points":3,"passage":"La permanence logement change d'adresse : dès lundi, les rendez-vous auront lieu au 8, rue des Tilleuls. Les horaires restent identiques.\n\nL'ancienne adresse accueillera des travaux. Les dossiers déjà ouverts seront transférés automatiquement, sans nouvelle inscription des habitants concernés.","question":"Qu'est-ce qui change ?","options":["Le lieu des rendez-vous","Le prix du service","Les pièces à fournir","Les jours d'ouverture"],"correct":"A","explanation":"Le passage indique : « La permanence logement change d'adresse : dès lundi, les rendez-vous auront lieu au 8, rue des Tilleuls. Les horaires restent identiques. » Cela justifie la réponse : Le lieu des rendez-vous."},{"number":4,"points":3,"passage":"Le jardin de la résidence ferme à vingt heures cet été. Les habitants peuvent y déjeuner, mais les barbecues sont interdits.\n\nCette règle s'applique aussi aux invités. Le portail sera fermé chaque soir par le responsable de permanence, après vérification des lieux.","question":"Quelle activité est autorisée ?","options":["Entrer après vingt heures","Allumer un barbecue","Organiser un feu de bois","Prendre son déjeuner au jardin"],"correct":"D","explanation":"Le passage indique : « Le jardin de la résidence ferme à vingt heures cet été. Les habitants peuvent y déjeuner, mais les barbecues sont interdits. » Cela justifie la réponse : Prendre son déjeuner au jardin."},{"number":5,"points":9,"passage":"Salut Nora, j'ai trouvé une chambre moins chère, mais elle est loin de mon travail. Je préfère encore chercher près du tram, même si je dois payer un peu plus.\n\nUne collègue m'a parlé d'un immeuble bien situé où une chambre se libère bientôt.","question":"Quel critère Nora doit-elle comprendre comme prioritaire ?","options":["La taille de la chambre","La présence d'un balcon","Le prix le plus bas possible","La facilité des trajets"],"correct":"D","explanation":"Le passage indique : « Salut Nora, j'ai trouvé une chambre moins chère, mais elle est loin de mon travail. Je préfère encore chercher près du tram, même si je dois payer un peu plus. » Cela justifie la réponse : La facilité des trajets."},{"number":6,"points":9,"passage":"Chers voisins, notre installation samedi risque d'être bruyante entre neuf heures et midi. Nous laisserons l'ascenseur libre en dehors des déplacements de meubles. Merci de votre patience.\n\nLe camion restera devant notre entrée pendant le déchargement.","question":"Pourquoi ce message est-il envoyé ?","options":["Annoncer une panne durable","Demander un changement d'étage","Prévenir d'une gêne temporaire","Interdire l'usage de l'ascenseur"],"correct":"C","explanation":"Le passage indique : « Chers voisins, notre installation samedi risque d'être bruyante entre neuf heures et midi. Nous laisserons l'ascenseur libre en dehors des déplacements de meubles. Merci de votre patience. » Cela justifie la réponse : Prévenir d'une gêne temporaire."},{"number":7,"points":9,"passage":"Je te rends les clés dimanche après avoir relevé le compteur. Le propriétaire accepte que nous fassions l'état des lieux par vidéo, car il est en déplacement.\n\nJe filmerai chaque pièce et lui transmettrai les photographies des relevés. Il vérifiera ensuite le document avant que nous le signions ensemble.","question":"Comment le propriétaire participera-t-il ?","options":["À distance","Par courrier uniquement","En venant dimanche soir","En passant chez un voisin"],"correct":"A","explanation":"Le passage indique : « Je te rends les clés dimanche après avoir relevé le compteur. Le propriétaire accepte que nous fassions l'état des lieux par vidéo, car il est en déplacement. » Cela justifie la réponse : À distance."},{"number":8,"points":9,"passage":"L'association propose un atelier pour comprendre un bail. Apportez une copie sans vos coordonnées personnelles. Les animateurs expliqueront les clauses ; ils ne chercheront pas de logement à votre place.\n\nDeux séances sont proposées samedi pour les personnes qui travaillent en semaine.","question":"Quel service est proposé ?","options":["Collecter les coordonnées des participants","Aider à comprendre un contrat","Signer un bail pour le locataire","Trouver un appartement garanti"],"correct":"B","explanation":"Le passage indique : « L'association propose un atelier pour comprendre un bail. Apportez une copie sans vos coordonnées personnelles. Les animateurs expliqueront les clauses ; ils ne chercheront pas de logement à votre place. » Cela justifie la réponse : Aider à comprendre un contrat."},{"number":9,"points":9,"passage":"Annonce : chambre meublée chez une retraitée, contre une présence deux soirs par semaine. Il ne s'agit pas d'un emploi d'aide à domicile. Les tâches médicales sont exclues.\n\nUne rencontre préalable permettra de discuter des habitudes de chacun.","question":"Quelle obligation accompagne l'hébergement ?","options":["Verser un salaire à l'hôte","Assurer des soins quotidiens","Être présent certains soirs","Travailler toutes les nuits"],"correct":"C","explanation":"Le passage indique : « Annonce : chambre meublée chez une retraitée, contre une présence deux soirs par semaine. Il ne s'agit pas d'un emploi d'aide à domicile. Les tâches médicales sont exclues. » Cela justifie la réponse : Être présent certains soirs."},{"number":10,"points":9,"passage":"Nous avons avancé la réunion de copropriété à dix-huit heures pour permettre aux parents d'y assister avant la sortie des activités des enfants. L'ordre du jour reste inchangé.\n\nLes documents seront envoyés auparavant pour que chacun puisse les lire.","question":"Pourquoi l'horaire a-t-il été modifié ?","options":["Faciliter la participation des parents","Terminer des travaux urgents","Réduire le nombre de participants","Ajouter un vote supplémentaire"],"correct":"A","explanation":"Le passage indique : « Nous avons avancé la réunion de copropriété à dix-huit heures pour permettre aux parents d'y assister avant la sortie des activités des enfants. L'ordre du jour reste inchangé. » Cela justifie la réponse : Faciliter la participation des parents."},{"number":11,"points":15,"passage":"Dans cet immeuble, une buanderie commune remplace les machines individuelles. Chaque foyer réserve un créneau. Les appareils sont mieux utilisés, mais les retards créent parfois des tensions entre voisins.\n\nLe conseil a donc installé un tableau rappelant les heures de début et de fin. Les habitants peuvent échanger leur réservation s'ils préviennent la personne suivante. Une réunion permettra de discuter des incidents après un mois d'essai. Plusieurs familles apprécient déjà de ne plus devoir entretenir une grosse machine dans leur appartement. La réussite du service dépend cependant des petites attentions de chacun, notamment du nettoyage après utilisation.","question":"Quelle difficulté est signalée ?","options":["L'interdiction de laver chez soi","L'absence totale de réservation","La consommation excessive de papier","Le non-respect des créneaux"],"correct":"D","explanation":"Le passage indique : « Dans cet immeuble, une buanderie commune remplace les machines individuelles. Chaque foyer réserve un créneau. Les appareils sont mieux utilisés, mais les retards créent parfois des tensions entre voisins. » Cela justifie la réponse : Le non-respect des créneaux."},{"number":12,"points":15,"passage":"La mairie prête des outils aux résidents après une courte démonstration. Les bénévoles ne réalisent pas les travaux : ils montrent comment utiliser le matériel en sécurité. Les emprunteurs rapportent les outils propres.\n\nUne carte d'adhésion permet d'emprunter jusqu'à trois outils pour une semaine. Les appareils les plus délicats ne sont remis qu'après vérification des consignes. L'association a choisi de demander une participation annuelle modeste plutôt que de facturer chaque prêt.","question":"Quel est le rôle des bénévoles ?","options":["Vérifier les déclarations fiscales","Vendre les outils aux habitants","Expliquer l'utilisation du matériel","Rénover gratuitement les logements"],"correct":"C","explanation":"Le passage indique : « La mairie prête des outils aux résidents après une courte démonstration. Les bénévoles ne réalisent pas les travaux : ils montrent comment utiliser le matériel en sécurité. Les emprunteurs rapportent les outils propres. » Cela justifie la réponse : Expliquer l'utilisation du matériel."},{"number":13,"points":15,"passage":"Un ancien hôtel devient une résidence étudiante. Les chambres sont petites, mais chaque étage dispose d'une cuisine et d'un salon. La transformation conserve la structure du bâtiment au lieu de le démolir.\n\nLes architectes ont aussi gardé le grand escalier et créé des rangements individuels. Une association étudiante animera quelques soirées pendant les premiers mois, sans rendre la présence obligatoire. Les futurs locataires pourront visiter un étage témoin avant de déposer leur dossier. La ville espère ainsi proposer des chambres moins coûteuses tout en limitant la consommation de nouveaux matériaux.","question":"Quel choix guide le projet ?","options":["Réserver l'hôtel aux touristes","Construire des maisons séparées","Réutiliser un bâtiment existant","Supprimer les espaces communs"],"correct":"C","explanation":"Le passage indique : « Un ancien hôtel devient une résidence étudiante. Les chambres sont petites, mais chaque étage dispose d'une cuisine et d'un salon. La transformation conserve la structure du bâtiment au lieu de le démolir. » Cela justifie la réponse : Réutiliser un bâtiment existant."},{"number":14,"points":15,"passage":"Sarah a emménagé sans voiture. Elle a choisi un appartement près de la gare, puis vendu plusieurs meubles trop grands. Elle constate qu'un logement plus petit lui demande moins d'entretien.\n\nElle a d'abord craint de manquer de place pour recevoir ses proches. Elle a finalement choisi une table pliante et utilise une chambre d'amis partagée dans la résidence lorsque sa famille reste dormir. Son budget de transport a également diminué. Elle ne présente pas son choix comme une solution convenant à tout le monde, mais comme un équilibre adapté à sa situation actuelle.","question":"Quel avantage Sarah découvre-t-elle ?","options":["Une pièce supplémentaire","Des meubles plus volumineux","Un garage gratuit","Un entretien moins important"],"correct":"D","explanation":"Le passage indique : « Sarah a emménagé sans voiture. Elle a choisi un appartement près de la gare, puis vendu plusieurs meubles trop grands. Elle constate qu'un logement plus petit lui demande moins d'entretien. » Cela justifie la réponse : Un entretien moins important."},{"number":15,"points":15,"passage":"Le comité de quartier organise une marche avec les nouveaux habitants. Les participants repèrent ensemble les commerces, les arrêts de bus et les services publics. Aucun circuit touristique payant n'est prévu.\n\nLes départs se font depuis le centre social et les circuits restent assez courts. Un bénévole répond aux questions pratiques, tandis que des commerçants présentent leurs services habituels. Les participants reçoivent une petite carte sur laquelle ils peuvent ajouter leurs propres repères. Le comité veut faciliter les premiers échanges entre voisins, sans demander aux nouveaux arrivants de connaître déjà quelqu'un.","question":"À quoi sert cette marche ?","options":["Collecter une taxe locale","Visiter seulement des monuments","Découvrir les services du quotidien","Vendre des abonnements touristiques"],"correct":"C","explanation":"Le passage indique : « Le comité de quartier organise une marche avec les nouveaux habitants. Les participants repèrent ensemble les commerces, les arrêts de bus et les services publics. Aucun circuit touristique payant n'est prévu. » Cela justifie la réponse : Découvrir les services du quotidien."},{"number":16,"points":15,"passage":"Une agence met en ligne les dépenses de chauffage des logements proposés. Les chiffres correspondent à une occupation habituelle ; ils ne garantissent pas une facture identique pour chaque locataire.\n\nLa température choisie, les absences et le nombre d'occupants modifient les besoins. Un logement montré vide peut aussi avoir été chauffé différemment. L'agence précise donc la période mesurée et la méthode utilisée. Les visiteurs sont invités à poser des questions sur l'isolation, plutôt qu'à retenir le seul montant affiché en tête de l'annonce.","question":"Comment faut-il interpréter ces chiffres ?","options":["Comme une indication dépendant de l'usage","Comme un prix fixe garanti","Comme le montant du dépôt","Comme une consommation toujours nulle"],"correct":"A","explanation":"Le passage indique : « Une agence met en ligne les dépenses de chauffage des logements proposés. Les chiffres correspondent à une occupation habituelle ; ils ne garantissent pas une facture identique pour chaque locataire. » Cela justifie la réponse : Comme une indication dépendant de l'usage."},{"number":17,"points":15,"passage":"Lors des fortes chaleurs, la salle commune reste ouverte jusqu'à vingt-deux heures. Les résidents isolés peuvent s'y retrouver et boire de l'eau. L'accès ne nécessite pas de réservation.\n\nDes bénévoles passent proposer cet accueil aux personnes qui le souhaitent, sans les inscrire d'office. Une petite bibliothèque et des jeux sont disponibles, mais chacun peut simplement rester assis dans un lieu moins chaud. Le conseil des résidents évaluera le dispositif après l'été. Il regardera notamment si les horaires correspondent réellement aux besoins et si les personnes ayant du mal à marcher peuvent rejoindre facilement la salle commune.","question":"À qui cette mesure peut-elle particulièrement servir ?","options":["Aux propriétaires vendant leur logement","Aux résidents isolés pendant la chaleur","Aux touristes réservant une chambre","Aux automobilistes cherchant un parking"],"correct":"B","explanation":"Le passage indique : « Lors des fortes chaleurs, la salle commune reste ouverte jusqu'à vingt-deux heures. Les résidents isolés peuvent s'y retrouver et boire de l'eau. L'accès ne nécessite pas de réservation. » Cela justifie la réponse : Aux résidents isolés pendant la chaleur."},{"number":18,"points":15,"passage":"La fête des voisins aura lieu dans le hall si la pluie persiste. Les organisateurs ont renoncé à installer une tente, car elle bloquerait l'accès des secours dans la cour.\n\nLa fête se tiendra donc près de l'entrée, où les tables peuvent être déplacées rapidement. Les voisins sont invités à apporter des plats froids pour éviter un équipement de cuisson encombrant. Une équipe vérifiera que les portes restent dégagées. Les organisateurs préfèrent modifier quelques habitudes plutôt que renoncer à accueillir tout le monde, y compris les personnes utilisant un fauteuil ou une poussette.","question":"Pourquoi la tente a-t-elle été écartée ?","options":["Elle gênerait un passage de sécurité","Elle empêcherait toute musique","Elle coûterait plus que le repas","Elle manquerait de places assises"],"correct":"A","explanation":"Le passage indique : « La fête des voisins aura lieu dans le hall si la pluie persiste. Les organisateurs ont renoncé à installer une tente, car elle bloquerait l'accès des secours dans la cour. » Cela justifie la réponse : Elle gênerait un passage de sécurité."},{"number":19,"points":15,"passage":"Après plusieurs plaintes sur le bruit, les habitants ont choisi une médiatrice. Elle reçoit séparément les personnes concernées avant de proposer un échange commun. Elle ne peut pas imposer une amende.\n\nLa première séance permettra surtout de préciser les horaires et les situations qui provoquent les désaccords. Chaque voisin pourra expliquer ce qu'il entend depuis son appartement et proposer un arrangement réaliste. Un document commun ne sera rédigé que si les personnes l'acceptent.","question":"Quelle est sa mission ?","options":["Décider du montant des loyers","Remplacer le gardien de nuit","Faciliter un accord entre voisins","Sanctionner immédiatement les habitants"],"correct":"C","explanation":"Le passage indique : « Après plusieurs plaintes sur le bruit, les habitants ont choisi une médiatrice. Elle reçoit séparément les personnes concernées avant de proposer un échange commun. Elle ne peut pas imposer une amende. » Cela justifie la réponse : Faciliter un accord entre voisins."},{"number":20,"points":21,"passage":"Une coopérative d'habitation achète un terrain pour y construire des logements et une salle partagée. Les futurs habitants participeront aux décisions. Leur contribution financière ne leur donnera pas davantage de voix lors des assemblées. Les membres prépareront ensemble les règles d'utilisation des espaces partagés. Certaines dépenses seront mutualisées, mais chaque ménage conservera son logement privé. Des réunions ouvertes permettront aux nouveaux participants de comprendre le fonctionnement avant de confirmer leur engagement. Le groupe cherche une solution durable plutôt qu'un simple placement immobilier individuel. Les comptes seront présentés régulièrement à tous les membres du groupe.","question":"Quel principe est retenu ?","options":["La suppression des assemblées","Des votes proportionnels à la richesse","Une participation sans domination financière","La réservation des décisions aux investisseurs"],"correct":"C","explanation":"Le passage indique : « Une coopérative d'habitation achète un terrain pour y construire des logements et une salle partagée. Les futurs habitants participeront aux décisions. Leur contribution financière ne leur donnera pas davantage de voix lors des assemblées. » Cela justifie la réponse : Une participation sans domination financière."},{"number":21,"points":21,"passage":"Un quartier teste la livraison des courses à pied depuis ses commerces. Le service vise surtout les personnes qui se déplacent difficilement. Les commerçants restent responsables des commandes ; les livreurs ne choisissent pas les produits à la place des clients. Les personnes passent leur commande auprès de leur boutique habituelle et choisissent un horaire de réception. La commune prend en charge une partie du transport pendant l'expérimentation. Une permanence téléphonique est maintenue pour celles qui n'utilisent pas internet.","question":"Que permet principalement ce service ?","options":["Remplacer les achats par des dons","Faciliter l'accès aux commerces locaux","Décider des menus des clients","Fermer les boutiques de proximité"],"correct":"B","explanation":"Le passage indique : « Un quartier teste la livraison des courses à pied depuis ses commerces. Le service vise surtout les personnes qui se déplacent difficilement. Les commerçants restent responsables des commandes ; les livreurs ne choisissent pas les produits à la place des clients. » Cela justifie la réponse : Faciliter l'accès aux commerces locaux."},{"number":22,"points":21,"passage":"Dans une résidence rénovée, des capteurs signalent les fuites d'eau sans enregistrer les habitudes détaillées des occupants. Le conseil des locataires a demandé cette limitation avant d'accepter le dispositif. Les alertes sont envoyées au service technique. Le système indique seulement le secteur où une intervention semble nécessaire. Les données sont effacées après un délai annoncé. Le bailleur souhaite limiter les dégâts matériels tout en évitant qu'un outil d'entretien devienne un moyen de surveiller la vie domestique.","question":"Quelle préoccupation a influencé le dispositif ?","options":["La suppression de l'entretien","L'augmentation du débit d'eau","Le contrôle des visiteurs","La protection de la vie privée"],"correct":"D","explanation":"Le passage indique : « Dans une résidence rénovée, des capteurs signalent les fuites d'eau sans enregistrer les habitudes détaillées des occupants. Le conseil des locataires a demandé cette limitation avant d'accepter le dispositif. Les alertes sont envoyées au service technique. » Cela justifie la réponse : La protection de la vie privée."},{"number":23,"points":21,"passage":"Une commune réserve des appartements aux travailleurs saisonniers. Les locations touristiques avaient rendu leur recherche difficile. Les logements seront occupés l'hiver par des stagiaires, afin d'éviter qu'ils restent vides plusieurs mois. Les associations de commerçants ont soutenu le projet après avoir constaté plusieurs recrutements abandonnés faute de logement. La mairie ne promet pas une réponse à toutes les demandes : les places disponibles seront attribuées selon des critères publiés. Un bilan annuel précisera si l'alternance des publics correspond effectivement aux besoins recensés.","question":"Quelle logique suit la commune ?","options":["Adapter l'occupation à différents besoins annuels","Interdire toutes les locations touristiques","Fermer les appartements après l'été","Réserver les logements aux retraités"],"correct":"A","explanation":"Le passage indique : « Une commune réserve des appartements aux travailleurs saisonniers. Les locations touristiques avaient rendu leur recherche difficile. Les logements seront occupés l'hiver par des stagiaires, afin d'éviter qu'ils restent vides plusieurs mois. » Cela justifie la réponse : Adapter l'occupation à différents besoins annuels."},{"number":24,"points":21,"passage":"Un collectif transforme un parking inutilisé en place de quartier. Les habitants pourront déplacer les bancs avant l'aménagement définitif. La commune veut observer les usages plutôt que choisir immédiatement une configuration permanente. Les premiers essais auront lieu pendant plusieurs semaines, en dehors des grands événements. Les personnes âgées et les parents pourront notamment indiquer les zones trop bruyantes ou trop exposées. Les agents observeront aussi les passages nécessaires aux livraisons.","question":"Pourquoi les bancs seront-ils mobiles ?","options":["Pour tester plusieurs aménagements","Pour éviter toute observation","Pour les louer chaque soir","Pour empêcher les rencontres"],"correct":"A","explanation":"Le passage indique : « Un collectif transforme un parking inutilisé en place de quartier. Les habitants pourront déplacer les bancs avant l'aménagement définitif. La commune veut observer les usages plutôt que choisir immédiatement une configuration permanente. » Cela justifie la réponse : Pour tester plusieurs aménagements."},{"number":25,"points":21,"passage":"Le bailleur d’une résidence propose de remplacer une réunion sur deux par un questionnaire, disponible sur papier et en ligne. Les réponses placent la peinture des couloirs devant la réparation de la porte d’entrée. Lors d’un échange, une locataire explique que la porte trop lourde l’empêche de sortir seule. Plusieurs voisins changent alors leur ordre de priorité, tout en souhaitant toujours repeindre les couloirs. Aucun nouveau vote n’a été organisé. Les réponses papier et numériques présentaient pourtant le même classement. Les représentants acceptent de conserver le formulaire pour préparer les rencontres, mais refusent que son résultat décide directement des travaux. Le bailleur espérait surtout raccourcir les réunions ; ils lui proposent de réserver ce temps aux situations que les réponses individuelles rendent difficiles à apprécier.","question":"Qu’attendent surtout les représentants de l’échange qui suit le questionnaire ?","options":["Qu’il corrige un classement déformé par l’accès inégal aux supports de consultation.","Qu’il départage des priorités concurrentes par un nouveau vote après le questionnaire.","Qu’il confirme les travaux majoritaires avant d’en discuter les modalités pratiques.","Qu’il permette de revoir les priorités en confrontant les situations des locataires."],"correct":"D","explanation":"D. L’explication de la difficulté à sortir conduit certains voisins à placer la porte avant la peinture. L’échange sert donc à reconsidérer les priorités. A attribue le changement aux supports, dont les résultats concordaient ; B suppose un nouveau vote qui n’a pas eu lieu ; C transforme le classement initial en décision déjà acquise."},{"number":26,"points":21,"passage":"Le projet de rénovation d’une rue prévoit trente arbres dans de petites fosses séparées par des conduites. Le même budget permettrait d’en planter vingt-deux dans des bandes de terre continues, à condition de déplacer six places de stationnement. D’après les essais du service technique, les espèces retenues supportent bien la chaleur dans les deux configurations, mais leurs racines se développent moins dans les fosses. Déplacer les conduites coûterait davantage que l’enveloppe prévue. Les riverains ont longtemps défendu le chiffre de trente ; ils soutiennent finalement la seconde solution. Ils demandent toutefois que les bandes soient aménagées avant la plantation et que les arbres remplacés durant les premières années figurent dans le bilan public.","question":"Quel arbitrage explique le changement de position des riverains ?","options":["Réduire le nombre de plantations pour maintenir le stationnement dans son état actuel.","Réduire le nombre initial d’arbres pour financer des conditions de croissance plus favorables.","Conserver les petites fosses en privilégiant des espèces mieux adaptées aux fortes chaleurs.","Reporter les plantations pour consacrer d’abord le budget au déplacement des conduites."],"correct":"B","explanation":"B. À budget égal, les habitants retiennent moins d’arbres mais davantage de terre disponible pour les racines. A inverse l’effet sur le stationnement. C déplace le problème vers les espèces, adaptées à la chaleur dans les deux cas. D reprend une solution dont le coût dépasse le budget et qui n’est pas retenue."},{"number":27,"points":21,"passage":"Après le regroupement des poubelles d’une résidence en un point unique, les ordures résiduelles pèsent vingt pour cent de moins. Le conseil annonce que les habitants produisent moins de déchets. Or, pendant les mêmes semaines, les bacs de recyclage ont reçu presque autant de kilos supplémentaires. Les agents ont pesé les deux catégories sur des périodes de même durée. Une vérification des corbeilles de la rue ne révèle pas d’augmentation liée à la résidence. Les nouvelles consignes expliquaient surtout quels emballages déposer dans chaque bac ; elles ne proposaient pas de modifier les achats. Le conseil souhaite maintenir l’installation, mais l’équipe chargée du bilan lui demande de changer la formulation de son annonce.","question":"Quelle interprétation correspond le mieux aux mesures réalisées après le changement ?","options":["Le déplacement des dépôts vers la rue explique une partie de la baisse des ordures.","Le changement de période de collecte accentue la diminution apparente des déchets.","La réorientation des emballages vers le recyclage explique l’essentiel de la baisse observée.","La diminution des achats emballés réduit la masse des déchets dans la résidence."],"correct":"C","explanation":"C. La baisse des ordures résiduelles est presque compensée par la hausse du recyclage : la répartition change davantage que la quantité totale. A est contredit par les contrôles dans la rue ; B par les périodes identiques ; D prête aux consignes et aux mesures un effet sur les achats qu’elles n’établissent pas."},{"number":28,"points":21,"passage":"Dans un quartier en pente, des bénévoles accompagnent des personnes âgées au marché. Au début, la règle leur interdisait de faire les achats à leur place : préserver l’autonomie signifiait que chacun devait parcourir les étals. Une bénéficiaire a expliqué qu’un jour de douleur, elle préférait choisir ses produits sur une liste et demander qu’on les lui rapporte. Une autre tenait à marcher, même lentement. Le service autorise désormais ces deux formules, décidées avec la personne avant chaque sortie. Les bénévoles continuent à porter les sacs et peuvent conseiller un itinéraire, mais ils ne choisissent ni le budget ni la formule d’aide sans l’accord du bénéficiaire. La durée reste adaptée à chaque sortie, plutôt qu’inscrite dans une tournée de durée commune. Le nombre de sorties à pied n’est donc plus son seul indicateur de réussite.","question":"Quel partage des rôles résulte de la révision du service ?","options":["La personne choisit les commerces à visiter ; le bénévole répartit ensuite le budget entre les achats.","La personne choisit ses achats ; la part de leur réalisation confiée au bénévole varie selon la sortie.","La personne fixe le budget ; le bénévole compose ensuite la liste selon les commerces accessibles.","La personne choisit la formule d’aide ; le bénévole inscrit la sortie dans une durée commune aux bénéficiaires."],"correct":"B","explanation":"B. Les produits et le budget restent choisis par la personne, qui peut demander une aide matérielle différente selon le jour. A attribue au bénévole la répartition du budget ; C lui confie la liste des produits ; D introduit une durée commune, alors que les sorties restent adaptées individuellement."},{"number":29,"points":21,"passage":"Une cour d’école ouvrira aux riverains le week-end : ateliers associatifs le samedi, accueil libre le dimanche. La commune et l’association locale partageront à parts égales le nettoyage du dimanche soir, quel que soit le nombre de visiteurs. Les parents demandent que les élèves retrouvent le lieu propre le lundi. L’association accepte cette exigence, mais refuse de payer la réparation de dégradations qui pourraient dater de la semaine scolaire. Un état des lieux commun sera établi le vendredi après la dernière classe, puis le lundi avant la reprise des cours et après le nettoyage. Aucun contrôle intermédiaire n’est prévu entre les deux usages du week-end. Les réparations imputées à l’ouverture devront s’appuyer sur cette comparaison. Le calendrier d’essai reste limité à six week-ends ; son prolongement dépendra de l’état de la cour à la reprise des cours.","question":"Quelle distinction les deux états des lieux permettent-ils d’établir dans cet accord ?","options":["Les dégâts des ateliers du samedi, séparés de ceux de l’accueil libre du dimanche.","Les dégâts de l’accueil dominical, séparés de ceux de la reprise scolaire du lundi.","Les dégâts d’une semaine scolaire, séparés de ceux qui étaient présents à la rentrée du lundi.","Les dégâts de la période d’ouverture, séparés de l’état laissé par l’école avant le week-end."],"correct":"D","explanation":"D. Le constat du vendredi, après les classes, sert de référence ; celui du lundi, avant les cours, mesure l’état rendu après tout le week-end. A exigerait un contrôle entre samedi et dimanche. B exigerait un contrôle après la reprise scolaire du lundi. C exigerait une comparaison du lundi au vendredi d’une même semaine. Les deux constats prévus ne couvrent aucune de ces trois périodes."},{"number":30,"points":26,"passage":"À l'ouverture d'une résidence, un salon équipé devait favoriser les rencontres. Un groupe d'amis y jouait aux cartes, sans attirer d'autres habitants. Le conseil a ajouté des fauteuils et un programme d'activités sur inscription; la fréquentation a peu changé. Deux résidentes ont ensuite proposé un café où chacun pouvait passer brièvement, sans inscription ni engagement à revenir. De nouveaux voisins sont alors entrés. Le conseil a conservé ce format et comparé deux types de séances. Dans les unes, une résidente présentait les personnes arrivées seules à d'autres visiteurs; dans les autres, elle se contentait d'ouvrir la salle. Les relevés montrent des nombres comparables de nouveaux venus, des durées de visite semblables et une même fréquence de retour. Le suivi des échanges fait pourtant apparaître davantage d'entraide après les séances avec présentation. Il distingue les liens antérieurs: l'écart concerne surtout des personnes qui ne se connaissaient pas avant le café. La sociologue rapproche ces résultats du premier changement. Elle invite à distinguer le fait d'entrer dans un lieu ouvert et ce qui peut ensuite s'y nouer.","question":"Quelle interprétation respecte le rôle distinct des changements étudiés dans cette résidence ?","options":["L'accès libre élargit le public; l’accueil organisé favorise ensuite l'entraide entre des visiteurs qui ne se connaissaient pas auparavant.","L'accès libre renouvelle le public; l’accueil organisé développe ensuite l'entraide en réunissant plus souvent des voisins qui se connaissaient déjà.","L'accès libre prolonge les visites; l’accueil organisé développe ensuite l'entraide en augmentant le nombre de voisins qui découvrent les lieux.","L'accès libre élargit le public; l’accueil organisé favorise ensuite l'entraide en augmentant le nombre de visites effectuées par chaque participant."],"correct":"A","explanation":"A. L'accès sans inscription fait d'abord venir de nouveaux habitants. Dans la comparaison suivante, l'accueil organisé est associé à davantage d'entraide entre personnes auparavant inconnues, avec des nombres de nouveaux venus, des durées de visite et des fréquences de retour comparables. B attribue le résultat aux liens préexistants, alors que l'écart concerne surtout des inconnus. C introduit un allongement initial des visites non établi, puis une hausse des nouveaux participants absente de la comparaison. D suppose davantage de retours, contrairement aux relevés. Il faut distinguer l'élargissement du public et la formation de liens entre ses membres."},{"number":31,"points":26,"passage":"La mairie présente cent façades rénovées et une baisse des factures de chauffage comme les réussites de son programme. Le suivi détaille les logements rénovés et un groupe d’immeubles voisins non rénovés. Une réduction du tarif de l’énergie explique une partie de l’économie financière. Une fois les tarifs neutralisés, les quantités consommées baissent encore, dans des proportions voisines pour les deux groupes. L’hiver a été plus doux que le précédent. Les ménages sont restés les mêmes, leurs périodes d’occupation n’ont pas changé et les relevés de thermostat montrent des températures de consigne stables. Les travaux comportaient pourtant une amélioration des fenêtres ; l’urbaniste ne nie donc pas qu’ils puissent avoir un effet. Il demande un suivi pendant plusieurs saisons avant de chiffrer cet effet. La contribution financière demandée aux locataires sera également étudiée, dans un volet séparé sur leur budget total.","question":"Quelle explication des chiffres conduit l’urbaniste à différer son estimation de l’effet des travaux ?","options":["La baisse du tarif a réduit les factures, tandis que les volumes d’énergie consommés sont restés stables.","Une présence moins fréquente des occupants a réduit les besoins, sans amélioration comparable de l’isolation.","Un abaissement des températures demandées a réduit les consommations, indépendamment du remplacement des fenêtres.","Un hiver moins froid a réduit les besoins, dans les immeubles rénovés comme dans les bâtiments de comparaison."],"correct":"D","explanation":"D. Après neutralisation du tarif, les consommations baissent dans les deux groupes pendant un hiver plus doux : l’effet propre des travaux n’est pas isolé. A conserve à tort des volumes stables. B et C proposent deux causes plausibles en général, mais les périodes d’occupation et les consignes de thermostat sont restées inchangées."},{"number":32,"points":26,"passage":"Un café accueille gratuitement des réunions associatives les mardis et jeudis soirs. Les participants peuvent consommer, mais aucun achat n’est exigé. Le gérant couvre les frais par les recettes ordinaires et par la location de la salle à des groupes privés le samedi. Après plusieurs réunions très fréquentées, une association demande tous les samedis du mois. Le gérant propose deux créneaux supplémentaires en semaine, tout en refusant cette réservation régulière. La salle peut accueillir les mêmes effectifs chaque jour ; le personnel nécessaire coûterait également le même montant. Dans son bilan, les ventes ordinaires restent comparables selon les jours et les réunions gratuites n’ont pas entraîné de hausse nette des ventes, malgré l’arrivée de nouveaux habitués : ceux-ci utilisent surtout le lieu pour se rencontrer. Les locations du samedi, en revanche, ont dégagé la marge qui a permis d’ajouter les soirées ouvertes sans augmenter les prix du café.","question":"Quelle différence entre les samedis et les soirs de semaine explique la décision du gérant ?","options":["Le samedi, la capacité de la salle limite les groupes accueillis ; en semaine, davantage de places restent disponibles.","Le samedi, les ventes ordinaires procurent une marge supérieure ; en semaine, les réunions remplacent une faible consommation.","Le samedi, les locations apportent la marge utilisée pour les réunions ; en semaine, ces recettes ne sont pas sacrifiées.","Le samedi, le personnel représente un coût supérieur ; en semaine, le même accueil demande une dépense moindre."],"correct":"C","explanation":"C. La marge des locations du samedi finance les réunions ouvertes; ajouter des créneaux en semaine permet de conserver cette recette. A fait de la disponibilité des places la raison du refus, alors que cette différence de disponibilité n'est pas documentée et que le bilan identifie la marge des locations. B attribue aux ventes ordinaires une différence selon les jours que le bilan écarte. D contredit les coûts de personnel identiques."},{"number":33,"points":26,"passage":"Une résidence de petits logements propose une laverie, un prêt d'outils et du stockage pour compenser la surface réduite. Une contribution mensuelle à ces services est incluse dans les charges; l'utilisation de la laverie commune n'entraîne ensuite aucun paiement à l'acte. Avant la location, le bailleur établit un budget personnalisé à partir des anciens relevés de dépenses. Son estimation intègre la contribution commune et prévoit deux économies: un poste logement-chauffage moins élevé et la disparition des factures de laverie extérieure. Une enquêtrice suit ensuite deux habitantes qui font chacune quatre lessives par mois. La première peut utiliser la laverie commune; la seconde rentre après sa fermeture et continue à aller à l'extérieur. Leurs nouvelles charges comprennent la même contribution et les économies de logement-chauffage prévues sont observées. Pour comprendre pourquoi le second budget dépasse l'estimation, l'enquêtrice reprend aussi les dossiers antérieurs. Les deux habitantes payaient déjà leurs quatre lavages à l'extérieur avant le déménagement. Pour la seconde, les factures actuelles présentent le même nombre de lavages et le même prix qu'auparavant. Aucune réduction de sa contribution commune n'est prévue en cas de non-utilisation.","question":"Quelle analyse explique l’écart entre les dépenses de la seconde habitante et le budget qui lui avait été annoncé ?","options":["La baisse du poste logement est réalisée, mais une dépense extérieure apparue après le déménagement réduit le gain prévu sur les services collectifs.","La baisse du poste logement est réalisée, mais la dépense extérieure déjà présente auparavant empêche d'obtenir l'économie prévue sur la lessive.","La baisse du poste logement est réalisée, mais la contribution aux services, absente de l'estimation initiale, réduit le gain prévu pour les habitantes.","La baisse du poste logement est réalisée, mais la hausse du tarif extérieur absorbe une partie de l'économie prévue à fréquence de lavage stable."],"correct":"B","explanation":"B. Le budget annonçait la disparition des factures de laverie extérieure et intégrait déjà la contribution commune. Or, la seconde habitante continue de payer les mêmes lavages qu'avant le déménagement, au même prix: une économie prévue ne se réalise pas. La baisse des dépenses de logement-chauffage reste, elle, observée. A transforme une dépense ancienne maintenue en dépense apparue après le déménagement. C présente comme oubliée une contribution déjà incluse dans l'estimation. D suppose une hausse de tarif alors que le nombre et le prix des lavages restent identiques. Il faut comparer l'ancienne situation, la prévision et les dépenses réelles."},{"number":34,"points":26,"passage":"La ville attribuait ses jardins selon l’ancienneté de la demande. Les mêmes ménages conservaient ensuite leur parcelle tant qu’ils la cultivaient. Le nouveau règlement garantit aux titulaires actuels trois saisons supplémentaires : ils pourront ainsi récolter ce qu’ils ont planté et préparer une transmission. Après cette période, une partie des parcelles sera remise en jeu chaque année. Pour les nouvelles attributions, la moitié sera réservée aux ménages sans espace extérieur ; l’autre moitié suivra la liste d’attente. Des inscrits de longue date dénoncent une rupture de promesse. La mairie répond qu’elle protège le travail déjà commencé, mais qu’elle n’assimile plus le temps passé sur une liste à un droit prioritaire sur chaque parcelle. Elle maintient néanmoins une voie d’accès fondée sur l’attente, afin que la prise en compte des besoins n’efface pas toutes les attentes antérieures.","question":"Quelle lecture des règles correspond au nouveau dispositif d’attribution ?","options":["La transition protège l’ancienneté des titulaires ; le partage privilégie ensuite les plus anciens candidats sans extérieur.","La transition protège les titulaires sans extérieur ; le partage équilibre ensuite nouvelles demandes et renouvellements.","La transition protège les investissements les plus récents ; le partage répartit ensuite les parcelles selon le temps d’attente.","La transition protège les cultures engagées ; le partage maintient ensuite deux voies, selon le besoin et selon l’attente."],"correct":"D","explanation":"D. Les trois saisons permettent aux titulaires actuels de récolter et préparer une transmission ; les nouvelles attributions passent ensuite pour moitié par le besoin d’extérieur et pour moitié par l’attente. A fusionne besoin et ancienneté en une seule priorité. B réserve à tort la transition aux titulaires sans extérieur. C limite la transition aux investissements récents et rétablit l’attente comme critère général."},{"number":35,"points":26,"passage":"Dans une rue commerçante, les habitants se plaignaient des livraisons à l’aube, des terrasses tardives et d’un moteur de ventilation. L’association de quartier a refusé de demander une heure de fermeture identique pour tous les établissements. Un accord a regroupé les livraisons de trois boutiques après sept heures ; un café a avancé le rangement de sa terrasse, tout en gardant sa salle ouverte. Le moteur, qui fonctionnait également lorsque la boutique était fermée, a été isolé. Les relevés aux fenêtres ont ensuite diminué, sans disparition d’un commerce. L’association demande que chaque nouvel accord comporte une vérification au domicile des habitants exposés. Un atelier souhaite maintenant s’installer : il ne recevra aucune livraison matinale et n’aura pas de terrasse, mais son extracteur fonctionnera en continu. Ses machines de réparation seront arrêtées le soir, contrairement à cet équipement. Les riverains veulent conserver le service de réparation proposé. Certains suggèrent de lui appliquer l’horaire du café ; d’autres proposent une contribution à un fonds commun pour les travaux d’isolation futurs.","question":"Quel engagement demander à l’atelier serait cohérent avec la méthode et les constats présentés ?","options":["Avancer la fermeture de l’atelier, puis comparer le bruit avant et après ce changement dans les logements voisins.","Isoler acoustiquement l’extracteur, puis comparer le bruit avant et après les travaux dans les logements voisins.","Regrouper les livraisons sur un autre créneau, puis comparer le bruit avant et après ce changement dans les logements voisins.","Installer des supports amortissants sous les machines de réparation, puis comparer le bruit avant et après les travaux dans les logements voisins."],"correct":"B","explanation":"B. Une isolation acoustique de l’extracteur traite l’équipement qui restera en fonctionnement quand les machines et l’atelier seront arrêtés, comme le moteur du précédent accord. Les quatre engagements prévoient le même contrôle chez les voisins. A, C et D ciblent respectivement les horaires, les livraisons et les machines, qui ne sont pas la source continue identifiée."},{"number":36,"points":33,"passage":"Une coopérative municipale propose deux appartements semblables dans chacune des résidences Centre et Parc. Le loyer, charges et chauffage compris, est de 800 euros à Centre et de 600 euros à Parc, contre environ 1 000 euros dans les annonces privées comparables. La brochure qualifie donc les deux résidences d’« abordables ». Pour préparer des exemples personnalisés, la ville étudie les dossiers de deux ménages admis au programme. Celui d’Aïcha dispose de 1 800 euros nets par mois ; celui de Rémi, de 2 100 euros. Dans leurs prévisions, chacun réserve 1 000 euros à l’alimentation, à l’habillement et aux autres dépenses courantes, après paiement du logement et des trajets professionnels. Aïcha travaille au centre-ville : elle irait à pied depuis Centre. Depuis Parc, le dernier bus part avant la fin de son service ; ses trajets en voiture lui reviendraient à 250 euros par mois. Rémi travaille sur le site d’activités voisin de Parc et pourrait s’y rendre à pied. Depuis Centre, ses déplacements lui coûteraient 350 euros par mois, une fois déduite la participation de son employeur. Les deux ménages peuvent choisir l’une ou l’autre résidence ; le service municipal doit maintenant compléter les simulations.","question":"Quelle répartition des logements respecterait les budgets prévus par les deux ménages ?","options":["Centre pour Aïcha et Parc pour Rémi.","Parc pour Aïcha et Centre pour Rémi.","Centre pour Aïcha et pour Rémi.","Parc pour Aïcha et pour Rémi."],"correct":"A","explanation":"A. Après le logement et les trajets, Aïcha garderait 1 000 euros à Centre, contre 950 euros à Parc ; Rémi garderait 1 500 euros à Parc, contre 950 euros à Centre. Chacun a prévu 1 000 euros pour ses autres dépenses. B placerait donc les deux ménages sous ce montant. C conviendrait à Aïcha, mais laisserait Rémi avec 950 euros. D conviendrait à Rémi, mais laisserait Aïcha avec 950 euros. Le loyer inférieur de Parc ne compense pas, pour Aïcha, les frais de trajet ajoutés."},{"number":37,"points":33,"passage":"Le conseil d’une résidence a renoncé à rendre le dîner hebdomadaire obligatoire. Les horaires de travail et les préférences des habitants variaient trop. Chacun peut désormais venir au repas, préparer une liste de courses, arroser le potager ou aider ponctuellement un voisin. Deux mois plus tard, les contributions se sont diversifiées et les échanges hors des repas ont augmenté. Pourtant, la lettre de la résidence félicite les « piliers de la vie collective » en citant presque exclusivement les personnes présentes à table. Une habitante qui travaille le soir et organise les achats est rarement nommée. Les réunions de préparation se tiennent à des horaires alternés et les tâches de cuisine sont réparties entre plusieurs volontaires ; ces changements ont levé des difficultés réelles. Lors du bilan, une médiatrice s’arrête néanmoins sur le choix des personnes citées dans la lettre. Elle ne demande pas le retour à une participation identique, mais invite le conseil à examiner ce que ses marques de reconnaissance font comprendre aux nouveaux arrivants.","question":"Quelle réserve la médiatrice formule-t-elle implicitement sur le fonctionnement actuel ?","options":["La possibilité de choisir sa contribution reste limitée par les horaires fixes de préparation.","La variété des tâches proposées dissimule une charge de cuisine toujours concentrée sur les mêmes.","Les contributions sont reconnues en principe, mais leur visibilité au repas continue de les hiérarchiser.","La souplesse de participation a développé l’entraide pratique au détriment des relations de voisinage."],"correct":"C","explanation":"C. Les formes d’engagement se diversifient réellement, mais la lettre continue de désigner surtout les convives comme acteurs essentiels. A et B reprennent des difficultés que les horaires alternés et le partage des tâches ont atténuées. D contredit la hausse des échanges hors des repas. La médiatrice interroge donc une hiérarchie implicite, pas la souplesse elle-même."},{"number":38,"points":33,"passage":"Après la rénovation d’une place, des ateliers quittent des locaux devenus trop chers. La ville les reloge sur deux sites : Rive, à trois cents mètres, et le Parc, à quatre kilomètres. Les deux groupes bénéficient de réductions de loyer comparables. Un an plus tard, les comptes séparés indiquent, dans chacun des groupes, des recettes moyennes revenues au niveau d’avant le déménagement. La ville les inscrit donc ensemble dans la catégorie « fonctions préservées ». À Rive, les réparations sont encore largement demandées par les habitants de l’ancien quartier ; les artisans continuent à se prêter du matériel avec les mêmes voisins professionnels. Au Parc, le nombre total de clients est comparable, mais ce sont surtout de nouveaux clients venus d’autres secteurs. Les anciens riverains y font rarement réparer leurs objets et les échanges de matériel entre les ateliers dispersés ont fortement diminué. Les brochures municipales présentent avec la même place les artisans des deux sites. L’association de riverains accepte le constat tiré des comptes, mais demande une autre lecture de la catégorie retenue pour préparer la prochaine phase de relogement.","question":"Quelle comparaison des deux sites est étayée par les observations du bilan ?","options":["Les recettes se rétablissent à Rive seulement ; les échanges antérieurs se maintiennent surtout à Rive.","Les recettes se rétablissent sur les deux sites ; les échanges antérieurs se maintiennent surtout à Rive.","Les recettes se rétablissent sur les deux sites ; les échanges antérieurs se maintiennent sur les deux sites.","Les recettes se rétablissent à Rive seulement ; les échanges antérieurs se maintiennent sur les deux sites."],"correct":"B","explanation":"B. Les comptes établissent une reprise moyenne des recettes dans les deux groupes. Il faut y associer l’origine des clients et les échanges de matériel : Rive conserve largement les relations antérieures, tandis que le Parc retrouve des clients surtout nouveaux et perd une partie des liens anciens. A conserve la bonne distinction relationnelle mais attribue à tort la reprise financière à Rive seul. C conserve le résultat financier mais assimile la clientèle nouvelle du Parc à une continuité des relations antérieures. D combine ces deux confusions."},{"number":39,"points":33,"passage":"Pour accélérer la construction, une municipalité compare deux offres utilisant les mêmes composants préfabriqués. La première propose six plans correspondant à différents ménages ; une fois choisi, chaque plan possède ses propres réseaux intégrés aux cloisons. La seconde propose seulement trois plans initiaux, mais regroupe les conduites dans une partie fixe et prévoit des accès techniques indépendants des cloisons mobiles. Son coût de départ est légèrement supérieur. Les deux équipes montrent des logements adaptés à des étudiants, à des familles et au travail à domicile. Les élus hésitent : six plans paraissent offrir davantage de choix que trois. Les architectes de la seconde équipe demandent que l’on suive aussi le cas d’un même appartement lorsque ses occupants changent ou qu’une chambre devient un bureau. Déplacer une cloison ne doit pas entraîner la reprise des réseaux, expliquent-ils. Ils ne prétendent pas rendre toute transformation gratuite : une cuisine déplacée resterait coûteuse dans leur projet. Leurs estimations portent sur des changements de répartition des pièces ordinaires, répétés pendant la durée de vie du bâtiment.","question":"Sur quel avantage comparatif la seconde équipe fonde-t-elle sa proposition aux élus ?","options":["Une meilleure correspondance initiale entre chaque catégorie de ménage et un plan spécialisé.","Une réduction des coûts de déplacement des cuisines grâce à l’investissement technique initial.","Une fabrication moins coûteuse grâce à l’emploi d’une gamme plus réduite de composants.","Une redistribution moins coûteuse des pièces au fil des changements d’usage d’un appartement."],"correct":"D","explanation":"D. L’équipe suit un même appartement au fil de ses usages : séparer les conduites des cloisons mobiles facilite les redistributions des pièces ordinaires. A correspond plutôt à la diversité initiale des six plans. B étend l’économie aux déplacements de cuisines, exclus de la promesse. C confond le nombre de plans avec les composants, identiques dans les deux offres, et contredit le coût initial supérieur."}]}$paper$::jsonb),
('tcf-reading-03','tcf-reading-2026-11-close-reading-v6',$paper${"id":"tcf-reading-03","version":"tcf-reading-2026-11-close-reading-v6","title":"TCF Reading · Test 03","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"L'accueil du centre de formation ferme à midi vendredi. Les cours de l'après-midi auront lieu normalement ; les stagiaires entreront par la porte latérale.\n\nUne affiche devant la réception rappellera le parcours d'accès.","question":"Qu'est-ce qui est maintenu ?","options":["L'accueil toute la journée","Les cours de l'après-midi","Les inscriptions du soir","L'entrée principale ouverte"],"correct":"B","explanation":"Le passage indique : « L'accueil du centre de formation ferme à midi vendredi. Les cours de l'après-midi auront lieu normalement ; les stagiaires entreront par la porte latérale. » Cela justifie la réponse : Les cours de l'après-midi."},{"number":2,"points":3,"passage":"Atelier CV : apportez une offre d'emploi qui vous intéresse. Aucun ordinateur personnel n'est nécessaire ; des postes seront disponibles.\n\nL'animateur vous aidera à sélectionner les expériences pertinentes.","question":"Que faut-il apporter ?","options":["Un contrat signé","Une offre d'emploi","Une lettre de recommandation","Un ordinateur"],"correct":"B","explanation":"Le passage indique : « Atelier CV : apportez une offre d'emploi qui vous intéresse. Aucun ordinateur personnel n'est nécessaire ; des postes seront disponibles. » Cela justifie la réponse : Une offre d'emploi."},{"number":3,"points":3,"passage":"Le vestiaire du personnel sera repeint lundi. Les casiers doivent être vidés avant dimanche soir ; des sacs temporaires seront fournis.\n\nUn agent ouvrira une pièce de stockage pour les effets personnels.","question":"Quand faut-il libérer les casiers ?","options":["Lundi après les travaux","Mardi matin","À la fin du mois","Avant dimanche soir"],"correct":"D","explanation":"Le passage indique : « Le vestiaire du personnel sera repeint lundi. Les casiers doivent être vidés avant dimanche soir ; des sacs temporaires seront fournis. » Cela justifie la réponse : Avant dimanche soir."},{"number":4,"points":3,"passage":"La réunion d'équipe passe en visioconférence demain. Le lien sera envoyé une heure avant ; la durée prévue reste trente minutes.\n\nLes personnes sans caméra pourront participer avec le son seulement. Les documents de travail seront transmis avec l'invitation à tous les collègues.","question":"Quel changement est annoncé ?","options":["La durée de la réunion","Le jour de la réunion","Le nom du responsable","Le mode de participation"],"correct":"D","explanation":"Le passage indique : « La réunion d'équipe passe en visioconférence demain. Le lien sera envoyé une heure avant ; la durée prévue reste trente minutes. » Cela justifie la réponse : Le mode de participation."},{"number":5,"points":9,"passage":"Bonjour Malik, je peux échanger mon service de samedi contre ton mercredi. En revanche, je dois garder mon vendredi pour accompagner mon fils. Dis-moi si cela te convient.\n\nJ'ai déjà vérifié avec le responsable que cet échange ne désorganiserait pas l'équipe. Merci de me répondre rapidement.","question":"Quel service l'auteur veut-il conserver ?","options":["Celui du mercredi","Celui du samedi","Celui du vendredi","Tous les services du matin"],"correct":"C","explanation":"Le passage indique : « Bonjour Malik, je peux échanger mon service de samedi contre ton mercredi. En revanche, je dois garder mon vendredi pour accompagner mon fils. Dis-moi si cela te convient. » Cela justifie la réponse : Celui du vendredi."},{"number":6,"points":9,"passage":"Nous cherchons une personne pour classer des archives pendant six semaines. L'expérience n'est pas indispensable ; la précision et le respect de la confidentialité comptent davantage.\n\nLes dossiers seront traités dans un bureau calme avec un petit groupe.","question":"Quelle qualité est particulièrement recherchée ?","options":["La discrétion","Une expérience de direction","La maîtrise d'un camion","La connaissance de trois langues"],"correct":"A","explanation":"Le passage indique : « Nous cherchons une personne pour classer des archives pendant six semaines. L'expérience n'est pas indispensable ; la précision et le respect de la confidentialité comptent davantage. » Cela justifie la réponse : La discrétion."},{"number":7,"points":9,"passage":"J'ai refusé la promotion proposée. Le salaire augmentait, mais le poste impliquait des déplacements chaque semaine. Je préfère pour l'instant rester près de ma famille.\n\nJ'apprécie pourtant l'équipe et les missions annoncées. Peut-être pourrai-je envisager ce type de poste plus tard, lorsque l'organisation familiale sera différente.","question":"Pourquoi cette personne refuse-t-elle ?","options":["Le salaire serait réduit","Le poste disparaît prochainement","Les déplacements ne lui conviennent pas","Elle souhaite travailler à l'étranger"],"correct":"C","explanation":"Le passage indique : « J'ai refusé la promotion proposée. Le salaire augmentait, mais le poste impliquait des déplacements chaque semaine. Je préfère pour l'instant rester près de ma famille. » Cela justifie la réponse : Les déplacements ne lui conviennent pas."},{"number":8,"points":9,"passage":"La visite de l'atelier est ouverte aux candidats avant leur entretien. Elle permet de découvrir les tâches réelles ; elle n'entre pas dans l'évaluation du recrutement.\n\nUn salarié expliquera les équipements et les horaires.","question":"À quoi sert cette visite ?","options":["Remplacer l'entretien","Signer immédiatement le contrat","Mieux comprendre le travail proposé","Noter la vitesse des candidats"],"correct":"C","explanation":"Le passage indique : « La visite de l'atelier est ouverte aux candidats avant leur entretien. Elle permet de découvrir les tâches réelles ; elle n'entre pas dans l'évaluation du recrutement. » Cela justifie la réponse : Mieux comprendre le travail proposé."},{"number":9,"points":9,"passage":"Chère équipe, le nouveau planning tient compte des demandes reçues avant lundi. Les demandes plus tardives seront examinées pour le mois suivant, sauf urgence familiale.\n\nLe planning sera affiché dans le vestiaire et envoyé aux personnes absentes.","question":"Quelles demandes peuvent encore être traitées ce mois-ci ?","options":["Toutes les demandes tardives","Les demandes sans justification professionnelle","Les urgences familiales","Seulement les demandes de congés d'été"],"correct":"C","explanation":"Le passage indique : « Chère équipe, le nouveau planning tient compte des demandes reçues avant lundi. Les demandes plus tardives seront examinées pour le mois suivant, sauf urgence familiale. » Cela justifie la réponse : Les urgences familiales."},{"number":10,"points":9,"passage":"L'atelier de couture recrute un apprenti. La formation sera partagée entre le centre et l'entreprise ; les débutants seront accompagnés par une salariée expérimentée.\n\nLes candidats découvriront plusieurs étapes du travail avant de choisir une spécialité. L'école et l'entreprise feront régulièrement le point sur les progrès réalisés.","question":"Comment l'apprentissage sera-t-il organisé ?","options":["Uniquement à domicile","Entre formation et travail accompagné","Sans présence en entreprise","Par un examen quotidien éliminatoire"],"correct":"B","explanation":"Le passage indique : « L'atelier de couture recrute un apprenti. La formation sera partagée entre le centre et l'entreprise ; les débutants seront accompagnés par une salariée expérimentée. » Cela justifie la réponse : Entre formation et travail accompagné."},{"number":11,"points":15,"passage":"Après une longue interruption professionnelle, Éva suit un stage court pour actualiser ses outils de gestion. Elle ne change pas de métier : elle prépare son retour dans le même secteur.\n\nElle connaît déjà les dossiers et les habitudes des clients, mais les logiciels ont beaucoup changé pendant son absence. Le centre lui a proposé une évaluation préalable pour identifier ses priorités. Elle suit maintenant deux séances par semaine et s'exerce entre les cours sur des cas proches de son ancien travail. Cette progression lui permet de retrouver confiance sans devoir recommencer toutes ses études depuis le début.","question":"Quel est son objectif ?","options":["Devenir formatrice immédiatement","Ouvrir une agence de voyages","Abandonner son secteur","Mettre ses compétences à jour"],"correct":"D","explanation":"Le passage indique : « Après une longue interruption professionnelle, Éva suit un stage court pour actualiser ses outils de gestion. Elle ne change pas de métier : elle prépare son retour dans le même secteur. » Cela justifie la réponse : Mettre ses compétences à jour."},{"number":12,"points":15,"passage":"Une entreprise de maintenance remet à chaque nouvelle recrue un carnet de situations fréquentes. Les techniciens peuvent y ajouter leurs observations après validation. Le document évolue avec les interventions.\n\nLes nouveaux employés y trouvent des exemples concrets, avec les causes possibles d'une panne et les vérifications à effectuer avant de remplacer une pièce. Les remarques doivent être relues par un collègue pour éviter de diffuser une consigne imprécise.","question":"Qu'est-ce qui caractérise ce carnet ?","options":["Il est réservé aux clients","Il reste définitivement inchangé","Il remplace toutes les formations","Il s'enrichit de l'expérience du terrain"],"correct":"D","explanation":"Le passage indique : « Une entreprise de maintenance remet à chaque nouvelle recrue un carnet de situations fréquentes. Les techniciens peuvent y ajouter leurs observations après validation. Le document évolue avec les interventions. » Cela justifie la réponse : Il s'enrichit de l'expérience du terrain."},{"number":13,"points":15,"passage":"Un artisan montre ses gestes en direct à un petit groupe. Les participants essaient ensuite et discutent de leurs erreurs. Pour lui, regarder une démonstration ne remplace pas la pratique.\n\nLe groupe travaille d'abord sur des chutes de matière afin de pouvoir recommencer sans gaspiller une pièce coûteuse. L'artisan observe la position des mains et demande à chacun d'expliquer son choix. Les échanges révèlent souvent qu'un geste apparemment simple combine plusieurs décisions. À la fin, les participants rédigent quelques repères personnels. Ils savent qu'une fiche ne remplacera pas l'expérience, mais qu'elle pourra leur rappeler les points essentiels lorsqu'ils pratiqueront seuls dans leur propre atelier.","question":"Quelle approche privilégie-t-il ?","options":["L'essai accompagné","L'observation sans exercice","La mémorisation des tarifs","Le travail sans retour"],"correct":"A","explanation":"Le passage indique : « Un artisan montre ses gestes en direct à un petit groupe. Les participants essaient ensuite et discutent de leurs erreurs. Pour lui, regarder une démonstration ne remplace pas la pratique. » Cela justifie la réponse : L'essai accompagné."},{"number":14,"points":15,"passage":"La médiathèque prête des ordinateurs pour les formations du soir. Les demandeurs n'ont pas à justifier leur recherche d'emploi. Le dispositif vise aussi les salariés souhaitant apprendre un nouvel outil.\n\nLe prêt dure tout le cycle et comprend une courte présentation du matériel. Les apprenants peuvent ainsi reprendre les exercices entre les séances, même si leur ordinateur familial est partagé ou ancien. Une permanence permet de signaler un problème technique. La bibliothèque ne demande pas aux participants de détailler leurs revenus ; elle souhaite simplement que les conditions matérielles ne décident pas à elles seules de la possibilité de suivre le cours.","question":"Qui peut bénéficier du prêt ?","options":["Seulement les formateurs","Les entreprises achetant un abonnement","Uniquement des chômeurs inscrits","Des personnes aux situations professionnelles variées"],"correct":"D","explanation":"Le passage indique : « La médiathèque prête des ordinateurs pour les formations du soir. Les demandeurs n'ont pas à justifier leur recherche d'emploi. Le dispositif vise aussi les salariés souhaitant apprendre un nouvel outil. » Cela justifie la réponse : Des personnes aux situations professionnelles variées."},{"number":15,"points":15,"passage":"Dans une usine, la pause peut être prise à plusieurs horaires pour éviter l'affluence au réfectoire. Chaque équipe doit néanmoins garantir une présence suffisante sur la ligne.\n\nLes salariés s'organisent avec leurs collègues et indiquent leur créneau sur un tableau. Un changement est possible si les personnes concernées se mettent d'accord. La direction évaluera l'essai après plusieurs semaines, en regardant les files au restaurant et le fonctionnement de l'atelier. Certains employés apprécient de pouvoir déjeuner plus tôt ; d'autres préfèrent attendre un moment calme. La règle commune permet cette diversité sans laisser une équipe entière quitter son poste simultanément.","question":"Quelle limite encadre cette souplesse ?","options":["L'obligation de manger ensemble","Le maintien du fonctionnement de la ligne","La suppression de toutes les pauses","L'autorisation préalable des clients"],"correct":"B","explanation":"Le passage indique : « Dans une usine, la pause peut être prise à plusieurs horaires pour éviter l'affluence au réfectoire. Chaque équipe doit néanmoins garantir une présence suffisante sur la ligne. » Cela justifie la réponse : Le maintien du fonctionnement de la ligne."},{"number":16,"points":15,"passage":"Un cabinet propose un entretien de recrutement sans nom d'école sur le dossier initial. Les candidats réalisent d'abord un exercice lié au poste. Le diplôme peut être discuté plus tard.\n\nL'exercice est court et utilise des documents fictifs pour ne pas transformer le recrutement en travail gratuit pour l'entreprise. Deux personnes relisent les résultats avec la même grille. Le cabinet souhaite donner leur chance à des parcours moins connus, sans promettre que l'origine scolaire n'aura jamais d'importance.","question":"Que cherche ce procédé ?","options":["Examiner d'abord les compétences en situation","Éliminer toute personne diplômée","Choisir les candidats les plus jeunes","Supprimer l'entretien avec le candidat"],"correct":"A","explanation":"Le passage indique : « Un cabinet propose un entretien de recrutement sans nom d'école sur le dossier initial. Les candidats réalisent d'abord un exercice lié au poste. Le diplôme peut être discuté plus tard. » Cela justifie la réponse : Examiner d'abord les compétences en situation."},{"number":17,"points":15,"passage":"Une salariée apprend la réparation de cycles en soirée. Elle conserve son emploi administratif durant la formation pour vérifier progressivement son projet avant une éventuelle reconversion.\n\nElle rencontre également des professionnels pour connaître les horaires, les charges et les périodes plus calmes de cette activité. Une journée d'observation lui a permis de voir le travail derrière le comptoir, au-delà des réparations les plus intéressantes. Elle constitue progressivement un budget et vérifie les débouchés dans sa ville. Ses proches l'encouragent, mais elle préfère décider à partir de ces informations plutôt que quitter son poste après quelques cours seulement.","question":"Pourquoi garde-t-elle son emploi ?","options":["Parce que la formation est déjà terminée","Pour avancer prudemment dans son projet","Pour devenir responsable du cours","Parce qu'elle renonce au métier envisagé"],"correct":"B","explanation":"Le passage indique : « Une salariée apprend la réparation de cycles en soirée. Elle conserve son emploi administratif durant la formation pour vérifier progressivement son projet avant une éventuelle reconversion. » Cela justifie la réponse : Pour avancer prudemment dans son projet."},{"number":18,"points":15,"passage":"Le service des ressources humaines ouvre une permanence sans rendez-vous. Les questions individuelles seront reçues dans un bureau fermé, afin que les collègues n'entendent pas les échanges.\n\nLes responsables souhaitent réduire les questions restées sans réponse parce qu'il était difficile de trouver un moment disponible. Les sujets collectifs feront l'objet d'une réunion séparée. Le service rappelle que cette organisation ne change pas les règles applicables, mais doit rendre leur explication plus accessible aux personnes qui hésitent à poser une question devant toute l'équipe.","question":"Quelle précaution est prise ?","options":["Préserver la confidentialité des échanges","Diffuser les questions à toute l'équipe","Enregistrer toutes les conversations publiquement","Recevoir uniquement des groupes"],"correct":"A","explanation":"Le passage indique : « Le service des ressources humaines ouvre une permanence sans rendez-vous. Les questions individuelles seront reçues dans un bureau fermé, afin que les collègues n'entendent pas les échanges. » Cela justifie la réponse : Préserver la confidentialité des échanges."},{"number":19,"points":15,"passage":"Un restaurant forme ses serveurs à reconnaître les principaux allergènes. Ils doivent consulter la cuisine en cas de doute, plutôt que promettre un plat adapté sans vérification.\n\nLes fiches seront mises à jour lorsque les recettes ou les fournisseurs changent. L'équipe apprend aussi à transmettre clairement une demande particulière, sans l'interpréter de mémoire. Il précise qu'il vaut mieux prendre quelques minutes pour obtenir une confirmation que donner une assurance que la cuisine ne peut pas réellement tenir.","question":"Quel comportement est demandé ?","options":["Vérifier les informations incertaines","Rassurer le client sans consulter personne","Éviter toute conversation avec la cuisine","Supprimer tous les plats du menu"],"correct":"A","explanation":"Le passage indique : « Un restaurant forme ses serveurs à reconnaître les principaux allergènes. Ils doivent consulter la cuisine en cas de doute, plutôt que promettre un plat adapté sans vérification. » Cela justifie la réponse : Vérifier les informations incertaines."},{"number":20,"points":21,"passage":"Un centre propose des formations modulaires que les adultes peuvent étaler sur deux ans. Les compétences déjà acquises sont évaluées pour éviter de refaire certains modules. Le parcours reste exigeant, mais il s'adapte aux contraintes des participants. Les participants peuvent interrompre temporairement leur parcours et reprendre les éléments déjà validés. Un entretien régulier permet de vérifier si le rythme reste compatible avec leur emploi. Le centre souhaite rendre la formation accessible sans réduire les compétences attendues à la fin. Il demande donc un engagement réaliste plutôt qu'une présence intensive impossible à maintenir pour certaines personnes.","question":"Quel avantage offre l'évaluation initiale ?","options":["Garantir le diplôme sans formation","Imposer le même calendrier à chacun","Supprimer tous les examens","Éviter des apprentissages déjà maîtrisés"],"correct":"D","explanation":"Le passage indique : « Un centre propose des formations modulaires que les adultes peuvent étaler sur deux ans. Les compétences déjà acquises sont évaluées pour éviter de refaire certains modules. Le parcours reste exigeant, mais il s'adapte aux contraintes des participants. » Cela justifie la réponse : Éviter des apprentissages déjà maîtrisés."},{"number":21,"points":21,"passage":"Dans une entreprise de livraison, les conducteurs proposent de modifier les tournées. La direction accepte un essai sur deux secteurs avant une généralisation. Les délais et la fatigue seront étudiés ensemble, car une tournée rapide peut aussi être épuisante. Les conducteurs ont identifié des arrêts où les attentes sont longues et des itinéraires qui imposent de nombreuses manœuvres. Leurs propositions seront comparées sur des journées semblables. La direction souhaite éviter qu'un meilleur délai annoncé se traduise simplement par davantage de pression sur les mêmes personnes.","question":"Quels critères seront comparés ?","options":["Uniquement le prix des véhicules","La performance et les conditions de travail","Le nombre de publicités affichées","Les préférences musicales des conducteurs"],"correct":"B","explanation":"Le passage indique : « Dans une entreprise de livraison, les conducteurs proposent de modifier les tournées. La direction accepte un essai sur deux secteurs avant une généralisation. Les délais et la fatigue seront étudiés ensemble, car une tournée rapide peut aussi être épuisante. » Cela justifie la réponse : La performance et les conditions de travail."},{"number":22,"points":21,"passage":"Une association accompagne les personnes qui souhaitent faire reconnaître une expérience bénévole. Elle aide à décrire les activités réalisées, sans promettre automatiquement une certification. La décision dépend ensuite de l'organisme compétent. Les bénévoles apportent des exemples, des documents et des descriptions de situations. Un accompagnateur les aide à distinguer une responsabilité précise d'une participation occasionnelle. Ils n'effacent pas les exigences du diplôme demandé, mais peuvent aider une personne à présenter des acquis jusque-là difficiles à formuler.","question":"Quelle limite du service est précisée ?","options":["Seuls les salariés sont reçus","L'accompagnement ne garantit pas la certification","Le bénévolat ne peut jamais être décrit","L'association délivre tous les diplômes"],"correct":"B","explanation":"Le passage indique : « Une association accompagne les personnes qui souhaitent faire reconnaître une expérience bénévole. Elle aide à décrire les activités réalisées, sans promettre automatiquement une certification. La décision dépend ensuite de l'organisme compétent. » Cela justifie la réponse : L'accompagnement ne garantit pas la certification."},{"number":23,"points":21,"passage":"Le bureau partagé d'un service était censé faciliter les échanges. Les appels fréquents y ont pourtant gêné les tâches de concentration. L'équipe réserve maintenant des créneaux silencieux et des espaces pour les conversations. Les nouvelles règles ont été dessinées avec les salariés après une semaine d'observation. Chacun peut signaler une difficulté sans demander l'interdiction de tous les échanges. Les responsables savent que les dossiers ne demandent pas tous le même environnement.","question":"Pourquoi l'organisation a-t-elle évolué ?","options":["Pour concilier échange et concentration","Pour interdire tout travail collectif","Pour augmenter le bruit des appels","Pour réduire le nombre de clients"],"correct":"A","explanation":"Le passage indique : « Le bureau partagé d'un service était censé faciliter les échanges. Les appels fréquents y ont pourtant gêné les tâches de concentration. L'équipe réserve maintenant des créneaux silencieux et des espaces pour les conversations. » Cela justifie la réponse : Pour concilier échange et concentration."},{"number":24,"points":21,"passage":"Un hôtel préfère former plusieurs salariés à l'accueil de nuit plutôt que dépendre d'une seule personne. Les volontaires bénéficieront d'un accompagnement et de repos adaptés. La polyvalence doit réduire la fragilité du service, pas multiplier les heures de chacun. Les premiers essais concerneront des périodes courtes, avec une personne expérimentée disponible pour répondre aux questions. Les volontaires apprendront aussi les procédures à suivre en cas d'incident. La direction souhaite limiter les remplacements improvisés au dernier moment.","question":"Quel objectif poursuit l'hôtel ?","options":["Imposer des nuits à tous les clients","Remplacer tout le personnel par une machine","Rendre le service moins dépendant d'une personne","Supprimer les repos"],"correct":"C","explanation":"Le passage indique : « Un hôtel préfère former plusieurs salariés à l'accueil de nuit plutôt que dépendre d'une seule personne. Les volontaires bénéficieront d'un accompagnement et de repos adaptés. La polyvalence doit réduire la fragilité du service, pas multiplier les heures de chacun. » Cela justifie la réponse : Rendre le service moins dépendant d'une personne."},{"number":25,"points":21,"passage":"Pour leur journée de formation, les salariés d'une petite entreprise ont demandé, les uns, un logiciel de planification, les autres, une réflexion sur les urgences. Le premier projet de programme juxtaposait deux ateliers. L'équipe a finalement confié aux deux animateurs un même dossier fictif, inspiré d'une commande livrée en retard, avec les échanges entre l'atelier, les achats et les ventes. Le matin, les participants en établissent le calendrier avec le logiciel. L'après-midi, ils découvrent des informations sur un fournisseur et doivent reprendre leurs choix. Le temps de saisie est relevé, mais ne sert pas à classer les groupes. Chacun explique plutôt ce qu'il a conservé ou modifié. Les salariés débutants disposent d'une fiche technique, afin que la maîtrise des menus ne décide pas de la discussion.","question":"Quelle compétence travaille surtout le scénario retenu pour cette journée ?","options":["Adapter une planification à une information tardive en explicitant les choix qui doivent être modifiés.","Arbitrer entre deux planifications concurrentes en appliquant à chacune les mêmes informations de départ.","Confronter les contraintes de plusieurs services pour répartir entre eux les tâches d'une commande.","Établir un classement commun des urgences pour harmoniser les décisions prises séparément par chaque groupe."],"correct":"A","explanation":"A correspond à la reprise du calendrier quand de nouvelles informations sur le fournisseur arrivent. B suppose la comparaison de deux plans concurrents à données constantes, alors que le même plan est réexaminé avec des données nouvelles. C prend les services présents dans le dossier pour l'objet d'une négociation entre eux. D transforme les explications données par chaque groupe en recherche d'un classement commun des urgences."},{"number":26,"points":21,"passage":"Une école professionnelle prépare une rencontre sur les changements de métier. Elle avait d'abord invité trois anciens élèves dont la reconversion était achevée. Les organisateurs ont ajouté deux intervenantes qui souhaitent devenir électriciennes : l'une commence sa formation, l'autre attend encore de pouvoir s'inscrire. Toutes deux ont déjà effectué une immersion et confirmé leur choix. La première dispose d'une indemnisation et d'une solution de garde ; la seconde doit conserver son salaire jusqu'au début des cours et n'a pas trouvé de relais familial. Les élèves recevront une chronologie de leurs démarches, sans classement entre les parcours. La rencontre comportera aussi le témoignage d'un diplômé revenu à son premier métier après une expérience dans un autre secteur.","question":"Que permet surtout d'examiner le rapprochement entre les deux futures électriciennes ?","options":["L'influence d'une immersion sur la précision du projet de reconversion.","Le rapport entre la durée d'une hésitation et le calendrier de formation.","L'effet d'un diplôme antérieur sur le choix d'une nouvelle spécialité.","Le rôle des ressources disponibles dans la réalisation d'un projet confirmé."],"correct":"D","explanation":"Les deux intervenantes ont confirmé le même projet après une immersion, mais leurs possibilités financières et familiales diffèrent : D explique l'intérêt de leur rapprochement. A concerne une étape déjà accomplie par toutes deux. B leur attribue une hésitation que le texte ne signale pas. C transpose à ces deux femmes le diplôme mentionné à propos d'un troisième intervenant."},{"number":27,"points":21,"passage":"Avant sa retraite, un technicien filme le réglage d'une presse. Un apprenti suit la séquence et obtient une pièce déformée. Le technicien apporte alors des plaques de même aspect provenant de deux lots. Il fait manœuvrer lentement le levier à l'apprenti, qui décrit une différence dans la façon dont le mouvement se poursuit. Le lendemain, sur une autre presse, l'apprenti reporte les valeurs affichées sur sa fiche: ce sont celles du film. Il signe aussi le contrôle d'outillage effectué avec un collègue. Au troisième essai, il demande à celui-ci de venir sentir le mouvement, puis s'arrête avant la mise en forme. La plaque est mise de côté. En fin de journée, le laboratoire classe son lot à part: plusieurs plaques y avaient reçu un traitement différent des autres. L'équipe prépare désormais des séances associant les films à la manipulation de lots variés.","question":"Quelle règle de décision l'apprenti semble-t-il avoir acquise lors de l'essai du lendemain ?","options":["Suspendre le réglage lorsqu'une position affichée s'écarte de la valeur de référence montrée sur la vidéo.","Suspendre le réglage lorsqu'un contrôle de la pièce révèle une déformation après les premières opérations.","Suspendre le réglage lorsqu'une résistance ressentie indique que la matière ne réagira pas comme prévu.","Suspendre le réglage lorsqu'un changement de machine exige de vérifier la compatibilité de l'outillage utilisé."],"correct":"C","explanation":"C. L'apprenti a comparé les sensations produites par deux lots, demande ensuite de sentir le mouvement et interrompt l'essai avant la mise en forme. Le classement ultérieur du lot rend cohérente l'anticipation d'une réaction différente de la matière. A ne correspond pas aux valeurs relevées, identiques à celles du film. B transpose au nouvel essai la pièce déformée de la veille. D place après l'arrêt un contrôle d'outillage déjà signé."},{"number":28,"points":21,"passage":"Dans une entreprise, peu de salariés s'inscrivent aux formations du mardi soir. La direction envisage de renouveler les thèmes. Les entretiens révèlent pourtant que plusieurs employés avaient demandé ces mêmes cours avant de connaître les horaires. Certains doivent récupérer leurs enfants ; d'autres changent d'équipe chaque semaine. À titre d'essai, deux cours inchangés sont proposés pendant le travail et sur plusieurs dates. Les inscriptions progressent surtout parmi ceux qui avaient déjà exprimé leur intérêt. Plusieurs inscrits espèrent aussi échanger avec des collègues d'autres équipes. Le bilan est établi avant le premier cours. Des salariés continuent cependant à refuser les deux cours, jugés éloignés de leur poste. Le prochain programme prévoit donc à la fois une révision de l'offre et le maintien de créneaux alternatifs.","question":"À quelle explication la hausse des inscriptions apporte-t-elle le soutien le plus direct ?","options":["Une demande déjà exprimée restait en partie empêchée par l'organisation des séances.","Une offre mieux adaptée aux postes a réveillé un intérêt jusque-là peu affirmé.","Les entretiens ont convaincu des salariés qui doutaient de l'utilité de se former.","Les échanges pendant les premières séances ont incité d'autres collègues à s'inscrire à leur tour."],"correct":"A","explanation":"Les mêmes cours attirent davantage de salariés qui les souhaitaient déjà, après modification des créneaux : A est l'explication directement étayée. B suppose une modification de contenu qui n'a pas eu lieu. C attribue aux entretiens un changement de conviction alors que l'intérêt leur était antérieur. D transforme des échanges espérés en effet déjà observé, alors que le bilan précède le premier cours."},{"number":29,"points":21,"passage":"Un espace de travail élargit ses horaires du soir, accueille de nouvelles professions et organise des présentations le mercredi. Julien choisit un bureau où laisser son matériel. Il peut y passer de longues journées et apprécie la variété des personnes rencontrées, mais retrouve rarement un interlocuteur de la veille. Samira remplace sa journée entière, réservée selon ses disponibilités, par deux heures chaque mardi avec deux personnes connues lors d'une soirée d'accueil. Les tables changent selon les besoins. Un mardi, elle leur soumet une difficulté dans un devis; la semaine suivante, l'un revient avec des annotations et lui demande conseil sur son propre projet. Ils commencent ensuite à se recommander des clients. Julien continue à assister aux présentations du mercredi pour découvrir les nouveaux métiers accueillis. Le gestionnaire conserve les deux formules, auxquelles les utilisateurs attribuent des intérêts différents.","question":"Quel élément de la formule de Samira rend le mieux compte de la collaboration racontée ?","options":["L'allongement des périodes de présence donne aux participants davantage de temps pour découvrir leurs activités respectives.","Le retour des mêmes interlocuteurs permet aux échanges de se poursuivre et de déboucher sur des collaborations.","La diversité accrue des professions représentées élargit les possibilités de recommandations et de projets entre participants.","La fréquence accrue des présentations animées aide les participants à repérer plus vite les compétences de leurs voisins."],"correct":"B","explanation":"B. Samira revoit des personnes déjà rencontrées; une question laissée ouverte reçoit une réponse la semaine suivante, puis l'aide devient réciproque. A correspond plutôt aux longues journées de Julien: Samira a remplacé une journée entière par deux heures. C reprend l'élargissement des métiers accueillis, mais le récit de Samira met en évidence la continuité d'un même groupe. D attribue un effet à une fréquence accrue des présentations, dont le passage n'établit pas l'augmentation."},{"number":30,"points":26,"passage":"Dans un service à distance, la direction rapproche le temps de connexion du nombre de dossiers clôturés. Marc traite surtout les demandes standardisées; Sofia reprend les litiges. Pour un litige, Sofia envoie une demande à un partenaire puis ferme aussitôt sa session; la réponse arrive avant sa reconnexion du lendemain. Le journal conserve les heures d'envoi et de réponse. Le relevé de Marc comporte notamment une demi-heure d'appui à un collègue. Dans l'agenda de Sofia, une plage quotidienne est consacrée aux appels: elle quitte l'application au début de cette plage et y saisit ses notes au retour. Le directeur propose d'ajouter la durée des conversations relevée dans l'historique téléphonique. La représentante du personnel examine aussi deux lignes du journal de Marc. Lundi, le dossier R42 indique « accès au compte rétabli », puis reçoit le statut « clos ». Jeudi, un nouveau dossier, R75, porte le même compte et la note du client: « la coupure de lundi recommence ». Il est fermé après une nouvelle intervention. Le tableau hebdomadaire attribue deux clôtures à Marc pour ces lignes. La représentante demande de conserver cet historique lors de la comparaison des agents, en plus de l'ajustement du temps proposé.","question":"Quel problème resterait dans le classement après l'ajout des appels proposé par la direction ?","options":["Certains échanges utiles resteraient hors du temps retenu, notamment l'aide apportée entre collègues.","Une même difficulté pourrait produire plusieurs unités de résultat, lorsqu'une demande est clôturée puis reprise.","Certaines minutes seraient comptées deux fois, lorsqu'un appel se déroule pendant une connexion déjà mesurée.","Des délais d'attente seraient comptés comme du travail, lorsqu'un partenaire tarde à répondre à une demande."],"correct":"B","explanation":"B. Le classement utilise les clôtures; les deux lignes concernent le retour de la même coupure, mais produisent deux clôtures. Ajouter du temps d'appel ne change pas ce rapprochement entre unités comptées et difficultés durablement résolues. A ignore l'appui déjà inscrit au relevé de Marc. C suppose que la plage d'appels reste une plage de connexion. D confond les horodatages de suivi et le temps travaillé: l'attente décrite se déroule entre la fermeture et la reprise de la session, et l'ajout proposé porte sur les conversations téléphoniques."},{"number":31,"points":26,"passage":"Un collectif de soignants conteste une affiche interne affirmant que la passion du métier permet de dépasser les contraintes horaires. La semaine suivante, après l'absence imprévue de plusieurs collègues, ses membres acceptent de prolonger leurs gardes. La direction y voit une contradiction. Les soignants demandent alors que ces heures figurent dans le bilan du service, avec les transmissions écourtées et les rendez-vous reportés. Ils proposent de renouveler l'aide pendant quelques jours, jusqu'à l'arrivée de renforts, mais refusent qu'elle serve à fixer les effectifs habituels. Une responsable propose que les équipes suggèrent de nouveaux horaires et de mesurer la fatigue de chacun pour mieux distribuer les gardes. Le collectif accepte ce suivi, à condition qu'il complète le relevé des besoins non couverts. Il souhaite notamment savoir combien de travail est actuellement effectué après la fin officielle du service.","question":"À quoi le collectif veut-il principalement faire servir le bilan demandé ?","options":["Repérer les périodes de tension afin de déplacer les horaires existants vers les moments où l'activité est la plus forte.","Comparer la fatigue des équipes afin de répartir autrement les gardes sans modifier le volume d'heures disponibles.","Mesurer le temps des transmissions afin de réorganiser les échanges entre services en conservant les mêmes effectifs.","Évaluer le travail au-delà des horaires officiels afin de déterminer les renforts nécessaires au fonctionnement habituel."],"correct":"D","explanation":"Le collectif veut rendre compte du travail réellement nécessaire, y compris après les horaires officiels, pour ne pas fixer les effectifs sur l'aide d'urgence : D. A et B décrivent des réorganisations possibles du temps disponible, mais la demande porte aussi sur les besoins non couverts. C retient les transmissions, un élément du bilan, comme si leur réorganisation suffisait à effectifs constants."},{"number":32,"points":26,"passage":"Une candidate à un poste technique réussit l'exercice de recrutement, puis passe une journée d'observation rémunérée dans l'atelier. Le matin, elle négocie un créneau pour utiliser un outil partagé et compare deux méthodes lorsque le responsable avance un délai. Elle demande aussi l'ordre des interventions après l'arrivée d'une commande urgente. Lors du dernier travail, elle relève la série S sur la plaque de la machine et joint à ses notes une notice intitulée « série R ». Elle propose deux façons d'organiser l'intervention, mais attend le retour du salarié habilité à en autoriser le lancement. Le premier bilan décrit une candidate qui sollicite fréquemment des confirmations. À la relecture, le comité sépare les épisodes et retrouve les deux propositions qu'elle avait formulées pour le dernier travail. Il retire alors la mention selon laquelle elle n'aurait pas su envisager une action et prévoit une autre observation avant de conclure sur son autonomie.","question":"Quel constat ultérieur fragiliserait le plus la réinterprétation de cette dernière attente ?","options":["Les demandes de validation persistent après réception d'une notice applicable et de l'accord nécessaire pour intervenir.","Les comparaisons de méthodes persistent une fois le délai relâché et les procédures jugées équivalentes pour le travail demandé.","Les demandes de hiérarchisation persistent après qu'un ordre a été fixé entre les interventions concurrentes de l'atelier.","Les vérifications de disponibilité persistent après qu'un créneau d'utilisation exclusive a été attribué pour l'outillage nécessaire."],"correct":"A","explanation":"A. Pour la dernière attente, les notes rapprochent une machine S d'une notice R et montrent que l'autorisation de lancement dépend d'un salarié habilité. Si les confirmations persistent une fois ces deux conditions réglées, cette explication de l'attente devient moins convaincante. B, C et D testeraient plutôt les comportements observés dans d'autres épisodes: choix d'une méthode sous délai, ordre des tâches et partage d'outillage."},{"number":33,"points":26,"passage":"Dans un service de maintenance, chaque spécialiste possède un domaine très précis. Après une absence qui a bloqué des opérations simples, l'entreprise organise des échanges de savoirs. Les collègues apprennent les interventions fréquentes, les signes d'anomalie et le nom d'un expert à contacter hors du service. Ils n'ont pas à acquérir toutes les qualifications du spécialiste. Lors de son absence suivante, le nombre d'opérations courantes reste stable. Deux pannes inhabituelles attendent cependant l'avis de l'expert extérieur. Les pièces nécessaires sont disponibles et les délais des opérations connues ne s'allongent pas. Le responsable présente ce résultat au personnel : les fiches ont été utiles pour les opérations connues, et les collègues ont correctement isolé les machines douteuses. Il veut raccourcir le délai de réponse extérieur, sans leur demander de remettre ces machines en route sur la seule base des fiches. Les échanges de savoirs se poursuivront pendant le temps de travail.","question":"Quel bilan correspond aux limites et aux réussites du relais pendant l'absence ?","options":["Les relais ont assuré le diagnostic des pannes courantes, mais leur remise en route a encore nécessité une validation extérieure.","Les relais ont assuré les interventions connues et certaines pannes rares, mais la disponibilité des pièces a retardé d'autres réparations.","Les relais ont assuré les opérations habituelles, mais les anomalies non prévues ont encore nécessité l'avis d'un expert extérieur.","Les relais ont assuré les gestes décrits sur les fiches, mais les délais ont augmenté pour les opérations nécessitant une coordination entre collègues."],"correct":"C","explanation":"Les opérations habituelles continuent et les machines présentant des pannes inhabituelles sont isolées dans l'attente d'un expert : C. A étend la validation extérieure aux opérations courantes. B fait des pièces le facteur limitant, alors qu'elles sont disponibles. D attribue au relais un allongement des délais connus qui n'est pas observé."},{"number":34,"points":26,"passage":"Une formation courte promet un accès rapide à la maintenance. Lors du bilan, une ancienne stagiaire prépare le certificat exigé pour intervenir sur certaines installations; un autre étudie un emploi éloigné qui nécessiterait un déménagement. L'école prévoit aussi une session terminant avant la saison touristique, pour les postes d'entretien des campings. Un groupe vise cependant les emplois débutants de deux ateliers voisins qui recrutent au moment du bilan. Deux candidats présentés par d'anciens collègues y ont passé une mise en situation et reçu une proposition. Les notes des employeurs décrivent des compétences suffisantes pour les interventions prévues. D'autres membres du groupe, qui avaient réussi les mêmes exercices de formation, ont envoyé des dossiers et reçu seulement un accusé de réception. Le directeur propose davantage de pratique pour eux. Les anciens rassemblent les évaluations et les étapes suivies par chacun, afin que le prochain accompagnement permette de comprendre cet écart au lieu de présumer sa cause.","question":"Quelle mesure permettrait de tester le plus directement l'explication de l'écart au sein du groupe visant les deux ateliers ?","options":["Proposer une qualification complémentaire aux candidats restés sans réponse, puis suivre l'évolution des décisions des recruteurs.","Financer les déplacements des candidats restés sans réponse vers les deux ateliers, puis suivre l'évolution des décisions des recruteurs.","Décaler la sortie de formation des candidats restés sans réponse vers la période de recrutement saisonnier, puis suivre leurs embauches.","Présenter les candidats restés sans réponse aux ateliers pour une mise en situation, puis observer les décisions prises après cette rencontre."],"correct":"D","explanation":"D. Les candidats recommandés ont pu montrer leur travail et ont été jugés prêts; les autres n'ont pas atteint cette étape malgré leur réussite aux exercices. Leur donner accès à la même épreuve teste la différence de parcours effectivement relevée. A et C reprennent des obstacles de qualification ou de calendrier décrits dans d'autres projets. B testerait une difficulté de mobilité auprès des mêmes ateliers, mais cet obstacle est documenté pour une autre offre éloignée; le contraste observé dans ce groupe concerne l'accès à la mise en situation."},{"number":35,"points":26,"passage":"Deux équipes de préparation de commandes peuvent choisir l'ordre de leurs opérations, sous réserve des contrôles de sécurité. La première réussit à absorber des arrivées urgentes et rédige un guide: regrouper certains colis sur la table centrale, préparer les étiquettes, puis appeler le quai. Le document mis à disposition le lundi reprend les horaires de transport annoncés le vendredi. Le mardi, la seconde équipe l'essaie dans son nouvel atelier, où elle a récemment appris à utiliser des chariots différents. Les colis sont préparés, mais le camion qui part le premier attend encore une partie de son chargement. Une salariée de la première équipe vient alors discuter du cas. Elle demande à quelle heure chaque lot peut réellement partir et quels contrôles risquent de retarder sa libération. Les collègues déplacent l'ordre de préparation qu'ils avaient retenu. Lors d'une arrivée urgente ultérieure, ils choisissent une organisation différente de celle du guide et la mènent à terme. Le responsable compare les photographies des actions décrites, le récit de la visite et les décisions prises après celle-ci avant de diffuser le document à d'autres équipes.","question":"Quelle différence explique le mieux ce que la visite a apporté par rapport au guide seul ?","options":["Le guide reposait sur des horaires devenus anciens, tandis que la visite a fourni les informations de transport nécessaires à leur actualisation.","Le guide supposait des gestes techniques encore mal maîtrisés, tandis que la visite a apporté l'apprentissage nécessaire à l'utilisation des outils.","Le guide présentait des actions déjà réalisées, tandis que la visite a fait travailler les repères nécessaires pour décider dans quelles circonstances les reprendre.","Le guide décrivait des choix encore réservés à la première équipe, tandis que la visite a donné aux collègues l'autorisation nécessaire pour les effectuer."],"correct":"C","explanation":"C. Le guide énumère des actions; pendant la visite, les échanges portent sur les départs possibles et les contrôles qui modifient l'ordre utile. Les collègues peuvent ensuite choisir une autre organisation pour un nouvel événement. A attribue ce résultat à une actualisation d'horaires qui n'est pas décrite: la visite travaille la disponibilité réelle des lots et les risques liés aux contrôles. B transforme cette discussion en apprentissage de manipulation. D oublie que les deux équipes disposent dès le départ du choix de l'ordre des opérations."},{"number":36,"points":33,"passage":"Après avoir organisé des festivals, Léa coordonne des rendez-vous hospitaliers. Elle retrouve les tableaux de contraintes qu'elle utilisait auparavant, mais les indications médicales délimitent son intervention. Le service lui laisse choisir l'ordre des rendez-vous à l'intérieur des plages validées, sans lui permettre de modifier ces plages ni les niveaux de priorité. Pour une première série, Inès et Luc ont le même niveau de priorité. La fiche d'Inès indique un passage « pas avant quatorze heures »; celle de Luc demande un passage « avant quinze heures ». Ils sont initialement prévus dans cet ordre, à quatorze heures puis quatorze heures trente. Une contrainte de transport amène Léa à envisager Luc au premier créneau et Inès au second. Dans une autre série, Zoé et Malik portent également le même niveau de priorité. Pour libérer un appareil au bon moment, Léa prévoit d'avancer Malik devant Zoé; les deux horaires restent dans leurs plages. Entre-temps, un nouveau résultat rejoint le dossier de Malik avec la mention du médecin « priorité à réévaluer avant programmation ». La modification de cette fiche n'est pas encore enregistrée. Léa décrit les deux réaménagements et leurs effets sur les ressources, comme elle le faisait lorsqu'un imprévu modifiait l'organisation d'un festival.","question":"Quelle conduite respecte la marge de décision de Léa pour chacun des deux réaménagements envisagés ?","options":["Elle peut retenir le premier réaménagement, mais doit attendre une décision médicale pour le second.","Elle doit attendre une décision médicale pour le premier, mais peut retenir le second réaménagement.","Elle peut retenir les deux réaménagements dans le cadre des validations médicales déjà inscrites.","Elle doit attendre une décision médicale pour chacun des deux réaménagements envisagés."],"correct":"A","explanation":"A. Dans la première série, Luc à quatorze heures reste avant quinze heures et Inès à quatorze heures trente reste après la limite de quatorze heures. Leur priorité est identique: Léa peut choisir cet ordre dans les plages validées. Dans la seconde série, la compatibilité des horaires ne suffit pas: la priorité de Malik doit être réévaluée avant programmation, donc l'égalité inscrite n'est plus une base suffisante pour arrêter l'ordre. B inverse les deux situations. C étend au second cas une autonomie qui reste soumise à la décision médicale en attente. D traite tout changement d'ordre comme nécessitant une nouvelle validation, alors que cette marge est expressément laissée à Léa dans le premier cas."},{"number":37,"points":33,"passage":"Un logiciel préremplit les formulaires d'un service public. Les équipes disposent ainsi de quelques minutes qu'elles peuvent affecter à différentes étapes de l'accueil. Le bilan rapproche deux récits. Nora apporte un justificatif de domicile et son nouveau contrat de travail pour signaler un déménagement. L'agent sélectionne la demande correspondant à l'adresse; le contrôle réglementaire valide les champs de ce formulaire. La semaine suivante, Nora revient après le début de son emploi, pourtant déjà prévu lors du premier rendez-vous: le calcul de son aide doit être repris. Dans un autre entretien, Sami présente également un changement d'adresse. Après la saisie, l'agente lui demande ce qui va changer au cours du mois; il parle alors de son prochain emploi. Elle ouvre une demande regroupant les deux changements. Le service dispose justement d'un formulaire permettant de déclarer ensemble des changements déjà programmés. Son équipe propose par ailleurs des rappels pour annoncer l'avancement des dossiers, et l'accueil envoie avant les rendez-vous la liste des pièces à apporter. La direction doit maintenant décider où renforcer le temps humain rendu disponible par le logiciel.","question":"Quelle affectation de ce temps répondrait le plus directement à la difficulté révélée par les deux récits ?","options":["Placer un échange préparatoire avant le rendez-vous pour réunir les pièces et vérifier la complétude matérielle du dossier présenté.","Prolonger l'exploration de la situation au premier accueil pour relier les changements avant de choisir la demande à déposer.","Ajouter une validation spécialisée après la saisie pour contrôler l'application des règles à la demande qui a été sélectionnée.","Organiser un rappel après le dépôt pour expliquer l'avancement du dossier et vérifier les démarches que l'usager doit encore effectuer."],"correct":"B","explanation":"B. Nora disposait déjà des documents et son emploi était prévu, mais la demande sélectionnée ne reliait pas les deux changements. L'entretien de Sami fait émerger ce lien avant le choix d'un formulaire pouvant les réunir. A renforcerait une préparation documentaire déjà présente dans le premier cas. C vérifierait les règles d'une demande sélectionnée sans nécessairement en élargir le contenu. D agirait après le dépôt, alors que les éléments utiles pouvaient être réunis dès l'accueil."},{"number":38,"points":33,"passage":"Le meilleur réparateur d'un atelier devient responsable d'équipe. Le premier mois, il reprend les appareils dès qu'un collègue hésite; plusieurs postes restent en attente lorsqu'il est occupé ailleurs. Son carnet contient alors beaucoup de remplacements de composants courants. Un tuteur organise ensuite des points où chacun présente son diagnostic et l'action qu'il propose. Deux mois plus tard, une technicienne rencontre une panne proche d'un cas discuté, choisit une vérification, réalise la réparation et contrôle le résultat. Un collègue met de côté un appareil présentant un risque qu'il ne sait pas évaluer, puis expose ses observations au point prévu avec le responsable. Les réparations usuelles gardent leurs délais, et les retours pour erreur restent au même niveau. Le carnet récent du responsable décrit surtout des appareils anciens sans documentation et des recherches de défauts intermittents. Il a signé moins de réparations, mais le temps moyen de celles-ci a doublé. Le directeur y voit la preuve que la promotion a fait perdre de la rapidité à son meilleur technicien. Le tuteur rapproche les carnets des scènes de travail observées pour préparer le bilan.","question":"Quel bilan est le mieux étayé concernant la rapidité personnelle du responsable et l'autonomie de l'équipe ?","options":["La moyenne établit un recul de sa rapidité technique, mais les scènes observées montrent que les collègues décident davantage par eux-mêmes.","La moyenne ne suffit pas à établir un recul technique, et les scènes observées ne permettent pas encore de conclure à une autonomie accrue.","La moyenne ne suffit pas à établir un recul technique, mais les scènes observées montrent que les collègues décident davantage par eux-mêmes.","La moyenne établit un recul de sa rapidité technique, et les scènes observées ne permettent pas encore de conclure à une autonomie accrue."],"correct":"C","explanation":"C. Les carnets ne portent plus sur le même mélange d'interventions: les remplacements courants du début et les recherches atypiques récentes ne permettent pas de déduire un ralentissement personnel de la seule moyenne. Séparément, la technicienne agit à partir de son diagnostic et le collègue prépare un recours adapté au risque; le responsable ne reprend plus chaque hésitation. Les délais et retours des réparations usuelles soutiennent cette lecture. A conserve une conclusion individuelle non établie. B écarte les observations d'autonomie. D cumule ces deux erreurs."},{"number":39,"points":33,"passage":"Pour diversifier son recrutement, une organisation ouvre des entretiens en soirée et remplace un stage non rémunéré par une courte épreuve payée sur dossier fictif. Les candidats déjà en emploi et ceux qui ne pouvaient financer un stage parviennent désormais aussi souvent que les autres au dernier entretien. Le profil des personnes recrutées change pourtant peu. À cette dernière étape, les candidats expliquent leur solution et les recruteurs remplissent notamment une rubrique « autonomie immédiate ». Une association compare deux dossiers dont l'exercice anonyme a reçu la même note. Une technicienne ayant six ans d'expérience ailleurs expose une vérification que le jury juge pertinente. Elle s'arrête ensuite sur le sigle désignant le service à prévenir, dont elle demande la signification. Sa fiche indique « accompagnement nécessaire ». Un ancien stagiaire de l'organisation, récemment diplômé, décrit la même vérification en employant ce sigle et obtient « immédiatement opérationnel ». Les deux exposés durent environ trois minutes; leur clarté est appréciée de la même façon. Ces différences de notation réapparaissent dans plusieurs dossiers comparables. Les recruteurs s'interrogent sur ce que leur rubrique mesure avant de la reconduire.","question":"Quel mécanisme explique le mieux la faible évolution des profils recrutés ?","options":["La grille favorise les présentations brèves au détriment des réponses qui détaillent les vérifications techniques.","La grille fait prévaloir l'expérience professionnelle antérieure sur les résultats de l'épreuve pratique commune.","La grille pénalise les démarches qui s'écartent de la procédure attendue même quand leur résultat technique est valide.","La grille traite la maîtrise du vocabulaire interne comme un indice de capacité à travailler sans aide."],"correct":"D","explanation":"D. Les deux candidats ont obtenu la même note à l'exercice anonyme et proposent la même vérification, jugée pertinente. Leurs exposés ont une durée et une clarté comparables. Pourtant, la demande de précision sur un sigle interne est associée à un besoin d'accompagnement, tandis que son emploi par l'ancien stagiaire est associé à une disponibilité immédiate pour le poste. La grille utilise donc ici une connaissance du vocabulaire de l'organisation comme indice d'autonomie. A invoque une différence de brièveté absente du relevé. B ne rend pas compte du jugement moins favorable porté sur la candidate ayant six ans d'expérience ailleurs. C suppose une divergence de procédure alors que les deux candidats décrivent la même vérification."}]}$paper$::jsonb),
('tcf-reading-04','tcf-reading-2026-11-close-reading-v6',$paper${"id":"tcf-reading-04","version":"tcf-reading-2026-11-close-reading-v6","title":"TCF Reading · Test 04","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"Le car pour Valmont partira du quai 6 au lieu du quai 2. L'heure de départ reste fixée à huit heures.\n\nUne équipe sera présente dans le hall pour orienter les passagers. Les billets déjà achetés restent valables sur ce départ.","question":"Que doit vérifier le voyageur ?","options":["Le numéro de sa place","Un nouvel horaire","Le prix du billet","Le nouveau quai"],"correct":"D","explanation":"Le passage indique : « Le car pour Valmont partira du quai 6 au lieu du quai 2. L'heure de départ reste fixée à huit heures. » Cela justifie la réponse : Le nouveau quai."},{"number":2,"points":3,"passage":"Le musée maritime accepte les billets de la veille après sa fermeture exceptionnelle. Aucun échange au guichet n'est nécessaire.\n\nLe personnel a été informé de cette mesure et vous indiquera les espaces ouverts.","question":"Comment utiliser un billet acheté pour la veille ?","options":["Acheter un second billet","Demander un remboursement obligatoire","Le présenter directement à l'entrée","L'envoyer par courrier"],"correct":"C","explanation":"Le passage indique : « Le musée maritime accepte les billets de la veille après sa fermeture exceptionnelle. Aucun échange au guichet n'est nécessaire. » Cela justifie la réponse : Le présenter directement à l'entrée."},{"number":3,"points":3,"passage":"La passerelle du port sera fermée aux cyclistes cet après-midi. Ils pourront emprunter le pont situé deux cents mètres plus loin.\n\nElle ajoute quelques minutes au trajet mais reste praticable avec une remorque pour enfant.","question":"Quel itinéraire est proposé aux cyclistes ?","options":["Prendre un bateau obligatoire","Traverser la passerelle à vélo","Attendre le lendemain","Passer par le pont voisin"],"correct":"D","explanation":"Le passage indique : « La passerelle du port sera fermée aux cyclistes cet après-midi. Ils pourront emprunter le pont situé deux cents mètres plus loin. » Cela justifie la réponse : Passer par le pont voisin."},{"number":4,"points":3,"passage":"Les bagages trouvés dans le train sont conservés au bureau de la gare, et non dans les consignes automatiques.\n\nLe service demande une description précise de l'objet et du trajet effectué. Une vérification sera faite avant toute restitution au propriétaire.","question":"Où chercher un bagage oublié ?","options":["Dans une consigne automatique","Au bureau de la gare","À l'arrêt du tramway","Dans le train suivant"],"correct":"B","explanation":"Le passage indique : « Les bagages trouvés dans le train sont conservés au bureau de la gare, et non dans les consignes automatiques. » Cela justifie la réponse : Au bureau de la gare."},{"number":5,"points":9,"passage":"Léa, n'achète pas encore le billet de retour. La famille qui m'accueille peut me recevoir deux jours de plus, mais je dois confirmer mon congé.\n\nJe préfère vérifier cette possibilité plutôt que changer deux fois la réservation et payer des frais inutiles.","question":"Pourquoi l'achat doit-il attendre ?","options":["Les billets sont tous gratuits","Le trajet est annulé définitivement","La durée du séjour reste incertaine","La famille refuse la visite"],"correct":"C","explanation":"Le passage indique : « Léa, n'achète pas encore le billet de retour. La famille qui m'accueille peut me recevoir deux jours de plus, mais je dois confirmer mon congé. » Cela justifie la réponse : La durée du séjour reste incertaine."},{"number":6,"points":9,"passage":"Notre auberge prête des draps, mais ne fournit pas de serviettes. La cuisine collective est ouverte jusqu'à vingt et une heures.\n\nLes voyageurs doivent aussi libérer leur lit avant dix heures le jour du départ.","question":"Que doit apporter le client ?","options":["Un réfrigérateur","Des draps","Une serviette","Une clé de cuisine"],"correct":"C","explanation":"Le passage indique : « Notre auberge prête des draps, mais ne fournit pas de serviettes. La cuisine collective est ouverte jusqu'à vingt et une heures. » Cela justifie la réponse : Une serviette."},{"number":7,"points":9,"passage":"Je préfère le train de nuit : il arrive tôt et m'évite une nuit d'hôtel. Il est plus lent que l'avion, mais cela ne me gêne pas.\n\nJe pourrai dormir pendant le trajet et commencer ma visite après le petit déjeuner.","question":"Quel avantage motive ce choix ?","options":["Arriver en soirée","Voyager sans réservation","Économiser une nuit d'hébergement","Atteindre la vitesse maximale"],"correct":"C","explanation":"Le passage indique : « Je préfère le train de nuit : il arrive tôt et m'évite une nuit d'hôtel. Il est plus lent que l'avion, mais cela ne me gêne pas. » Cela justifie la réponse : Économiser une nuit d'hébergement."},{"number":8,"points":9,"passage":"L'office propose une visite à pied gratuite, limitée à douze personnes. L'inscription est obligatoire pour éviter de refuser des visiteurs au départ.\n\nLes départs ont lieu devant l'office et durent environ une heure.","question":"Pourquoi faut-il s'inscrire ?","options":["La visite nécessite un passeport","Le nombre de participants est limité","L'entrée de la ville est payante","Le guide travaille uniquement en ligne"],"correct":"B","explanation":"Le passage indique : « L'office propose une visite à pied gratuite, limitée à douze personnes. L'inscription est obligatoire pour éviter de refuser des visiteurs au départ. » Cela justifie la réponse : Le nombre de participants est limité."},{"number":9,"points":9,"passage":"Chers voyageurs, votre arrêt habituel sera déplacé pendant le marché. Retrouvez le bus devant la poste, dans le même sens de circulation.\n\nLes voyageurs sont invités à prévoir quelques minutes de marche supplémentaires depuis leur arrêt habituel.","question":"Quel effet le marché a-t-il sur le trajet ?","options":["Tous les arrêts deviennent payants","Le bus circule en sens inverse","Le lieu d'embarquement change","Le service cesse pour la journée"],"correct":"C","explanation":"Le passage indique : « Chers voyageurs, votre arrêt habituel sera déplacé pendant le marché. Retrouvez le bus devant la poste, dans le même sens de circulation. » Cela justifie la réponse : Le lieu d'embarquement change."},{"number":10,"points":9,"passage":"Nous louerons des vélos à l'arrivée plutôt que transporter les nôtres. La location est un peu chère, mais évite les changements de train avec du matériel.\n\nLe magasin près de la gare garde les vélos réservés jusqu'à notre arrivée.","question":"Quelle contrainte veut-on éviter ?","options":["Réserver un hébergement","Transporter les vélos pendant les correspondances","Pédaler sur place","Acheter des boissons"],"correct":"B","explanation":"Le passage indique : « Nous louerons des vélos à l'arrivée plutôt que transporter les nôtres. La location est un peu chère, mais évite les changements de train avec du matériel. » Cela justifie la réponse : Transporter les vélos pendant les correspondances."},{"number":11,"points":15,"passage":"Une gare transforme un ancien guichet en salle d'attente chauffée. La vente de billets reste possible sur les bornes et auprès d'un agent mobile.\n\nL'espace dispose de bancs et d'une prise pour recharger un téléphone. Les voyageurs ont demandé cet aménagement après plusieurs hivers passés à attendre sur un quai exposé au vent. L'agent mobile circulera surtout pendant les heures d'affluence, avec un appareil permettant de consulter les horaires et les tarifs. La municipalité souhaite conserver une présence utile dans la gare sans rouvrir exactement l'ancien service. Un bilan sera réalisé après les premiers mois pour vérifier les besoins.","question":"Quel service subsiste malgré la transformation ?","options":["Une aide humaine pour acheter un billet","La vente de repas chauds","La gratuité de tous les billets","Un guichet ouvert sans interruption"],"correct":"A","explanation":"Le passage indique : « Une gare transforme un ancien guichet en salle d'attente chauffée. La vente de billets reste possible sur les bornes et auprès d'un agent mobile. » Cela justifie la réponse : Une aide humaine pour acheter un billet."},{"number":12,"points":15,"passage":"Le village limite les groupes guidés dans ses ruelles étroites. Il accueille toujours les visiteurs individuels et cherche surtout à éviter des blocages devant les maisons.\n\nLes visites accompagnées devront désormais respecter un horaire et s'arrêter sur quelques emplacements plus larges. Les guides recevront une carte des zones sensibles afin de préparer leur parcours. La mairie souhaite maintenir les rencontres avec les commerçants, sans empêcher les résidents de sortir de chez eux.","question":"Pourquoi limiter les groupes ?","options":["Supprimer les visites culturelles","Réserver les rues aux voitures","Interdire tout tourisme","Faciliter la circulation dans les ruelles"],"correct":"D","explanation":"Le passage indique : « Le village limite les groupes guidés dans ses ruelles étroites. Il accueille toujours les visiteurs individuels et cherche surtout à éviter des blocages devant les maisons. » Cela justifie la réponse : Faciliter la circulation dans les ruelles."},{"number":13,"points":15,"passage":"Pour découvrir la région, Adam choisit une carte valable plusieurs jours sur les bus locaux. Elle coûte davantage qu'un trajet simple, mais couvre ses excursions successives.\n\nIl a repéré plusieurs villages accessibles sans voiture, ainsi qu'un sentier dont le départ se trouve près d'un arrêt. Les horaires de retour lui permettent de rester assez longtemps sur place. Il a aussi prévu une journée libre pour adapter son programme à la météo. La carte ne comprend pas les activités touristiques, mais il estime que la simplicité des déplacements lui sera déjà très utile.","question":"Pourquoi cette carte lui convient-elle ?","options":["Elle inclut un hôtel","Il ne prendra jamais le bus","Il prévoit plusieurs déplacements","Elle interdit les correspondances"],"correct":"C","explanation":"Le passage indique : « Pour découvrir la région, Adam choisit une carte valable plusieurs jours sur les bus locaux. Elle coûte davantage qu'un trajet simple, mais couvre ses excursions successives. » Cela justifie la réponse : Il prévoit plusieurs déplacements."},{"number":14,"points":15,"passage":"Une association teste un pédibus scolaire. Des adultes accompagnent les enfants à pied selon un parcours fixe ; les familles rejoignent le groupe aux arrêts indiqués.\n\nLe parcours évite les rues les plus circulées et comporte plusieurs points de rassemblement clairement indiqués. Les accompagnateurs vérifient les présences avant de repartir, mais les parents restent responsables d'amener les enfants au bon endroit. L'école soutient l'essai pendant quelques semaines. Elle souhaite savoir si les familles peuvent s'organiser régulièrement, car une initiative agréable le premier jour ne devient pas automatiquement une solution fiable pour toute l'année.","question":"Qu'est-ce qu'un pédibus dans ce texte ?","options":["Un autocar touristique","Un prêt de bicyclettes","Un trajet à pied accompagné","Un cours de conduite"],"correct":"C","explanation":"Le passage indique : « Une association teste un pédibus scolaire. Des adultes accompagnent les enfants à pied selon un parcours fixe ; les familles rejoignent le groupe aux arrêts indiqués. » Cela justifie la réponse : Un trajet à pied accompagné."},{"number":15,"points":15,"passage":"Un refuge de montagne demande de réserver le dîner avant midi. Les produits sont acheminés en quantité limitée ; les randonneurs non inscrits peuvent dormir sans bénéficier du repas.\n\nLe responsable indique le menu prévu lors de la réservation et demande de signaler les besoins particuliers. Les quantités sont préparées selon le nombre annoncé, car il est difficile de se réapprovisionner rapidement à cette altitude. Le refuge préfère expliquer cette organisation avant l'arrivée plutôt que laisser croire qu'un repas supplémentaire peut toujours être improvisé à la fin d'une longue journée de marche.","question":"Pourquoi anticiper la réservation du dîner ?","options":["Réserver toutes les chambres","Éviter les frais de transport des clients","Adapter des provisions limitées","Permettre un service nocturne permanent"],"correct":"C","explanation":"Le passage indique : « Un refuge de montagne demande de réserver le dîner avant midi. Les produits sont acheminés en quantité limitée ; les randonneurs non inscrits peuvent dormir sans bénéficier du repas. » Cela justifie la réponse : Adapter des provisions limitées."},{"number":16,"points":15,"passage":"Le guide enregistre les témoignages des habitants pour une promenade sonore. Les lieux sont présentés par ceux qui y vivent, et pas seulement par des informations historiques officielles.\n\nDes récits décrivent par exemple le travail au port, les jeux dans une ancienne cour et les commerces disparus. Les visiteurs suivent une carte et déclenchent les enregistrements devant les lieux concernés. Les témoignages sont présentés avec leur date et leur contexte. L'équipe ne veut pas remplacer toute recherche historique par des souvenirs : elle souhaite ajouter une perspective quotidienne à la découverte.","question":"Quelle particularité offre cette promenade ?","options":["La parole des habitants enrichit la visite","Les informations historiques sont interdites","Le visiteur doit devenir guide","Les monuments sont tous reconstruits"],"correct":"A","explanation":"Le passage indique : « Le guide enregistre les témoignages des habitants pour une promenade sonore. Les lieux sont présentés par ceux qui y vivent, et pas seulement par des informations historiques officielles. » Cela justifie la réponse : La parole des habitants enrichit la visite."},{"number":17,"points":15,"passage":"Après l'ouverture d'une piste cyclable, la commune interroge aussi ceux qui ne l'utilisent pas. Leurs réponses peuvent révéler des obstacles que les cyclistes réguliers ne remarquent plus.\n\nCertaines personnes évoquent un manque de stationnement sûr à l'arrivée, d'autres un carrefour qui leur fait peur. Ces réponses ne demandent pas toutes le même investissement. Le service technique les comparera aux observations faites sur le terrain. La commune veut éviter de conclure trop vite qu'une piste peu fréquentée serait inutile ou que tous les habitants devraient simplement changer leurs habitudes.","question":"Pourquoi consulter les non-utilisateurs ?","options":["Les obliger à acheter un vélo","Comprendre ce qui freine l'usage","Fixer le prix des voitures","Remplacer les cyclistes dans l'enquête"],"correct":"B","explanation":"Le passage indique : « Après l'ouverture d'une piste cyclable, la commune interroge aussi ceux qui ne l'utilisent pas. Leurs réponses peuvent révéler des obstacles que les cyclistes réguliers ne remarquent plus. » Cela justifie la réponse : Comprendre ce qui freine l'usage."},{"number":18,"points":15,"passage":"Un hôtel proche de la gare garde gratuitement les sacs après le départ des clients. Le service ne prolonge pas l'accès aux chambres, qui doivent être libérées à onze heures.\n\nLes sacs seront étiquetés et rangés dans une pièce fermée, accessible avec l'aide du personnel. Les voyageurs pourront ainsi poursuivre leur visite avant de rejoindre leur train. L'hôtel rappelle toutefois que les objets précieux doivent rester avec leurs propriétaires. Il souhaite rendre ce service pratique sans créer de confusion sur l'heure de départ.","question":"Quelle distinction faut-il faire ?","options":["Les chambres deviennent des consignes publiques","Les sacs doivent quitter l'hôtel à onze heures","Le dépôt inclut une nouvelle nuit","Déposer ses sacs ne permet pas de garder sa chambre"],"correct":"D","explanation":"Le passage indique : « Un hôtel proche de la gare garde gratuitement les sacs après le départ des clients. Le service ne prolonge pas l'accès aux chambres, qui doivent être libérées à onze heures. » Cela justifie la réponse : Déposer ses sacs ne permet pas de garder sa chambre."},{"number":19,"points":15,"passage":"La ville ajoute des plans lisibles à hauteur des enfants dans les stations. Ils indiquent des repères simples, sans remplacer la signalisation générale.\n\nLes enfants ont participé au choix des dessins, après avoir essayé plusieurs versions dans une station témoin. Les adultes peuvent également utiliser ces repères lorsqu'ils découvrent le réseau. Les noms des lignes et les règles de sécurité restent communs à tous ; l'objectif est d'ajouter une manière de lire l'espace, sans créer deux réseaux d'informations contradictoires.","question":"Quel objectif est poursuivi ?","options":["Rendre l'orientation plus accessible aux jeunes","Réserver les stations aux familles","Augmenter le nombre de correspondances","Supprimer les noms des lignes"],"correct":"A","explanation":"Le passage indique : « La ville ajoute des plans lisibles à hauteur des enfants dans les stations. Ils indiquent des repères simples, sans remplacer la signalisation générale. » Cela justifie la réponse : Rendre l'orientation plus accessible aux jeunes."},{"number":20,"points":21,"passage":"Les excursions vers une île dépendaient d'un seul bateau matinal. Un second départ tardif a réparti les visiteurs dans la journée. Les commerçants observent moins d'affluence simultanée, mais souhaitent mesurer le résultat sur toute la saison. Les habitants espèrent aussi que cette répartition limitera les files devant les petites attractions de l'île. Des informations seront recueillies auprès des visiteurs ayant choisi chaque départ. Les responsables veulent notamment vérifier si le nouveau service permet des séjours plus agréables ou déplace simplement l'affluence vers une autre heure, sans résoudre les difficultés signalées.","question":"Quelle prudence accompagne le premier bilan ?","options":["Attendre une observation plus longue","Conclure à une baisse certaine des visiteurs","Fermer les commerces le matin","Supprimer immédiatement le second bateau"],"correct":"A","explanation":"Le passage indique : « Les excursions vers une île dépendaient d'un seul bateau matinal. Un second départ tardif a réparti les visiteurs dans la journée. Les commerçants observent moins d'affluence simultanée, mais souhaitent mesurer le résultat sur toute la saison. » Cela justifie la réponse : Attendre une observation plus longue."},{"number":21,"points":21,"passage":"Une entreprise rembourse une partie des déplacements professionnels en train, même lorsque le billet dépasse légèrement le prix d'un vol. Elle intègre au calcul le temps consacré aux transferts et aux attentes. Elle compare donc la durée entre les lieux de travail, plutôt qu'entre deux points de départ seulement. Les salariés doivent préciser les correspondances nécessaires et les possibilités de travailler pendant le trajet. Cette méthode n'impose pas une solution identique dans chaque cas, mais rend la décision moins dépendante d'une différence de tarif isolée.","question":"Quelle comparaison pratique-t-elle ?","options":["Elle exclut tout temps d'attente","Elle compare uniquement les repas","Elle retient seulement le prix affiché","Elle considère le trajet dans son ensemble"],"correct":"D","explanation":"Le passage indique : « Une entreprise rembourse une partie des déplacements professionnels en train, même lorsque le billet dépasse légèrement le prix d'un vol. Elle intègre au calcul le temps consacré aux transferts et aux attentes. » Cela justifie la réponse : Elle considère le trajet dans son ensemble."},{"number":22,"points":21,"passage":"Un circuit propose de rencontrer un artisan dans son atelier. Les visites sont suspendues pendant les commandes urgentes. L'activité touristique doit compléter le métier de l'artisan, pas empêcher sa production. Les petits groupes sont prévenus que les horaires peuvent changer et qu'ils ne verront pas toujours la même étape de fabrication. L'artisan préfère expliquer un travail réel plutôt que répéter une démonstration à la demande. L'office de tourisme accepte cette souplesse et propose d'autres visites lorsque l'atelier doit se concentrer sur sa production.","question":"Quel principe organise ces visites ?","options":["Respecter l'activité principale de l'atelier","Garantir une ouverture touristique permanente","Transformer toutes les commandes en visites","Remplacer le métier par des spectacles"],"correct":"A","explanation":"Le passage indique : « Un circuit propose de rencontrer un artisan dans son atelier. Les visites sont suspendues pendant les commandes urgentes. L'activité touristique doit compléter le métier de l'artisan, pas empêcher sa production. » Cela justifie la réponse : Respecter l'activité principale de l'atelier."},{"number":23,"points":21,"passage":"Dans une vallée, les navettes estivales sont devenues gratuites pour les visiteurs munis d'une réservation d'hébergement. Les habitants demandent un accès identique : ils utilisent les mêmes routes et subissent aussi la circulation touristique. La commune avait conçu l'offre pour réduire les trajets automobiles des vacanciers, mais les associations locales estiment que les besoins permanents ne doivent pas être oubliés. Les responsables souhaitent trouver un financement stable avant d'étendre la gratuité, afin de ne pas annoncer un droit qui disparaîtrait après une seule saison.","question":"Que revendiquent les habitants ?","options":["Un traitement équitable pour les trajets locaux","Une priorité pour les touristes étrangers","Le rétablissement des embouteillages","La fermeture des hébergements"],"correct":"A","explanation":"Le passage indique : « Dans une vallée, les navettes estivales sont devenues gratuites pour les visiteurs munis d'une réservation d'hébergement. Les habitants demandent un accès identique : ils utilisent les mêmes routes et subissent aussi la circulation touristique. » Cela justifie la réponse : Un traitement équitable pour les trajets locaux."},{"number":24,"points":21,"passage":"Une application conseille les itinéraires les plus rapides, mais ignore les escaliers. Une voyageuse avec poussette indique qu'un trajet légèrement plus long peut lui éviter un obstacle impossible à franchir seule. Les utilisateurs ont notamment besoin de savoir si un passage comporte des marches ou un trottoir difficile. La voyageuse demande que ces informations apparaissent avant le choix du trajet. Elle souhaite pouvoir décider elle-même du compromis acceptable entre durée et effort, plutôt que recevoir un itinéraire présenté comme idéal sur un seul critère.","question":"Quelle limite de l'application est montrée ?","options":["La poussette empêche tout déplacement","Tous les itinéraires sont trop longs","Les escaliers accélèrent chaque trajet","La rapidité ne garantit pas l'accessibilité"],"correct":"D","explanation":"Le passage indique : « Une application conseille les itinéraires les plus rapides, mais ignore les escaliers. Une voyageuse avec poussette indique qu'un trajet légèrement plus long peut lui éviter un obstacle impossible à franchir seule. » Cela justifie la réponse : La rapidité ne garantit pas l'accessibilité."},{"number":25,"points":21,"passage":"Un village réduit le stationnement au centre et finance son nouvel accès piéton avec les recettes d'un parking extérieur. Six mois plus tard, les sommes encaissées baissent. Le conseil examine plusieurs données avant de revoir le financement. Les véhicules payants restent en moyenne aussi longtemps qu'auparavant, et la proposition de remise sur les courts séjours n'a pas été adoptée. Les habitants conservent leur gratuité habituelle; leur part dans les entrées n'a pas augmenté. En revanche, davantage de visiteurs arrivent en bus ou à vélo. Les comptages du centre et les passages devant les commerces restent soutenus. La mairie prévoit une contribution fixe pour l'entretien du chemin, dont profitent également les visiteurs arrivés sans voiture. Elle veut éviter de juger l'utilité de cet accès à partir des seules recettes automobiles.","question":"Quel mécanisme explique la baisse des recettes dans la situation décrite ?","options":["Les durées de stationnement payant raccourcissent, ce qui réduit les versements malgré un nombre comparable de voitures accueillies.","Le tarif appliqué aux courts séjours diminue, ce qui réduit les versements malgré des durées de stationnement comparables.","La proportion de véhicules bénéficiant d'une gratuité augmente, ce qui réduit les versements malgré une fréquentation automobile comparable.","Une partie des visiteurs change de mode de déplacement, ce qui réduit les versements malgré une fréquentation du centre soutenue."],"correct":"D","explanation":"D. Les visites au centre se maintiennent, mais davantage de visiteurs viennent en bus ou à vélo et ne paient donc pas le parking. A suppose une réduction des durées, restées comparables. B transforme une remise proposée en tarif adopté. C suppose une hausse de la part des gratuités, que le bilan exclut."},{"number":26,"points":21,"passage":"Une famille organise dix jours autour de deux étapes longues. Elle réserve ses logements et un spectacle joué une seule fois pendant son séjour; les autres visites restent modifiables. Les enfants souhaitent surtout participer à une activité du quotidien, plutôt que multiplier les lieux à photographier. Sur place, une voisine les invite à préparer la fête du quartier le dimanche après-midi. Ce moment de préparation n'est pas ouvert habituellement aux visiteurs. La famille avait envisagé une excursion au monument ce jour-là, mais celui-ci sera encore accessible les jours suivants. L'atelier artisanal propose, quant à lui, des visites commentées chaque matin: on y observe les gestes, sans les pratiquer. Les parents cherchent à garder leur rendez-vous culturel réservé tout en répondant au souhait des enfants. Ils n'ont pas encore acheté les billets du monument ni de l'atelier.","question":"Quelle décision correspondrait à la priorité que la famille se donne dans cette situation ?","options":["Maintenir le spectacle et réserver la visite du monument, en renonçant à participer à la préparation de la fête.","Maintenir le spectacle et participer à la préparation de la fête, en reportant la visite du monument.","Maintenir la visite du monument et participer à la préparation de la fête, en échangeant les places du spectacle.","Maintenir le spectacle et observer les artisans à l'atelier, en réservant la visite du monument pour un prochain séjour."],"correct":"B","explanation":"B. La préparation de la fête offre une participation ponctuelle à la vie locale; le monument peut être reporté sans toucher au spectacle réservé. A privilégie la visite d'un site au détriment du souhait exprimé. C suppose qu'une autre représentation permet l'échange, alors que le spectacle n'est joué qu'une fois. D choisit une observation régulière de l'artisanat, plutôt que la participation recherchée."},{"number":27,"points":21,"passage":"Avant l'inscription à une promenade, une participante en fauteuil demande des précisions sur l'ensemble de la sortie. Le minibus possède une plateforme élévatrice dont les dimensions ont été vérifiées avec elle. Les sanitaires du point de pause sont accessibles par une rampe, et un véhicule adapté pourra la ramener depuis cet arrêt si elle souhaite écourter la sortie. L'organisatrice transmet aussi le compte rendu de reconnaissance: au-delà de l'arrêt, une passerelle est trop étroite pour le fauteuil. La variante indiquée sur la carte comporte des marches. La participante veut poursuivre jusqu'au point de vue avec les autres et ne considère pas le retour anticipé comme un remplacement de cette possibilité. L'organisatrice cherche donc une adaptation avant de confirmer qu'elle pourra accomplir le même parcours que le groupe.","question":"Quelle adaptation reste nécessaire pour répondre à la demande de la participante ?","options":["Prévoir un passage assez large, sans marches, permettant de rejoindre le point de vue avec le groupe.","Prévoir une plateforme élévatrice compatible avec le fauteuil, permettant de monter dans le véhicule de liaison avec le groupe.","Prévoir une rampe jusqu'aux sanitaires du point de pause, permettant de les utiliser pendant l'arrêt du groupe.","Prévoir un véhicule adapté au point de pause, permettant de rentrer avant la fin du parcours du groupe."],"correct":"A","explanation":"A. Le transport, les sanitaires et le retour anticipé disposent déjà des adaptations décrites. Le passage vers le point de vue reste infranchissable, et la participante souhaite poursuivre avec le groupe. B, C et D sont des conditions d'accès pertinentes, mais les confondent avec le besoin encore non résolu."},{"number":28,"points":21,"passage":"Sur un réseau rural, les validations électroniques semblent indiquer une fréquentation faible. Le registre est alimenté par les lecteurs installés dans les bus: chaque passage d'une carte sur un lecteur produit une inscription. Une correspondance demande de repasser la carte dans le second véhicule, même lorsque le titre reste valable pour tout le voyage. Les abonnés annuels bénéficiaient cependant d'une procédure particulière: ils montraient leur carte au conducteur et montaient sans utiliser le lecteur. Pendant un essai, leurs cartes doivent suivre la même procédure que les autres titres. Les inscriptions augmentent, tandis que les agents qui comptent les voyageurs aux mêmes horaires relèvent des effectifs proches des précédents. Les élus demandent un exemple concret permettant de comprendre le passage de l'ancienne procédure à la nouvelle.","question":"Une abonnée annuelle effectue un trajet avec une correspondance sur ce réseau. Combien d'inscriptions ce trajet aurait-il produites avant et pendant l'essai ?","options":["Aucune avant l'essai, puis une pendant l'essai.","Une avant l'essai, puis deux pendant l'essai.","Aucune avant l'essai, puis deux pendant l'essai.","Une avant l'essai, puis une pendant l'essai."],"correct":"C","explanation":"C. Avant l'essai, l'abonnée présente sa carte sans utiliser les lecteurs: le registre électronique ne reçoit aucune inscription. Pendant l'essai, elle la passe à chaque montée, donc dans chacun des deux véhicules. A confond un voyage avec une seule montée; B transforme l'ancien contrôle visuel en inscription électronique; D cumule ces deux confusions."},{"number":29,"points":21,"passage":"Une destination ouvre six semaines supplémentaires en automne. Le groupe de travail avait envisagé plusieurs bénéfices: tarifs plus accessibles, séjours plus longs, visites mieux réparties entre quartiers et emplois moins intermittents. Le premier essai remplit les hôtels les week-ends, mais les fermetures entre ces pointes empêchent les restaurants et le transport local de garder une équipe continue. Les professionnels doivent encore rappeler du personnel pour quelques journées. Des hôtels proposent des forfaits prolongés et l'office prépare des circuits vers d'autres quartiers; ces initiatives restent utiles, mais ne règlent pas cette alternance d'ouvertures et d'arrêts. Pour la seconde période, les acteurs coordonnent leurs jours de service et calculent les recettes nécessaires à leur maintien. Le bilan de renouvellement devra montrer que cette organisation peut fonctionner pendant toute la période, et pas seulement améliorer un autre aspect de l'offre touristique.","question":"Quel résultat répondrait au problème que la seconde période d'essai doit résoudre ?","options":["Sur six semaines, les recettes supplémentaires financent des tarifs réduits qui permettent de recevoir davantage de familles modestes.","Sur six semaines, les réservations régulières couvrent l'ouverture coordonnée des services et permettent de maintenir des contrats continus.","Sur six semaines, les séjours prolongés réduisent les rotations de chambres et permettent aux hôtels de mieux amortir leur entretien.","Sur six semaines, les circuits proposés répartissent les achats entre plusieurs quartiers et permettent de soutenir davantage de petits commerces."],"correct":"B","explanation":"B. Le problème retenu est l'alternance de pointes et de fermetures qui maintient un emploi intermittent. Des réservations régulières couvrant les services ouverts ensemble permettent d'y répondre. A, C et D décrivent des résultats cohérents avec d'autres bénéfices envisagés, mais ne montrent pas que l'ouverture et les contrats peuvent durer pendant toute la période."},{"number":30,"points":26,"passage":"Une commune compare deux groupes de touristes accueillis pendant les mêmes journées de mai. Le premier reste trois nuits dans un complexe vendu avec les repas par une agence extérieure. Ses membres dépensent davantage au total, mais paient l'essentiel de leurs prestations dans le forfait; leurs achats directs auprès des entreprises de la commune restent limités. Le second groupe ne vient qu'une journée et achète des repas et des produits chez des commerçants indépendants. Le dossier rassemble les factures de forfait et les tickets des achats supplémentaires payés sur place. Les pièces de caisse montrent que ces entreprises reçoivent davantage du second groupe. L’enquête porte sur ces ventes directes; elle ne suit pas les reversements du forfait aux prestataires. Les montants retenus correspondent à des paiements effectués, non aux budgets annoncés avant le voyage. L'étude ne calcule pas encore les charges publiques d'entretien et de circulation, qui feront l'objet d'un autre volet. Un élu classe néanmoins le premier groupe devant le second en additionnant les nuitées. Le service économique demande de compléter ce classement à partir de la différence mise en évidence par son enquête.","question":"Quelle différence constatée entre les groupes fonde la réserve du service économique ?","options":["Le séjour long entraîne une dépense totale plus élevée, mais moins de paiements directs aux entreprises de la commune.","Le séjour long entraîne des recettes locales plus élevées, mais un bénéfice local net plus faible après déduction des charges publiques.","Le séjour long paraît plus dépensier sur la base de budgets annoncés qui incluent des achats ensuite abandonnés.","Le séjour long paraît plus dépensier parce que les repas inclus dans le forfait sont comptés une nouvelle fois parmi les achats directs."],"correct":"A","explanation":"A. Le groupe qui reste davantage dépense plus au total, mais le groupe de passage apporte plus de paiements directs aux entreprises locales étudiées. L'enquête ne suit pas les reversements du forfait et ne permet pas d'en déduire toutes les recettes locales indirectes. B suppose un bilan net après charges publiques, encore à réaliser. C utilise des budgets annoncés au lieu des paiements effectués. D prend les tickets d'achats supplémentaires pour une seconde comptabilisation des repas déjà inclus dans le forfait."},{"number":31,"points":26,"passage":"Deux réseaux adoptent un billet commun, mais le dernier train arrive à 22 h 12 alors que le dernier bus part à 22 h 10. L'équipe examine quatre ajustements. Le train ne peut être avancé sans faire perdre une correspondance qui l'alimente dans la ville voisine. Le dernier bus dessert trois quartiers où des voyageurs descendent encore à cette heure; la commune maintient donc toute sa boucle. Aucun véhicule ni conducteur supplémentaire n'est disponible pour une navette. En revanche, le véhicule de cette dernière course n'assure plus d'autre ligne, et son conducteur dispose d'une marge de quinze minutes avant la fin de son service. Les horaires scolaires du matin doivent rester en place, mais ils ne dépendent pas de l'heure de retour de ce bus le soir. Le billet unique règle déjà l'achat: le choix porte maintenant sur une correspondance réalisable avec les moyens prévus.","question":"Quel ajustement peut être retenu en respectant les contraintes décrites ?","options":["Avancer l'arrivée du dernier train tout en conservant les horaires de départ et le tracé de la ligne de bus.","Retarder le départ du dernier bus et raccourcir sa boucle pour conserver son heure actuelle de retour au dépôt.","Créer une navette après le dernier train tout en conservant les départs et les parcours de la ligne régulière.","Retarder le départ du dernier bus et décaler son retour au dépôt tout en conservant l'intégralité de sa boucle."],"correct":"D","explanation":"D. Le dernier véhicule n'a plus d'autre service et son conducteur dispose de la marge nécessaire pour terminer plus tard; il peut attendre le train sans supprimer de quartier. A compromet la correspondance amont. B enlève une partie de la desserte que la commune conserve. C nécessite un véhicule et un conducteur supplémentaires qui ne sont pas disponibles."},{"number":32,"points":26,"passage":"Un circuit promet une rencontre avec la vie « authentique » d'un village. Une chercheuse assiste aux démonstrations préparées à heure fixe par des habitants rémunérés. Elle observe des gestes réellement pratiqués et relève que les participants ont choisi les séquences, l'agence s'occupant du transport et des réservations. Pendant la visite, les artisans expliquent dans quelles occasions familiales et collectives ils utilisent ces savoir-faire. Deux familles montrent aussi des variantes, au lieu de suivre un modèle unique. La chercheuse s'intéresse ensuite aux images publicitaires, qui montrent les voyageurs entrant dans un atelier comme s'ils passaient simplement devant une porte ouverte. Plusieurs visiteurs interrogés racontent avoir eu la chance d'arriver au moment où les habitants se réunissaient. Or les démonstrations commencent après l'arrivée du groupe, dont la visite a été réservée plusieurs semaines auparavant. La chercheuse ne conteste pas l'intérêt de la rencontre; elle confronte ce que l'enquête établit à ce que les visiteurs pensent avoir rencontré.","question":"Quel décalage entre la visite observée et sa compréhension par le public ressort de l'enquête ?","options":["Des gestes locaux sont montrés, mais leur sélection par l'agence est comprise comme l'expression des choix propres aux habitants.","Des gestes locaux sont montrés, mais leur présentation à un rendez-vous préparé est comprise comme une scène rencontrée spontanément.","Des gestes locaux sont montrés, mais leur présentation sans contexte est comprise comme une description de leurs usages sociaux.","Des gestes locaux sont montrés, mais leur version uniformisée pour le circuit est comprise comme représentative des différentes traditions familiales."],"correct":"B","explanation":"B. Le groupe réserve une démonstration à heure fixe, tandis que des visiteurs pensent être arrivés par chance pendant une réunion ordinaire. A attribue la sélection à l'agence, alors que les habitants choisissent les séquences. C suppose une absence de contexte social, malgré les explications données. D suppose une uniformisation, alors que plusieurs variantes familiales sont montrées."},{"number":33,"points":26,"passage":"Après l'ouverture de cinq kilomètres de piste, une ville doit choisir son prochain chantier parmi quatre besoins de sécurité. Les salariés de la zone d'activités signalent les croisements avec les camions de livraison. Près de la gare, des usagers demandent des locaux fermés après plusieurs vols. La branche qui conduit à la bibliothèque comporte un revêtement déformé susceptible de provoquer des chutes. La ville interroge aussi les parents qu'elle souhaite encourager à accompagner leurs enfants à vélo vers l'école. Leur trajet n'emprunte aucune de ces trois sections, et l'école dispose déjà d'un espace fermé pour les vélos. Ces familles s'arrêtent surtout à la fin de la piste: pour rejoindre l'école, elles doivent traverser deux files de circulation sans protection. Une sortie accompagnée leur a permis de franchir ce point, mais elles n'ont pas repris le trajet seules. La fréquentation globale augmente déjà grâce aux cyclistes réguliers; l'objectif de cette consultation porte sur le début d'une nouvelle pratique familiale.","question":"Quel chantier répondrait au frein identifié chez le public visé par cette consultation ?","options":["Aménager une traversée protégée entre la fin de la piste et l'accès à l'école pour éviter le franchissement des files sans protection.","Séparer la piste des mouvements de camions près de la zone d'activités pour éviter les croisements dangereux pendant les livraisons.","Installer des locaux fermés près de la gare pour réduire le risque de vol lorsque les usagers y laissent leur vélo.","Reprendre le revêtement déformé sur la branche de la bibliothèque pour réduire le risque de chute lors du passage des vélos."],"correct":"A","explanation":"A. La consultation vise les familles qui veulent rejoindre l'école; leur obstacle se situe entre la fin de la piste et cette destination. B, C et D répondent à des risques réels et sérieux, mais sur d'autres sections que ces familles n'empruntent pas. Le choix demandé dépend du public et de son trajet, pas d'une hiérarchie abstraite entre les risques."},{"number":34,"points":26,"passage":"Après l'instauration d'un billet destiné à restaurer un belvédère, des habitants demandent de conserver leurs arrêts improvisés pendant une promenade. La mairie leur accorde un titre gratuit, utilisable plusieurs fois par semaine, et prolonge l'ouverture jusqu'à vingt-deux heures. Elle organise cependant l'accès par créneaux d'une heure, à réserver au plus tard la veille. Chaque créneau comporte trente places, partagées entre résidents et autres visiteurs. Une réservation reste utilisable jusqu'à la fin de son créneau, même si son détenteur arrive en cours de période ou revient après une sortie. L'association suit le fonctionnement du guichet un samedi. À quinze heures vingt, l'écran de la tranche quinze-seize heures affiche trente réservations et aucune place disponible; les tranches voisines disposent encore de places. Le journal d'accès de cette tranche indique douze entrées et cinq sorties, tous titres confondus. Un comptage sur place confirme que sept personnes sont présentes. Deux résidents sans réservation se voient refuser l'accès. L'agent montre le nombre de réservations, tandis que l'association consulte les passages enregistrés depuis quinze heures. Les habitants comprennent la nécessité de limiter la présence simultanée, mais demandent ce que signifie ici un créneau « complet » et pourquoi les nouveaux titres ne leur ont pas rendu leur ancien usage du lieu.","question":"Quel mécanisme explique l’écart entre l’affichage « complet » et la présence relevée pendant ce créneau ?","options":["Le guichet agrège les réservations de plusieurs créneaux, tandis que le compteur suit les présences du seul créneau en cours.","Le guichet applique aux résidents un quota distinct, tandis que le compteur additionne toutes les catégories de visiteurs.","Le guichet retient les entrées enregistrées sans déduire les sorties, tandis que le compteur mesure la présence effective.","Le guichet conserve les places des visiteurs encore attendus, tandis que le compteur mesure les seules présences effectives."],"correct":"D","explanation":"D. Les trente places du créneau sont attribuées à des réservations qui restent utilisables jusqu'à seize heures, y compris pour une arrivée tardive ou un retour après une sortie. Le système maintient donc une capacité pour des personnes encore susceptibles de venir, alors que le comptage constate sept présences. A confond les créneaux: les trente réservations concernent précisément quinze-seize heures, et les tranches voisines gardent des places. B suppose un quota propre aux résidents, alors que les trente places sont partagées entre tous les titres. C ne suffit pas à expliquer l'affichage: même sans déduire les cinq sorties, les douze entrées enregistrées restent inférieures aux trente places. La gratuité et les horaires élargis ne changent pas cette différence entre un droit de visite réservé et une présence effective."},{"number":35,"points":26,"passage":"Une gare affiche six minutes pour une correspondance, d'après une moyenne entre deux quais. Des voyageurs signalent pourtant des difficultés à la réaliser. L'association des usagers consulte les relevés: le passage par les escaliers prend de trois à quatre minutes; celui par les ascenseurs, de huit à douze minutes, attente comprise. Ces durées s'arrêtent à l'arrivée sur le second quai. Pour rejoindre sa porte et monter, il faut ensuite une minute sans bagage encombrant, deux avec un chariot. Le règlement ferme les portes une minute avant l'heure de départ indiquée. La direction envisage une nouvelle valeur commune de neuf minutes. Un agent examine plutôt deux projets précis. Clara et Malik arrivent tous deux à quatorze heures et veulent prendre le train de quatorze heures dix. Clara connaît la gare, mais son chariot impose le parcours par les ascenseurs. Malik vient pour la première fois; il voyage léger et prendra les escaliers. L'agent dispose des durées relevées pour ces conditions et doit dire si chaque projet reste possible, en tenant compte de l'embarquement.","question":"Quelle réponse est compatible avec les durées fournies et la règle d'embarquement ?","options":["La correspondance reste possible pour Clara et pour Malik.","La correspondance reste possible pour Malik, mais pas pour Clara.","La correspondance reste possible pour Clara, mais pas pour Malik.","La correspondance n'est possible ni pour Clara ni pour Malik."],"correct":"B","explanation":"B. Les portes ferment à 14 h 09: neuf minutes sont disponibles. Clara a besoin d'au moins huit minutes par les ascenseurs, puis de deux pour embarquer avec son chariot, soit dix. Malik a besoin d'au plus quatre minutes par les escaliers, puis d'une pour embarquer, soit cinq. A applique à tort une durée commune favorable aux deux. C privilégie la connaissance de la gare en inversant les parcours réellement prévus. D peut résulter de l'application à tous des neuf minutes envisagées, auxquelles on ajouterait l'embarquement."},{"number":36,"points":33,"passage":"Une métropole annonce un trajet ferroviaire de quinze minutes vers son aéroport. Le chiffre est exact entre les deux gares, mais une association mesure le déplacement depuis plusieurs quartiers jusqu'au terminal. Elle inclut l'accès, l'attente et la marche finale. Train et bus sont observés aux mêmes heures, en période creuse comme en pointe; les trajets comportant une correspondance manquée restent dans le relevé avec leur attente supplémentaire. Depuis le quartier de la gare, le train demande trente-trois minutes en moyenne contre quarante en bus. Depuis un quartier périphérique, il faut cinquante-cinq minutes par le train contre quarante-sept en bus direct. La société veut remplacer son affiche par « Trente-cinq minutes de porte à porte », moyenne de l'ensemble des trajets recueillis, où les départs proches de la gare sont majoritaires. L'association reconnaît que cette mesure couvre désormais le déplacement complet. Elle demande pourtant une autre présentation pour aider les habitants à choisir leur mode de transport depuis leur quartier.","question":"Quel défaut de l'affiche de remplacement subsiste au regard des données présentées ?","options":["Elle oppose des trajets ferroviaires relevés en période creuse à des trajets en bus relevés aux heures de pointe.","Elle présente comme complet un temps qui inclut l'accès à la gare, mais s'arrête avant la marche dans le terminal.","Elle présente une moyenne commune à des points de départ pour lesquels le classement du train et du bus s'inverse.","Elle utilise une moyenne calculée sur les correspondances réussies, en retirant les trajets où une attente supplémentaire a été nécessaire."],"correct":"C","explanation":"C. Le train est plus rapide depuis la gare, mais le bus l'est depuis la périphérie. Une moyenne commune, dominée par les origines proches de la gare, masque donc cette différence pertinente pour choisir. A décrit un déséquilibre horaire que le protocole exclut. B omet la marche finale pourtant incluse. D suppose une sélection des seuls trajets réussis, alors que les attentes après correspondance manquée restent comptées."},{"number":37,"points":33,"passage":"Une région présente le nombre de lits disponibles le long d'un itinéraire à vélo. Un binôme prévoit une nuit dans la zone des Collines, puis une nuit dans la zone du Lac. Les hébergements proposés sont proches de la piste et peuvent recevoir les deux personnes ensemble. La centrale transmet les conditions des deux zones. Aux Collines, les réservations d'une seule nuit sont ouvertes du lundi au mercredi; les autres arrivées exigent trois nuits. Une dérogation permet toutefois d'y réserver le jeudi pour une seule nuit, à partir de quatre cyclistes voyageant ensemble. Au Lac, les nuits du jeudi et du vendredi sont proposées séparément; pour une arrivée les autres jours, il faut réserver au moins trois nuits. Le binôme envisageait d'abord le lundi et le mardi. Il peut déplacer son départ dans la semaine, mais conserve le sens Collines puis Lac, une étape par jour et deux nuits au total. Les voyageurs souhaitent rester tous les deux. Le total hebdomadaire des lits paraît suffisant; ils doivent choisir les dates de leur réservation.","question":"Quel choix de dates respecte les conditions des deux zones tout en conservant le projet du binôme ?","options":["La nuit du lundi aux Collines, puis celle du mardi au Lac.","La nuit du mardi aux Collines, puis celle du mercredi au Lac.","La nuit du jeudi aux Collines, puis celle du vendredi au Lac.","La nuit du mercredi aux Collines, puis celle du jeudi au Lac."],"correct":"D","explanation":"D. Le mercredi fait partie des nuits réservables seules aux Collines, et le jeudi peut être réservé seul au Lac. A et B placent l'arrivée au Lac un jour imposant au moins trois nuits. C utilise le jeudi autorisé aux Collines par dérogation, mais celle-ci exige au moins quatre cyclistes; le binôme souhaite rester à deux. La capacité totale doit donc être rapprochée des jours, de la durée minimale et de la taille du groupe."},{"number":38,"points":33,"passage":"Un parc limite les réservations entre dix et dix-huit heures. Le quota porte sur les personnes, qu'elles viennent seules ou avec un guide. Le bilan administratif montre moins d'entrées dans ce créneau. Plusieurs prestataires proposent toutefois des départs avant sept heures sur les mêmes sentiers. Les compteurs de chacun de ces chemins fonctionnent toute la journée et relèvent un total de passages proche de celui de l'année précédente. Le suivi des sorties indique également une durée moyenne de présence comparable. Les naturalistes constatent en revanche moins de périodes tranquilles au lever du jour, moment où certaines espèces se nourrissent après la nuit. Les responsables avaient choisi le créneau réglementé selon les anciennes heures de pointe touristiques, sans étudier ce rythme animal. Ils préparent maintenant un bilan reliant les heures de passage aux observations de la faune. Le respect des quotas reste suivi, mais il ne suffit plus à expliquer la situation des animaux dans les secteurs traversés.","question":"Quel mécanisme explique la divergence entre le bilan administratif et le constat écologique ?","options":["Des visites se déplacent vers l'aube, exposant la faune pendant une période sensible malgré une fréquentation quotidienne presque inchangée.","Les visiteurs restent plus longtemps sur place, réduisant les intervalles de tranquillité malgré la baisse du nombre d'entrées enregistrées.","Des visites se déplacent vers des sentiers moins comptés, exposant de nouvelles zones de la faune malgré la baisse des entrées officielles.","Les groupes accueillent davantage de personnes, augmentant la présence humaine malgré la baisse du nombre de réservations accordées aux groupes."],"correct":"A","explanation":"A. Les passages se déplacent vers l'aube, qui correspond à une activité sensible de la faune, alors que le total quotidien change peu. B attribue le problème à des visites plus longues, malgré une durée moyenne comparable. C suppose un déplacement spatial hors des compteurs, alors que les mêmes sentiers sont suivis toute la journée. D confond un quota par personne avec un quota par groupe."},{"number":39,"points":33,"passage":"Une plateforme recommande trois petites places pour éviter les lieux surfréquentés. Les trois sont gratuites, accessibles aux mêmes heures, et aucune animation n'est programmée pendant l'essai. Les itinéraires proposés empruntent des chemins distincts, sans point de passage commun. Les noms changent de position sur la liste; celui qui apparaît en tête porte la mention « Le plus calme maintenant ». Les comptages utilisés ont pourtant trente minutes de retard, tandis que les visiteurs peuvent atteindre une place en dix à quinze minutes. Le suivi montre que la plupart choisissent le premier lieu indiqué. Les observateurs y relèvent des arrivées groupées, puis une période plus calme. Plus tard, une autre place prend la tête et reçoit à son tour un afflux. Sur la journée, les trois lieux ont été recommandés et leur fréquentation totale reste raisonnable, mais certains créneaux deviennent difficiles pour les habitants. L'équipe examine donc ce qui, dans le fonctionnement de la recommandation, concentre les choix malgré la variété des lieux.","question":"Quel mécanisme rend compte des attroupements observés malgré la variété des suggestions ?","options":["Les itinéraires vers les différents lieux traversent un même point, qui reçoit ainsi les flux de plusieurs parcours pourtant présentés séparément.","Le premier lieu indiqué attire des choix convergents avant que les nouvelles arrivées soient prises en compte dans le classement proposé.","Les activités recommandées commencent aux mêmes heures, ce qui regroupe les arrivées sur des créneaux communs malgré la diversité des lieux.","Les conditions d'accès écartent une partie des suggestions, ce qui reporte les visiteurs vers le lieu compatible avec leurs contraintes de visite."],"correct":"B","explanation":"B. La plupart suivent la même première suggestion et arrivent avant que les données retardées soient actualisées: les lieux varient au fil de la journée, mais les choix convergent par vagues. A suppose un passage commun que les itinéraires n'ont pas. C suppose des activités à heures fixes, absentes pendant l'essai. D suppose des conditions d'accès différentes, alors que les trois lieux sont gratuits et ouverts aux mêmes heures."}]}$paper$::jsonb),
('tcf-reading-05','tcf-reading-2026-11-close-reading-v6',$paper${"id":"tcf-reading-05","version":"tcf-reading-2026-11-close-reading-v6","title":"TCF Reading · Test 05","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"Déposez les piles usagées dans la boîte de l'accueil. Les ampoules doivent être apportées au magasin de bricolage voisin.\n\nUn agent peut expliquer les autres points de collecte. Merci de ne rien laisser à côté de la boîte.","question":"Où déposer les piles ?","options":["Dans le magasin prévu pour les ampoules","À côté de la boîte de collecte","Dans le bac des déchets en papier","Dans la boîte située à l'accueil"],"correct":"D","explanation":"Le passage indique : « Déposez les piles usagées dans la boîte de l'accueil. Les ampoules doivent être apportées au magasin de bricolage voisin. » Cela justifie la réponse : À l'accueil."},{"number":2,"points":3,"passage":"La collecte des feuilles aura lieu jeudi. Les sacs en plastique ne seront pas acceptés ; utilisez les sacs en papier distribués en mairie.\n\nLes distributions de sacs se font aux horaires habituels.","question":"Quel contenant faut-il utiliser ?","options":["Les sacs en papier remis par la mairie","Les sacs compostables du commerce","Les sacs plastiques de collecte","Les grands sacs de déchets ménagers"],"correct":"A","explanation":"Le passage indique : « La collecte des feuilles aura lieu jeudi. Les sacs en plastique ne seront pas acceptés ; utilisez les sacs en papier distribués en mairie. » Cela justifie la réponse : Un sac en papier."},{"number":3,"points":3,"passage":"En période de sécheresse, l'arrosage des pelouses est suspendu. Les jeunes arbres peuvent recevoir de l'eau avant huit heures.\n\nDes contrôles auront lieu pendant toute la période annoncée par la commune.","question":"Quel arrosage reste permis ?","options":["Arroser les jeunes arbres avant huit heures","Arroser les jeunes arbres en journée","Arroser les pelouses tôt le matin","Arroser les pelouses après le coucher du soleil"],"correct":"A","explanation":"Le passage indique : « En période de sécheresse, l'arrosage des pelouses est suspendu. Les jeunes arbres peuvent recevoir de l'eau avant huit heures. » Cela justifie la réponse : Celui des jeunes arbres tôt le matin."},{"number":4,"points":3,"passage":"Le café accepte vos tasses réutilisables propres. Les couvercles jetables ne sont plus fournis automatiquement ; demandez-en un si nécessaire.\n\nL'équipe souhaite réduire les petits déchets emportés après chaque vente. Cette organisation sera évaluée avec les clients au cours du mois prochain.","question":"Quelle nouvelle habitude est proposée ?","options":["Utiliser des tasses fournies par le café","Rapporter les couvercles après usage","Apporter une tasse à faire laver sur place","Apporter sa tasse réutilisable propre"],"correct":"D","explanation":"Le passage indique : « Le café accepte vos tasses réutilisables propres. Les couvercles jetables ne sont plus fournis automatiquement ; demandez-en un si nécessaire. » Cela justifie la réponse : Utiliser sa propre tasse propre."},{"number":5,"points":9,"passage":"Demain, apportons chacun une boîte pour le pique-nique. Je préparerai les boissons dans une grande gourde ; inutile d'acheter des bouteilles individuelles.\n\nNous pourrons tout rapporter après le repas au lieu de remplir les poubelles du parc. J'ai aussi prévu des couverts que nous laverons chez moi.","question":"Que cherche à limiter ce message ?","options":["Réduire les portions servies au pique-nique","Éviter de transporter des boissons chaudes","Réduire le nombre de plats préparés","Limiter les contenants à usage unique"],"correct":"D","explanation":"Le passage indique : « Demain, apportons chacun une boîte pour le pique-nique. Je préparerai les boissons dans une grande gourde ; inutile d'acheter des bouteilles individuelles. » Cela justifie la réponse : Les contenants jetables."},{"number":6,"points":9,"passage":"L'atelier réparation accepte les grille-pain et les lampes. Les appareils à gaz sont exclus, car les bénévoles n'ont pas la qualification nécessaire.\n\nUn bénévole examinera d'abord l'objet pour vérifier si l'intervention est possible. Les réparations complexes seront orientées vers un professionnel du secteur.","question":"Pourquoi certains appareils sont-ils refusés ?","options":["Les bénévoles ne sont pas habilités à intervenir sur le gaz","Les réparations de ces appareils demandent plus de temps","La collecte des pièces de rechange est trop coûteuse","L'atelier réserve leur réparation aux séances du soir"],"correct":"A","explanation":"Le passage indique : « L'atelier réparation accepte les grille-pain et les lampes. Les appareils à gaz sont exclus, car les bénévoles n'ont pas la qualification nécessaire. » Cela justifie la réponse : Pour respecter les compétences disponibles."},{"number":7,"points":9,"passage":"Je laisse une partie du jardin sans tonte cette année. Je garderai seulement un passage court pour accéder au cabanon.\n\nCe sera intéressant de voir quelles plantes apparaissent et si les insectes reviennent. Je prendrai quelques photographies pour comparer les changements au fil de la saison.","question":"Comment le jardin sera-t-il entretenu ?","options":["Le passage vers le cabanon restera non tondu","La tonte aura lieu uniquement en fin de saison","Une partie du jardin restera sans tonte","Les plantes spontanées seront retirées avant l'été"],"correct":"C","explanation":"Le passage indique : « Je laisse une partie du jardin sans tonte cette année. Je garderai seulement un passage court pour accéder au cabanon. » Cela justifie la réponse : Avec des zones volontairement non tondues."},{"number":8,"points":9,"passage":"La visite du centre de tri est gratuite. Les enfants de moins de huit ans ne peuvent pas y participer pour des raisons de sécurité.\n\nLes groupes seront accompagnés dans les zones autorisées.","question":"Quelle condition concerne les enfants ?","options":["Participer uniquement avec un groupe scolaire","Venir accompagné même avant huit ans","Avoir suivi une initiation au tri sélectif","Avoir au moins huit ans pour la visite"],"correct":"D","explanation":"Le passage indique : « La visite du centre de tri est gratuite. Les enfants de moins de huit ans ne peuvent pas y participer pour des raisons de sécurité. » Cela justifie la réponse : Avoir au moins huit ans."},{"number":9,"points":9,"passage":"Chers membres, les gobelets consignés devront être rapportés avant la fermeture du festival pour récupérer la consigne. Ils ne sont pas des cadeaux promotionnels.\n\nLe point de retour se trouve près de la sortie principale.","question":"Que faut-il faire pour récupérer la somme déposée ?","options":["Rapporter le gobelet après la fermeture","Rapporter le gobelet avant la fermeture","Remettre le gobelet à l'entrée du site","Rendre le gobelet lors d'un autre festival"],"correct":"B","explanation":"Le passage indique : « Chers membres, les gobelets consignés devront être rapportés avant la fermeture du festival pour récupérer la consigne. Ils ne sont pas des cadeaux promotionnels. » Cela justifie la réponse : Rapporter le gobelet à temps."},{"number":10,"points":9,"passage":"Le concours de jardins récompense cette année les pratiques économes en eau. La présence de fleurs rares ne rapporte pas de points supplémentaires.\n\nLes participants présenteront leurs choix au jury. Des photographies prises à différentes périodes permettront aussi d'expliquer l'évolution du jardin et les difficultés rencontrées.","question":"Quel critère est privilégié ?","options":["La variété des végétaux présentés","Une utilisation économe de l'eau","Le caractère rare des fleurs","La qualité des photographies du jardin"],"correct":"B","explanation":"Le passage indique : « Le concours de jardins récompense cette année les pratiques économes en eau. La présence de fleurs rares ne rapporte pas de points supplémentaires. » Cela justifie la réponse : La gestion de l'eau."},{"number":11,"points":15,"passage":"Une épicerie propose des produits en vrac. Les clients peuvent apporter leurs contenants, qui sont pesés vides avant d'être remplis.\n\nLe personnel retire ensuite ce poids du montant utilisé pour calculer le prix. Une démonstration est proposée aux nouveaux clients, car plusieurs personnes hésitent à se servir seules lors de leur première visite. Le magasin accepte des boîtes de tailles différentes, à condition qu'elles soient propres et adaptées au produit choisi. Il souhaite rendre cette formule simple sans promettre que tous les aliments pourront être transportés dans n'importe quel récipient. Les tarifs restent affichés au même endroit.","question":"Pourquoi pèse-t-on le contenant vide ?","options":["Pour fixer le prix de chaque bocal","Pour vérifier la capacité du récipient","Pour déduire le poids du récipient du prix","Pour contrôler la quantité de produit admise"],"correct":"C","explanation":"Le passage indique : « Une épicerie propose des produits en vrac. Les clients peuvent apporter leurs contenants, qui sont pesés vides avant d'être remplis. » Cela justifie la réponse : Pour ne facturer que le produit."},{"number":12,"points":15,"passage":"Des élèves recensent les oiseaux près de leur école chaque vendredi. Ils observent au même endroit et à la même heure pour rendre les relevés comparables.\n\nLes élèves notent la météo et le nombre de personnes présentes, afin de conserver une trace des circonstances. Une association vérifie les espèces difficiles à identifier sur les photographies. L'école veut surtout apprendre à observer avec régularité, plutôt qu'annoncer un résultat spectaculaire après une seule séance.","question":"Pourquoi répéter les mêmes conditions ?","options":["Pour observer un plus grand nombre d'espèces","Pour éviter de consigner les conditions météo","Pour répartir les élèves dans différents lieux","Pour rendre les résultats comparables"],"correct":"D","explanation":"Le passage indique : « Des élèves recensent les oiseaux près de leur école chaque vendredi. Ils observent au même endroit et à la même heure pour rendre les relevés comparables. » Cela justifie la réponse : Faciliter la comparaison des observations."},{"number":13,"points":15,"passage":"Un composteur collectif ferme temporairement après des dépôts inadaptés. Les habitants recevront une démonstration avant sa réouverture.\n\nLes erreurs concernaient notamment les emballages et les restes trop volumineux. L'association installera des indications illustrées à proximité du bac et désignera des personnes de contact dans plusieurs immeubles. Les usagers pourront leur poser une question avant de déposer un produit inhabituel. Le comité souhaite que cette interruption serve à améliorer le fonctionnement, sans faire croire qu'un composteur se gère tout seul. Un premier contrôle sera organisé quelques semaines après la reprise.","question":"Quel problème la démonstration doit-elle résoudre ?","options":["Le choix du lieu d'installation du composteur","La récupération des emballages en bon état","Les dépôts de matières inadaptées au compostage","Le transport des déchets vers la déchèterie"],"correct":"C","explanation":"Le passage indique : « Un composteur collectif ferme temporairement après des dépôts inadaptés. Les habitants recevront une démonstration avant sa réouverture. » Cela justifie la réponse : Les erreurs de dépôt."},{"number":14,"points":15,"passage":"La commune remplace ses haies taillées par des espèces locales variées. Elle souhaite offrir des abris à différentes espèces plutôt qu'un décor identique toute l'année.\n\nLes plantations ont été choisies avec une pépinière et une association naturaliste. Certaines fleurissent au printemps, d'autres portent des fruits plus tard. Le calendrier d'entretien tiendra compte des périodes où les animaux utilisent les branches pour se reproduire. Les agents expliquent aux riverains que la haie pourra paraître moins uniforme sans être abandonnée. Une petite visite permettra de découvrir les espèces installées et de comprendre les fonctions recherchées, au-delà de leur seul aspect décoratif.","question":"Quel objectif guide ce remplacement ?","options":["Offrir des habitats à davantage d'espèces","Rendre toutes les haies identiques toute l'année","Réduire le nombre de plantes locales utilisées","Faciliter une taille uniforme à chaque saison"],"correct":"A","explanation":"Le passage indique : « La commune remplace ses haies taillées par des espèces locales variées. Elle souhaite offrir des abris à différentes espèces plutôt qu'un décor identique toute l'année. » Cela justifie la réponse : Favoriser la diversité du vivant."},{"number":15,"points":15,"passage":"Un magasin reprend les vêtements abîmés, mais demande de séparer les articles encore utilisables. Ceux-ci pourront être réemployés plutôt que transformés en fibres.\n\nDes bénévoles vérifient l'état des vêtements avant de les orienter vers les associations partenaires. Une petite couture ou un bouton remplacé permet parfois de remettre rapidement un article en circulation. Les tissus vraiment usés seront regroupés pour un autre traitement. Le magasin souhaite éviter que l'ensemble des dons soit considéré comme une matière indistincte. Il indiquera les résultats de la collecte pour expliquer les volumes réutilisés et ceux qui nécessitent une transformation plus importante.","question":"Pourquoi distinguer les deux catégories ?","options":["Envoyer les tissus encore utilisables au recyclage","Répartir les articles selon le prix d'origine","Conserver la possibilité de réemployer certains vêtements","Écarter les vêtements qui demandent une petite couture"],"correct":"C","explanation":"Le passage indique : « Un magasin reprend les vêtements abîmés, mais demande de séparer les articles encore utilisables. Ceux-ci pourront être réemployés plutôt que transformés en fibres. » Cela justifie la réponse : Préserver la possibilité de réutilisation."},{"number":16,"points":15,"passage":"Une association nettoie les berges sans entrer dans les roselières. Ces zones servent de refuge ; retirer les déchets ne doit pas déranger les oiseaux nicheurs.\n\nLes organisateurs ont préparé un parcours et expliqué les zones à éviter avant le départ. Les sacs seront transportés par les passages déjà fréquentés. Si un déchet se trouve dans un endroit sensible, un responsable décidera comment intervenir plus tard. Les bénévoles comprennent ainsi qu'une action de nettoyage ne se juge pas seulement au nombre de sacs remplis.","question":"Quelle précaution est prise ?","options":["Nettoyer uniquement les berges déjà dégradées","Éviter de perturber les refuges des oiseaux nicheurs","Retirer les plantes aquatiques avant les déchets","Déplacer les nids avant d'accéder aux roselières"],"correct":"B","explanation":"Le passage indique : « Une association nettoie les berges sans entrer dans les roselières. Ces zones servent de refuge ; retirer les déchets ne doit pas déranger les oiseaux nicheurs. » Cela justifie la réponse : Éviter certains habitats pendant le nettoyage."},{"number":17,"points":15,"passage":"Des habitants comparent leurs consommations d'eau après l'installation de mousseurs. Ils relèvent aussi le nombre de personnes présentes pour ne pas attribuer toute variation au matériel.\n\nLes familles comparent des périodes de durée semblable et indiquent les changements de leurs habitudes. Un week-end avec des invités ou une longue absence peut peser sur le résultat. L'association les aide à lire les relevés sans transformer l'expérience en compétition. Elle veut savoir si l'équipement contribue à réduire la consommation dans des conditions ordinaires. Les participants discuteront ensuite des solutions les plus simples à conserver au quotidien, avec ou sans nouvelle installation.","question":"Que veulent-ils éviter ?","options":["Une erreur dans le prix des équipements installés","Attribuer trop vite les variations aux mousseurs","La comparaison de périodes de durée semblable","Le relevé du nombre de personnes dans le foyer"],"correct":"B","explanation":"Le passage indique : « Des habitants comparent leurs consommations d'eau après l'installation de mousseurs. Ils relèvent aussi le nombre de personnes présentes pour ne pas attribuer toute variation au matériel. » Cela justifie la réponse : Une interprétation trop rapide des chiffres."},{"number":18,"points":15,"passage":"Une entreprise propose le prêt de vaisselle pour les fêtes. Les clients la rapportent sale ; le lavage collectif est organisé avec une machine adaptée.\n\nLes lots sont comptés avant chaque retour afin de repérer rapidement une pièce manquante. L'entreprise vérifie aussi que le nettoyage correspond au type de vaisselle proposé. Une fiche explique les horaires et les modalités de transport. Le responsable suivra les quantités réellement réutilisées au cours de la saison, ainsi que les déplacements nécessaires pour assurer les prêts, avant de dresser un bilan plus large.","question":"Quel service est inclus ?","options":["Le nettoyage des pièces après leur retour","La préparation des repas avant la réception","Le dressage des tables pour les invités","La livraison des boissons avec la vaisselle"],"correct":"A","explanation":"Le passage indique : « Une entreprise propose le prêt de vaisselle pour les fêtes. Les clients la rapportent sale ; le lavage collectif est organisé avec une machine adaptée. » Cela justifie la réponse : Le nettoyage après retour."},{"number":19,"points":15,"passage":"Le ramassage des déchets sur une plage se déroule après la marée haute. Les organisateurs vérifient les horaires pour ne pas exposer les participants à la montée des eaux.\n\nUn guide rappelle les limites du parcours et les points de rendez-vous en cas de séparation du groupe. Les zones difficiles d'accès resteront exclues, même si des déchets y sont visibles. Les participants sont invités à porter des chaussures fermées et à ne pas ramasser les objets dangereux à mains nues.","question":"Pourquoi choisir ce moment ?","options":["Pour profiter d'une plage plus accessible au public","Pour limiter le risque lié à la montée des eaux","Pour observer davantage de déchets dans l'eau","Pour prolonger la collecte jusqu'à la marée suivante"],"correct":"B","explanation":"Le passage indique : « Le ramassage des déchets sur une plage se déroule après la marée haute. Les organisateurs vérifient les horaires pour ne pas exposer les participants à la montée des eaux. » Cela justifie la réponse : Réduire un risque pour les participants."},{"number":20,"points":21,"passage":"Un supermarché baisse le prix de produits proches de leur date limite. L'association partenaire rappelle que ces promotions ne doivent pas inciter à acheter plus que ce que l'on consommera réellement. Les clients recevront des indications de conservation et pourront acheter une petite quantité seulement. Le magasin souhaite écouler les produits encore utilisables, pas transformer l'urgence de la vente en prétexte à remplir inutilement les paniers. L'association propose de comparer les achats avec les besoins prévus pour les repas. Une réduction importante ne constitue une économie que si les aliments sont consommés dans les conditions nécessaires.","question":"Quelle limite accompagne la promotion ?","options":["Réserver les réductions aux achats en grande quantité","Promouvoir les produits dont la date est éloignée","Éviter que le gaspillage se déplace chez les acheteurs","Limiter l'achat aux seuls produits non périssables"],"correct":"C","explanation":"Le passage indique : « Un supermarché baisse le prix de produits proches de leur date limite. L'association partenaire rappelle que ces promotions ne doivent pas inciter à acheter plus que ce que l'on consommera réellement. » Cela justifie la réponse : Éviter de déplacer le gaspillage vers les foyers."},{"number":21,"points":21,"passage":"Une forêt accueille des promeneurs sur des chemins stabilisés. Les gestionnaires ferment certains sentiers après de fortes pluies : le sol humide s'abîme davantage sous les passages répétés. Les gardes ont observé des traces profondes dans certains passages très fréquentés. Ils préfèrent fermer quelques secteurs pendant une courte période plutôt que réparer plus tard un sentier fortement dégradé. Les promeneurs sont invités à suivre ces indications même lorsque la pluie a cessé et que la surface commence à sembler sèche.","question":"Quel motif explique les fermetures ?","options":["Protéger les sols affaiblis par les pluies récentes","Faciliter le passage des véhicules d'entretien","Éviter les rencontres entre groupes de promeneurs","Préparer la réfection de tous les chemins stabilisés"],"correct":"A","explanation":"Le passage indique : « Une forêt accueille des promeneurs sur des chemins stabilisés. Les gestionnaires ferment certains sentiers après de fortes pluies : le sol humide s'abîme davantage sous les passages répétés. » Cela justifie la réponse : La fragilité temporaire du sol."},{"number":22,"points":21,"passage":"Une ville plante des arbres sur une place très minérale. Les habitants demandent aussi des points d'eau et des bancs. L'ombre sera utile, mais prendra plusieurs années à se développer. Les associations du quartier proposent des points de repos temporaires et une information sur les lieux frais déjà accessibles. Le service des espaces verts a présenté le rythme probable de croissance des plantations. La mairie souhaite éviter une promesse de confort immédiat que les arbres ne peuvent pas tenir.","question":"Pourquoi ajouter d'autres équipements ?","options":["Protéger les plantations pendant les premiers travaux","Limiter l'accès à la place avant la fin du chantier","Répondre aux besoins de fraîcheur avant que les arbres grandissent","Conserver la place libre pour de futures plantations"],"correct":"C","explanation":"Le passage indique : « Une ville plante des arbres sur une place très minérale. Les habitants demandent aussi des points d'eau et des bancs. L'ombre sera utile, mais prendra plusieurs années à se développer. » Cela justifie la réponse : Répondre aux besoins avant la croissance des arbres."},{"number":23,"points":21,"passage":"Une cantine réduit les portions servies d'avance et autorise les élèves à se resservir. Les déchets alimentaires diminuent sans limiter la quantité disponible pour ceux qui ont faim. Le personnel observe les retours de plateaux et demande aux enfants ce qui leur permet de se servir plus justement. Certains avaient l'habitude de prendre une grosse portion par crainte de manquer ensuite. Les équipes expliquent donc clairement que le complément reste possible.","question":"Quelle organisation est adoptée ?","options":["Distribuer une grande portion identique à chaque élève","Retirer le droit de se resservir pendant le repas","Servir moins d'abord, tout en permettant un complément","Réserver les portions supplémentaires au personnel"],"correct":"C","explanation":"Le passage indique : « Une cantine réduit les portions servies d'avance et autorise les élèves à se resservir. Les déchets alimentaires diminuent sans limiter la quantité disponible pour ceux qui ont faim. » Cela justifie la réponse : Adapter le premier service avec possibilité de complément."},{"number":24,"points":21,"passage":"Des pêcheurs participent à un suivi des poissons de rivière. Ils notent également les journées sans capture, car une absence d'observation apporte elle aussi une information utile. Les fiches précisent le lieu, la durée et les conditions de chaque sortie. Une journée sans poisson peut s'expliquer de plusieurs façons, qui seront discutées avec les spécialistes. Le groupe souhaite construire une série cohérente plutôt qu'une collection de belles photographies de captures.","question":"Pourquoi noter les sorties sans prise ?","options":["Pour calculer les prises seulement les jours fructueux","Pour comparer les durées de sortie de chaque bénévole","Pour inclure aussi les sorties sans résultat positif","Pour éviter de préciser les conditions de pêche"],"correct":"C","explanation":"Le passage indique : « Des pêcheurs participent à un suivi des poissons de rivière. Ils notent également les journées sans capture, car une absence d'observation apporte elle aussi une information utile. » Cela justifie la réponse : Pour éviter un relevé limité aux résultats positifs."},{"number":25,"points":21,"passage":"Pour comparer deux emplacements d’une zone commerciale, une enquête suit les déplacements que feraient les futurs clients. Léa visiterait le site Est le vendredi, en quittant le travail. Son parcours habituel passe près de l’entrée ; elle quitterait cette route pour atteindre le parking, puis reviendrait au même carrefour avant de poursuivre vers son domicile. Sans ouverture du site, elle rentrerait directement. Marc visiterait le site Gare le dimanche. Ce jour-là, il reste habituellement chez lui et reçoit ses courses par livraison. Avec le nouveau magasin, il partirait de son domicile pour acheter sur place, puis rentrerait chez lui. Le dossier indique pour chacun la distance entre son domicile et le site. Les bâtiments projetés seraient économes, mais l’urbaniste veut compléter leur bilan par la circulation automobile ajoutée par les clients ; les tournées des fournisseurs feront l’objet d’un volet distinct.","question":"Quel déplacement automobile s’ajoute, pour chacun, au scénario sans ouverture ?","options":["Pour Léa, un aller-retour depuis le domicile ; pour Marc, un aller-retour depuis le domicile.","Pour Léa, un détour sur un trajet déjà prévu ; pour Marc, un aller-retour depuis le domicile.","Pour Léa, un aller-retour depuis le domicile ; pour Marc, un détour sur un trajet déjà prévu.","Pour Léa, un détour sur un trajet déjà prévu ; pour Marc, un détour sur un trajet déjà prévu."],"correct":"B","explanation":"B. Léa passe déjà par le carrefour pour rentrer du travail : le parcours ajouté quitte puis rejoint son trajet habituel. Marc resterait chez lui sans le projet : sa sortie domicile–magasin–domicile est donc entièrement ajoutée. A attribue à Léa une sortie supplémentaire depuis son domicile, C inverse les deux situations et D suppose chez Marc un trajet déjà prévu dans lequel les courses s’inséreraient. Le détour de Léa peut lui-même comporter un aller et un retour jusqu’au carrefour ; il ne constitue pas pour autant un aller-retour supplémentaire depuis son domicile."},{"number":26,"points":21,"passage":"Un agriculteur consacre une bande de sa parcelle aux fleurs. Son voisin conserve la même surface entièrement cultivée. Tous deux utilisent un traitement lorsque les ravageurs atteignent le seuil fixé par leur conseiller. Au printemps, ce seuil est atteint chez le voisin, qui traite ; dans la parcelle bordée de fleurs, des insectes prédateurs sont observés et le relevé reste sous le seuil. Un second épisode conduit ensuite chacun à intervenir. À la récolte, les quantités obtenues par mètre carré cultivé sont proches. Le total vendu par l’agriculteur reste inférieur, puisqu’une partie de son terrain porte des fleurs. Le conseiller demande de poursuivre l’essai, notamment lors d’une saison plus sèche. Pour l’instant, le carnet des interventions et le relevé des surfaces n’ont pas été réunis dans le bilan économique.","question":"Quelle lecture croisée du carnet des interventions et du relevé des surfaces est fondée ?","options":["Les traitements ont été moins nombreux, mais le total vendu n’a pas rejoint celui du témoin.","Les traitements ont été aussi nombreux, et le total vendu a rejoint celui du témoin.","Les traitements ont été moins nombreux, et le total vendu a rejoint celui du témoin.","Les traitements ont été aussi nombreux, mais le total vendu n’a pas rejoint celui du témoin."],"correct":"A","explanation":"A. Le voisin intervient au printemps puis lors du second épisode ; l’agriculteur intervient seulement au second. L’égalité approximative des récoltes par mètre carré cultivé ne compense pas la moindre surface productive, puisque le total vendu reste inférieur. B inverse les deux constats. C conserve l’économie d’intervention mais confond rendement cultivé et total vendu. D conserve le résultat de vente mais ne compte que l’épisode final commun."},{"number":27,"points":21,"passage":"La bibliothèque d’objets hésite entre remplacer une perceuse très demandée et entretenir un taille-haie moins emprunté. Sur trente emprunteurs de perceuse interrogés, quatre auraient acheté un appareil ; les autres auraient loué ou demandé celui d’un proche. Sur douze emprunteurs du taille-haie, dix envisageaient un achat. Le modèle de perceuse s’use rapidement : son remplacement a déjà nécessité un appareil neuf. Le taille-haie fonctionne depuis cinq ans et une petite pièce permettrait de le maintenir en service. L’association conserve les deux services, mais révise son bilan environnemental. Jusqu’ici, elle comptait un achat évité par prêt et présentait la perceuse comme sa principale économie de matériel. Les nouveaux relevés portent sur les pratiques remplacées et sur les pièces utilisées pour l’entretien.","question":"Quelle comparaison des deux modèles est justifiée lorsque les deux indicateurs sont examinés ensemble ?","options":["La perceuse évite davantage d’achats ; le taille-haie conserve une durée de service plus longue.","Le taille-haie évite davantage d’achats ; la perceuse conserve une durée de service plus longue.","La perceuse évite davantage d’achats et conserve une durée de service plus longue.","Le taille-haie évite davantage d’achats et conserve une durée de service plus longue."],"correct":"D","explanation":"D. Les réponses font apparaître dix achats envisagés pour le taille-haie contre quatre pour la perceuse ; le taille-haie reste réparable après cinq ans, alors que la perceuse a déjà nécessité un remplacement. A inverse le résultat sur les achats. B inverse le résultat sur la durée. C inverse les deux."},{"number":28,"points":21,"passage":"Le jardin partagé possède une réserve suffisante pour deux arrosages complets. Le remplissage suivant dépend d’une pluie annoncée, encore incertaine. Le collectif compare deux rangées de jeunes plants : celle du Mur vient d’être repiquée dans une terre déjà sèche en profondeur ; celle du Saule conserve de l’humidité sous la surface, malgré une croûte sèche. Les feuilles du Mur commencent à s’affaisser. Les jardiniers ont observé qu’un arrosage complet atteint les racines, tandis que les petites distributions quotidiennes mouillent surtout cette croûte. Les plants du Saule pourront utiliser la réserve du sol pendant deux jours ; le contrôle suivant est prévu au terme de ce délai. Un ancien règlement aurait accordé dès aujourd’hui la même quantité à chaque rangée. Les jardiniers doivent choisir comment engager le premier arrosage, sachant qu’ils ne pourront pas compléter le réservoir entre-temps.","question":"Quelle décision prendre aujourd’hui en gardant le contrôle prévu comme prochaine étape ?","options":["Arroser complètement le Saule aujourd’hui, puis décider de l’emploi de la réserve restante au contrôle prévu.","Arroser complètement le Mur aujourd’hui, puis décider de l’emploi de la réserve restante au contrôle prévu.","Partager un apport entre le Mur et le Saule aujourd’hui, puis décider de l’emploi de la réserve restante au contrôle prévu.","Reporter l’arrosage des deux rangées aujourd’hui, puis décider de l’emploi de la réserve conservée au contrôle prévu."],"correct":"B","explanation":"B. Le Mur est sec en profondeur et ses feuilles commencent à s’affaisser ; il lui faut un apport atteignant les racines. Le Saule conserve de l’eau dans le sol jusqu’au contrôle. Les quatre plans laissent la suite ouverte à ce contrôle : la différence porte sur l’action présente. A inverse les besoins, C répartit l’eau en petites quantités qui atteignent mal les racines, et D laisse sans apport la rangée déjà en difficulté."},{"number":29,"points":21,"passage":"Une association revoit sa promenade nocturne après avoir observé que les groupes attendant devant un refuge retardent la sortie des chauves-souris. Réduire le groupe facilite les déplacements, mais les essais montrent que l’attente éclairée au même endroit perturbe encore les animaux. Un photographe propose une lumière moins forte ; l’équipe ne dispose pas d’observations permettant d’en évaluer l’effet. Le guide choisit plutôt une halte éloignée, sur un trajet de chasse, avec un détecteur qui rend certains cris audibles. Les visiteurs verront moins bien les détails des animaux, mais pourront comparer leurs activités. Les questions seront regroupées après chaque écoute. L’association conserve ainsi la sortie nocturne, tout en modifiant ce qu’elle promet d’apprendre à observer.","question":"Quel compromis est effectivement retenu dans la nouvelle promenade ?","options":["Maintenir l’observation du refuge en compensant sa proximité par un groupe plus restreint.","Maintenir une vision détaillée des animaux en diminuant l’intensité de l’éclairage utilisé.","Déplacer l’observation vers l’écoute des activités en renonçant à la proximité du refuge.","Réduire les interventions du guide pour prolonger l’observation silencieuse devant le refuge."],"correct":"C","explanation":"C. La halte est déplacée et le détecteur permet d’étudier l’activité sans rechercher la même vision rapprochée. A reprend un essai qui n’a pas éliminé le dérangement. B présente comme retenue une proposition non évaluée. D conserve un emplacement abandonné en lui associant la règle réelle sur les questions."},{"number":30,"points":26,"passage":"Un fabricant choisissait les matériaux de ses appareils en additionnant la part de chacun déclarée recyclable. Son premier prototype obtenait ainsi un très bon résultat sur le papier. Au centre de traitement, pourtant, la coque et les éléments internes restaient collés ; leur séparation aurait demandé trop de temps pour la filière disponible. Un second prototype emploie une petite pièce de fixation non recyclable, mais ses vis accessibles permettent de séparer rapidement les principaux matériaux. La part déclarée recyclable est donc légèrement plus faible dans le second modèle. Les deux prototypes sont essayés sur la même ligne du centre ; davantage de matière est finalement récupérée avec le second. Le fabricant avait aussi envisagé une notice demandant aux clients de démonter l’appareil chez eux. Les techniciens expliquent que la filière peut effectuer cette opération si l’assemblage le permet ; elle n’exige pas que les particuliers la réalisent. Le designer propose donc de remplacer l’indicateur initial par un essai du produit assemblé dans les conditions du centre partenaire.","question":"Quel mécanisme explique l’écart de récupération entre les deux prototypes ?","options":["Le second arrive démonté par les particuliers, ce qui réduit les opérations nécessaires au centre.","Le second contient une proportion plus forte de matières recyclables, ce qui augmente la fraction récupérable.","Le second bénéficie d’une ligne de traitement plus équipée, ce qui permet de séparer les assemblages collés.","Le second permet de séparer plus rapidement les matières, ce qui augmente la quantité effectivement récupérée."],"correct":"D","explanation":"D. Les vis accessibles rendent les matériaux séparables sur la ligne existante. A transforme une notice envisagée en démontage effectivement réalisé par les particuliers. B inverse la proportion nominalement recyclable, légèrement plus faible dans le second modèle. C attribue le résultat à une ligne différente, alors que la comparaison utilise la même."},{"number":31,"points":26,"passage":"Une entreprise teste un emballage plus léger sur deux séries de produits, P et R, expédiées dans les mêmes conditions. Pour un lot de P, le nouvel emballage économise quatre kilos de matière ; les dégâts et les pièces nécessaires à leur réparation restent identiques au lot témoin. Pour un lot de R, il économise trois kilos. Le nombre d’incidents de R passe de trois à un pour cent, mais leur nature change : les anciennes casses demandaient de petites pièces, les nouvelles imposent un produit complet. Le matériel supplémentaire mobilisé par ces remplacements représente cinq kilos par lot de R. Le service commercial souhaite généraliser le dispositif en citant la baisse globale des incidents. L’ingénieure examine séparément les deux séries, en gardant le même périmètre : emballages, produits et pièces de remplacement. Les frais des essais sont suivis dans un budget distinct et ne sont pas convertis en poids de matière.","question":"Quelle comparaison des bilans matériels par série correspond aux résultats de l’essai ?","options":["Pour P, l’économie d’emballage est conservée ; pour R, elle est dépassée par les remplacements supplémentaires.","Pour P, l’économie d’emballage est dépassée par les remplacements supplémentaires ; pour R, elle est conservée.","Pour P, l’économie d’emballage est conservée ; pour R, elle reste supérieure aux remplacements supplémentaires.","Pour P, les remplacements supplémentaires dépassent l’économie d’emballage ; pour R, ils la dépassent également."],"correct":"A","explanation":"A. P économise quatre kilos sans changement de matériel de réparation : ce gain demeure. R économise trois kilos d’emballage mais mobilise cinq kilos supplémentaires en remplacements : le gain est dépassé. B inverse les séries. C privilégie implicitement la baisse du nombre d’incidents de R sans prendre en compte leur gravité matérielle. D attribue à P des remplacements supplémentaires qui n’existent pas."},{"number":32,"points":26,"passage":"Pour une avenue exposée à la chaleur, la pépinière propose Aurore et Cuivre, deux formes d’une même espèce sélectionnées pour leurs feuillages. Les deux formes sont déjà cultivées dans les fosses de l’avenue. Une note sanitaire décrit le dernier épisode de maladie : lorsque le parasite s’est installé, les arbres de cette espèce ont été touchés dans plusieurs rues, quelle que soit leur forme. Le catalogue propose aussi Plume et Écorce, appartenant à deux autres espèces. Les essais de chaleur sont satisfaisants pour les quatre références. Plume a développé ses racines dans les fosses profondes du terrain d’essai ; sa fiche recommande de conserver cette profondeur. Écorce provient de plantations réalisées dans des fosses peu profondes, comme celles de l’avenue. Les conduites sous la chaussée doivent rester en place. L’équipe d’entretien peut organiser deux périodes de taille si nécessaire. Le marché peut être réparti entre plusieurs pépinières. Le paysagiste souhaite choisir deux références plutôt que renouveler toute l’avenue avec une seule.","question":"Quel mélange répondrait à la préoccupation sanitaire sans imposer de nouveaux travaux de sous-sol ?","options":["Aurore et Cuivre, commandés à deux pépinières différentes.","Cuivre et Écorce, avec des périodes de taille adaptées.","Aurore et Plume, avec une surveillance des nouvelles racines.","Plume et Écorce, répartis alternativement dans l’avenue."],"correct":"B","explanation":"B. Cuivre et Écorce appartiennent à deux espèces ; Écorce a été éprouvée dans des fosses comparables à celles de l’avenue. A change de fournisseur mais conserve l’espèce touchée quelle que soit sa forme. C et D introduisent Plume, dont la fiche demande la profondeur du terrain d’essai : une surveillance ou une alternance ne fournit pas cette profondeur. Le choix doit donc croiser la note sanitaire et les conditions racinaires."},{"number":33,"points":26,"passage":"Une campagne municipale présente le prêt d’outils, la réparation et l’usage de contenants personnels. Le dépliant indique les tarifs réduits et les lieux de démonstration. Après une séance, les participants savent expliquer les gestes ; plusieurs disent vouloir les adopter. Trois mois plus tard, les carnets de pratique présentent un contraste. Les retraités qui passent devant les commerces à midi reviennent avec leurs contenants et utilisent l’atelier voisin. Les salariés quittant le quartier tôt le matin continuent surtout leurs anciennes habitudes. Pourtant, pendant les entretiens, ils décrivent précisément la séance et les pratiques proposées. Une employée raconte avoir porté un appareil à réparer pendant plusieurs jours, puis l’avoir remis chez elle : l’atelier fermait avant son retour. Un retraité avait déposé un objet le jour même de la démonstration. L’équipe hésite sur l’usage du prochain budget : produire de nouveaux supports ou travailler avec les commerces sur leurs conditions d’accueil.","question":"Quel résultat supplémentaire renforcerait le mieux l’explication suggérée par le contraste entre les groupes ?","options":["Les salariés changent leurs pratiques après une reformulation des consignes, sans modification des services proposés.","Les salariés changent leurs pratiques après une nouvelle réduction des tarifs, sans modification des horaires proposés.","Les salariés changent leurs pratiques après davantage de démonstrations, sans modification des conditions d’accueil.","Les salariés changent leurs pratiques après une extension des heures d’accueil, sans nouvelle séance d’information."],"correct":"D","explanation":"D. Les salariés connaissent les pratiques et souhaitent les adopter, mais l’exemple de l’objet transporté puis rapporté chez soi révèle un obstacle entre connaissance et usage. Les retraités peuvent utiliser les services pendant leurs déplacements ordinaires. Une modification des heures permettant aux salariés d’agir, sans nouvelle séance, renforcerait cette lecture. A, B et C testeraient respectivement la compréhension des consignes, le coût et la fréquence des démonstrations, tous présents dans la campagne mais moins directement reliés au contraste observé."},{"number":34,"points":26,"passage":"Un chantier récupère vingt portes. Quatorze sont posées, quatre restent dans le dépôt et deux ne satisfont pas aux exigences techniques. Certaines remises en état demandent plus de travail qu’une pose neuve, mais permettent de conserver des éléments solides. Le responsable souhaite suivre à la fois ce travail, les matériaux collectés et les achats de portes neuves effectivement remplacés. Le financeur accepte ces trois rubriques séparées. Pour la troisième, il demande une attribution au chantier dans lequel une porte neuve aurait été utilisée : le lieu de collecte ou de stockage ne détermine pas cette attribution. Les portes sorties du dépôt devront donc être suivies jusqu’à leur pose. Un autre chantier s’intéresse aux quatre portes disponibles ; il pourra en refuser certaines à réception. Le dépôt enregistrera les transferts et les retours, tandis que chaque équipe justifiera les portes installées dans son propre bâtiment. Le nombre total de portes réemployées devra rester vérifiable entre les dossiers.","question":"Si deux portes du dépôt sont finalement posées dans le second chantier, comment appliquer la convention de suivi ?","options":["Attribuer les deux achats remplacés au second chantier et conserver la collecte dans le relevé du premier.","Attribuer les deux achats remplacés au premier chantier et conserver la pose dans le relevé du second.","Attribuer un achat remplacé à chaque chantier et conserver les deux poses dans le relevé du second.","Attribuer les deux achats remplacés au programme commun et conserver collecte et pose dans les relevés des chantiers."],"correct":"A","explanation":"A. L’achat neuf remplacé est attribué au chantier où la porte récupérée est effectivement installée ; le premier conserve la trace de la collecte. B privilégie l’origine du stock. C partage une attribution que la convention rattache à un chantier déterminé. D fournit un total de programme sans l’attribution par chantier demandée. Les quatre méthodes peuvent éviter un double comptage, mais seule A suit la convention exposée."},{"number":35,"points":26,"passage":"Une réserve s'agrandit sur le coteau Nord, refuge automnal d'une population animale. Au printemps, les adultes se dispersent pour se reproduire; le suivi des balises les situe encore au bois des Saules dans les derniers jours de mai. La prairie Haute conserve des plantes nourricières lorsque les autres secteurs se dessèchent. Les relevés montrent que cette ressource devient indispensable dès la première semaine de juin. Une route sépare les trois secteurs. Le passage entre le bois et le coteau utilise une piste agricole, fermée du 1er juin à la fin août pendant les travaux des champs. Deux autres liaisons peuvent recevoir un dispositif temporaire: bois–prairie ou coteau–prairie. Le financement disponible permet d'en ouvrir une seule. Une équipe pourrait l'installer pour le début de juin; une autre propose le même équipement en juillet à moindre coût. Les élus mettent en avant la surface nouvellement protégée sur le coteau. L'écologue demande que le premier investissement soit choisi d'après le déplacement effectivement réalisable au moment où la ressource manque, puis que l'on prépare les trajets d'automne.","question":"Quel aménagement répondrait au besoin prioritaire de la population suivie, compte tenu des liaisons disponibles ?","options":["Ouvrir la liaison coteau–prairie dès le début de juin.","Ouvrir la liaison bois–prairie à partir de juillet.","Ouvrir la liaison bois–prairie dès le début de juin.","Ouvrir la liaison coteau–prairie à partir de juillet."],"correct":"C","explanation":"C. Les balises situent les animaux au bois à la fin de mai, tandis que la prairie fournit la ressource indispensable dès début juin. Passer par le coteau n'est alors pas une solution: la liaison bois–coteau ferme le 1er juin. Il faut donc ouvrir bois–prairie pour le début de juin. A oublie cette coupure du trajet indirect. B retient le bon trajet mais intervient après le début du besoin. D cumule le détour inaccessible et le retard, malgré l'intérêt politique de la surface nouvellement protégée et le coût inférieur en juillet."},{"number":36,"points":33,"passage":"La municipalité compare deux formats d’un même festival, accueillant chacun mille visiteurs. Dans le format R, un sac recyclable est distribué à l’entrée ; des bénévoles expliquent le tri et huit kilos sur les dix kilos distribués rejoignent la filière correcte. Dans le format S, les sacs sont donnés sur demande : beaucoup de visiteurs utilisent leur propre panier. Trois kilos de sacs sont distribués et deux kilos sont correctement récupérés. Les contrôles ne constatent ni achat supplémentaire de sacs ailleurs ni abandon hors du site. Le service de communication classe R en tête, car son taux de récupération est supérieur. L’ingénieure reconnaît la qualité du tri de R, mais rappelle que le mandat initial était de diminuer la matière neuve mobilisée et les déchets restant à traiter. Elle souhaite améliorer aussi la collecte de S. Les organisateurs lui demandent pourquoi elle ne considère pas les taux annoncés comme suffisants pour choisir le prochain format.","question":"Quelle comparaison explique la réserve de l’ingénieure sur le classement annoncé ?","options":["R réduit davantage les résidus, même s’il introduit une masse de sacs plus importante.","S réduit davantage les résidus, même si sa proportion de sacs récupérés reste inférieure.","S améliore davantage le taux de récupération, même si ses résidus demeurent plus importants.","R réduit davantage la matière neuve, même si sa quantité de résidus reste supérieure."],"correct":"B","explanation":"B. R récupère huit des dix kilos distribués et en laisse deux ; S en récupère deux sur trois et en laisse un. S a donc un taux inférieur mais moins de résidus et moins de matière neuve introduite. A attribue à R la réduction supérieure des résidus ; C inverse les taux et les résidus ; D inverse les quantités de matière neuve. Les contrôles excluent un transfert des déchets hors du site."},{"number":37,"points":33,"passage":"Une restauration de rivière doit être suivie pendant trois ans. Avant les travaux, les poissons étaient comptés au crépuscule : les observations préparatoires avaient montré qu’ils quittaient alors leurs abris. Après une crue, les premières séries baissent dans les secteurs amont, aval et témoin. Les images automatiques indiquent ensuite un retour des passages dans le témoin et en aval. En amont, une fiche rapporte encore peu de poissons et conduit un financeur à demander une modification des aménagements. Le compte rendu technique précise ailleurs que la caméra amont, endommagée par la crue, a été remplacée par des visites manuelles. L’agent rejoint ce secteur avant midi, puis part relever les niveaux d’eau sur un autre site. Les caméras du témoin et de l’aval fonctionnent aux heures prévues depuis le début du suivi. La végétation reprend sur les berges et l’équipe conserve ces relevés séparément. Elle dispose d’une semaine pour organiser une mesure complémentaire avant de répondre à la demande de travaux.","question":"Quelle mesure complémentaire permettrait de réexaminer le signal inquiétant par rapport à la situation de départ ?","options":["Reprendre les comptages en amont au crépuscule, puis les rapprocher de la série recueillie avant les travaux.","Reprendre les comptages en amont avant midi, puis les rapprocher de la série recueillie avant les travaux.","Reprendre les comptages en aval au crépuscule, puis les rapprocher de la série recueillie avant les travaux.","Reprendre les comptages en aval avant midi, puis les rapprocher de la série recueillie avant les travaux."],"correct":"A","explanation":"A. Il faut associer deux informations : la série de départ observait les sorties au crépuscule, tandis que le secteur qui paraît rester déficitaire est désormais visité avant midi. Refaire l’amont au crépuscule permet de vérifier si une différence de détection contribue au signal, sans présumer le résultat écologique. B conserve le décalage horaire. C porte sur le secteur dont le dispositif est resté au crépuscule. D change à la fois de secteur et de fenêtre d’observation sans traiter la rupture de la série amont."},{"number":38,"points":33,"passage":"Un fabricant annonce qu’un nouveau boîtier consomme quarante pour cent de moins que l’ancien pendant une heure de fonctionnement comparable. Une association vérifie cette proportion, puis suit quatre ménages. Pour cet essai, les appareils sont débranchés en dehors des durées notées ; le relevé concerne ces boîtiers. Chez Ardoise, un ancien appareil fonctionnait quatre heures par jour ; il reste utilisé ainsi, dans une seconde pièce, tandis qu’un nouveau fonctionne aussi quatre heures. Chez Tilleul, deux anciens fonctionnant chacun quatre heures sont remplacés par trois nouveaux, chacun utilisé quatre heures. Chez Rivage, un ancien utilisé quatre heures est remplacé par un nouveau utilisé huit heures. Chez Cèdre, deux anciens utilisés chacun quatre heures cèdent la place à un seul nouveau, utilisé douze heures. Les ménages apprécient l’extension des services et la marque souhaite parler d’économies pour l’ensemble du logement. L’association prépare un bilan limité aux appareils suivis et aux durées relevées, avant de reprendre cette formulation.","question":"Chez quels deux ménages le gain technique se traduit-il en baisse du total des boîtiers, d’après ces relevés ?","options":["Chez Ardoise et Tilleul, pour l’ensemble des boîtiers suivis.","Chez Ardoise et Rivage, pour l’ensemble des boîtiers suivis.","Chez Rivage et Cèdre, pour l’ensemble des boîtiers suivis.","Chez Tilleul et Cèdre, pour l’ensemble des boîtiers suivis."],"correct":"D","explanation":"D. En prenant la consommation horaire ancienne comme une unité, un nouveau boîtier consomme 0,6 unité. Tilleul passe de 8 à 7,2 unités quotidiennes ; Cèdre, de 8 à 7,2 également. Ardoise passe de 4 à 6,4, car l’ancien appareil continue à fonctionner ; Rivage passe de 4 à 4,8, car la durée double. A oublie l’ancien conservé chez Ardoise. B applique la baisse unitaire sans intégrer ni ce maintien ni le doublement chez Rivage. C ne tient pas compte du doublement chez Rivage. Le calcul porte sur ces appareils, pas sur tous les usages électriques du logement."},{"number":39,"points":33,"passage":"Une entreprise a émis cent tonnes de CO₂ pendant l’exercice écoulé. Elle publie une annonce : « Cent tonnes neutralisées grâce à notre plantation. » Le dossier technique décrit dix hectares plantés récemment. Son modèle prévoit, pour chaque hectare, dix tonnes de CO₂ absorbées entre la plantation et le vingtième anniversaire du projet. Une fiche de suivi distincte enregistre les premières mesures de croissance de l’année ; les plants y sont encore de petite taille. Pour établir les courbes du modèle, les techniciens ont suivi des arbres d’âges différents dans des parcelles voisines. La ligne intitulée « plantation nouvelle : objectif à vingt ans » est obtenue en multipliant la surface du projet par la prévision à l’hectare. Une réserve de plants et une assurance financent le remplacement des arbres perdus. Les remplaçants entreront dans le suivi à leur date de plantation. Lors de la relecture, la rapporteure entoure le chiffre de l’annonce, puis la date figurant dans l’intitulé de la ligne technique.","question":"Quelle critique de l’annonce est étayée par ce rapprochement ?","options":["Elle transforme une absorption prévue chaque année en un stock attendu au terme de vingt années.","Elle transforme une absorption prévue sur vingt ans en un résultat attribué à l’exercice écoulé.","Elle transforme une absorption prévue pour un hectare en un résultat attribué aux dix hectares.","Elle transforme le carbone des parcelles de référence en un résultat attribué à la plantation nouvelle."],"correct":"B","explanation":"B. Le chiffre de l’annonce correspond aux dix hectares multipliés par dix tonnes attendues à l’hectare sur vingt ans ; il est pourtant présenté comme la neutralisation des émissions de l’exercice écoulé. A confond la prévision entre plantation et vingtième anniversaire avec un rythme annuel. C ne correspond pas au calcul : le passage donne bien la multiplication par la surface. D confond les observations utilisées pour construire une courbe avec la surface à laquelle cette courbe est appliquée. Les moyens de remplacement soutiennent un résultat futur sans avancer sa date."}]}$paper$::jsonb),
('tcf-reading-06','tcf-reading-2026-11-close-reading-v6',$paper${"id":"tcf-reading-06","version":"tcf-reading-2026-11-close-reading-v6","title":"TCF Reading · Test 06","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"Le concert commence à dix-neuf heures, mais les portes ouvrent à dix-huit heures trente. Le placement est libre.\n\nLes spectateurs sont invités à venir assez tôt pour s'installer. Le personnel indiquera les accès sans réserver de fauteuil particulier.","question":"À partir de quand peut-on entrer ?","options":["Vingt heures","Dix-neuf heures trente","Dix-huit heures précises","Dix-huit heures trente"],"correct":"D","explanation":"Le passage indique : « Le concert commence à dix-neuf heures, mais les portes ouvrent à dix-huit heures trente. Le placement est libre. » Cela justifie la réponse : Dix-huit heures trente."},{"number":2,"points":3,"passage":"La galerie ferme lundi pour changer d'exposition. Les visites reprendront mardi, avec les mêmes horaires.\n\nLes œuvres fragiles seront déplacées par l'équipe technique. Aucun accueil de groupe ne sera assuré pendant cette installation.","question":"Pourquoi la galerie ferme-t-elle ?","options":["Pour réduire ses horaires","Pour installer une exposition","Pour organiser un concert","Pour vendre le bâtiment"],"correct":"B","explanation":"Le passage indique : « La galerie ferme lundi pour changer d'exposition. Les visites reprendront mardi, avec les mêmes horaires. » Cela justifie la réponse : Pour installer une exposition."},{"number":3,"points":3,"passage":"Les costumes prêtés doivent être rendus vendredi avant midi. Déposez-les à la réception sans les laver ; un nettoyage adapté est prévu.\n\nUne fiche permettra de signaler une déchirure ou une pièce perdue.","question":"Que faut-il éviter ?","options":["Laver soi-même les costumes","Les rapporter vendredi matin","Les rendre avant midi","Utiliser la réception"],"correct":"A","explanation":"Le passage indique : « Les costumes prêtés doivent être rendus vendredi avant midi. Déposez-les à la réception sans les laver ; un nettoyage adapté est prévu. » Cela justifie la réponse : Laver soi-même les costumes."},{"number":4,"points":3,"passage":"La répétition de la chorale se tient cette semaine dans la petite salle. L'entrée habituelle reste ouverte.\n\nLes partitions et le matériel seront transportés par les bénévoles. Les chanteurs sont invités à consulter le panneau à l'entrée avant de s'installer.","question":"Qu'est-ce qui change ?","options":["Le jour de la répétition","Le groupe de chanteurs","La salle de répétition","La porte d'entrée"],"correct":"C","explanation":"Le passage indique : « La répétition de la chorale se tient cette semaine dans la petite salle. L'entrée habituelle reste ouverte. » Cela justifie la réponse : La salle de répétition."},{"number":5,"points":9,"passage":"Je ne pourrai pas jouer dimanche. Ma remplaçante connaît déjà la partition ; nous répéterons ensemble samedi pour préparer le passage.\n\nElle souhaite surtout revoir les transitions et l'ordre des entrées. Je lui transmettrai aussi mes annotations pour éviter de lui laisser des détails à découvrir au dernier moment.","question":"Pourquoi une répétition supplémentaire est-elle prévue ?","options":["Préparer un remplacement","Vendre les instruments","Choisir la date du concert","Composer une nouvelle œuvre"],"correct":"A","explanation":"Le passage indique : « Je ne pourrai pas jouer dimanche. Ma remplaçante connaît déjà la partition ; nous répéterons ensemble samedi pour préparer le passage. » Cela justifie la réponse : Préparer un remplacement."},{"number":6,"points":9,"passage":"L'atelier de gravure fournit encres et papier. Apportez une blouse : les taches sont difficiles à enlever.\n\nLes manches longues sont recommandées pour protéger les vêtements. L'animateur montrera les gestes à réaliser avant de commencer le premier tirage.","question":"Quel objet doit apporter le participant ?","options":["Du papier","De l'encre","Une blouse","Une presse"],"correct":"C","explanation":"Le passage indique : « L'atelier de gravure fournit encres et papier. Apportez une blouse : les taches sont difficiles à enlever. » Cela justifie la réponse : Une blouse."},{"number":7,"points":9,"passage":"Bonjour, votre réservation est conservée jusqu'à vingt minutes avant le spectacle. Sans confirmation, la place pourra être proposée à une autre personne.\n\nVous pouvez confirmer en ligne ou par téléphone. Cette règle permet à la billetterie de proposer les places non utilisées sans retarder le début de la représentation.","question":"Quel risque existe sans confirmation ?","options":["Le spectacle commence plus tôt","La salle devient privée","La place peut être réattribuée","Le billet est envoyé par courrier"],"correct":"C","explanation":"Le passage indique : « Bonjour, votre réservation est conservée jusqu'à vingt minutes avant le spectacle. Sans confirmation, la place pourra être proposée à une autre personne. » Cela justifie la réponse : La place peut être réattribuée."},{"number":8,"points":9,"passage":"Nous exposons les photographies sans les noms des auteurs pendant la première visite. Les visiteurs pourront ainsi discuter des images avant de lire les biographies.\n\nLes noms seront ensuite présentés avec quelques informations sur le travail de chaque photographe.","question":"Quel est le but de ce choix ?","options":["Vendre les biographies séparément","Interdire les discussions","Cacher définitivement les artistes","Regarder d'abord les œuvres elles-mêmes"],"correct":"D","explanation":"Le passage indique : « Nous exposons les photographies sans les noms des auteurs pendant la première visite. Les visiteurs pourront ainsi discuter des images avant de lire les biographies. » Cela justifie la réponse : Regarder d'abord les œuvres elles-mêmes."},{"number":9,"points":9,"passage":"Le cinéma organise une séance calme : éclairage léger et son réduit. Les spectateurs peuvent sortir puis revenir sans gêner les autres.\n\nL'équipe souhaite accueillir les personnes gênées par les conditions d'une séance ordinaire, sans leur demander d'expliquer publiquement leur situation.","question":"À quel besoin cette séance répond-elle ?","options":["Un film réservé aux critiques","Une projection plus rapide","Une salle entièrement obscure","Un environnement sensoriel plus souple"],"correct":"D","explanation":"Le passage indique : « Le cinéma organise une séance calme : éclairage léger et son réduit. Les spectateurs peuvent sortir puis revenir sans gêner les autres. » Cela justifie la réponse : Un environnement sensoriel plus souple."},{"number":10,"points":9,"passage":"Je t'offre deux places pour la danse, mais pas de date fixe. Tu choisiras une représentation parmi celles du mois prochain.\n\nRéserve assez tôt si tu veux venir un samedi, car ces soirées se remplissent souvent rapidement. Nous pourrons y aller ensemble.","question":"Que peut décider le destinataire ?","options":["L'heure d'ouverture du théâtre","Le programme de la saison","Le nom des danseurs","La représentation à laquelle assister"],"correct":"D","explanation":"Le passage indique : « Je t'offre deux places pour la danse, mais pas de date fixe. Tu choisiras une représentation parmi celles du mois prochain. » Cela justifie la réponse : La représentation à laquelle assister."},{"number":11,"points":15,"passage":"Une troupe joue dans les villages sans salle équipée. Son décor léger se transporte dans une camionnette et s'adapte aux places publiques.\n\nLes comédiens ont construit des éléments qui peuvent changer de fonction et tenir dans un espace réduit. Une répétition sur place permet d'adapter les entrées et les déplacements au lieu du jour. Les habitants viennent parfois installer des chaises avant le spectacle. L'équipe ne cherche pas à reproduire une grande scène partout : elle veut conserver une qualité de jeu tout en acceptant les particularités de chaque village.","question":"Qu'est-ce qui facilite ces déplacements ?","options":["Une absence de répétitions","Un décor facilement transportable","Une scène permanente dans chaque village","Un spectacle sans interprètes"],"correct":"B","explanation":"Le passage indique : « Une troupe joue dans les villages sans salle équipée. Son décor léger se transporte dans une camionnette et s'adapte aux places publiques. » Cela justifie la réponse : Un décor facilement transportable."},{"number":12,"points":15,"passage":"Un musée prête des reproductions tactiles d'œuvres. Elles permettent d'explorer les formes sans toucher les originaux fragiles.\n\nLes objets ont été réalisés à une échelle permettant de sentir les contours et les volumes. Un médiateur explique les différences avec l'œuvre exposée, afin de ne pas présenter la copie comme une expérience identique. Les visiteurs peuvent poser des questions avant de revenir regarder l'original.","question":"Quel est leur intérêt ?","options":["Authentifier les œuvres vendues","Remplacer tous les originaux","Découvrir les formes par le toucher","Supprimer les visites guidées"],"correct":"C","explanation":"Le passage indique : « Un musée prête des reproductions tactiles d'œuvres. Elles permettent d'explorer les formes sans toucher les originaux fragiles. » Cela justifie la réponse : Découvrir les formes par le toucher."},{"number":13,"points":15,"passage":"La bibliothèque accueille un illustrateur en résidence. Il travaille sur son album et rencontre les lecteurs, sans assurer une permanence de dessin à la demande.\n\nL'illustrateur dispose d'une table de travail accessible pendant quelques heures annoncées. Il pourra montrer un carnet ou expliquer un choix de composition, selon l'étape de son projet. La bibliothèque veut rendre le processus de création plus visible, tout en laissant à l'artiste le temps nécessaire pour chercher et recommencer. Les rencontres avec les classes seront préparées séparément. Cette organisation doit éviter que la résidence devienne une succession de commandes rapides empêchant le travail prévu sur l'album.","question":"Quelle activité n'est pas promise ?","options":["Dessiner pour chaque demande individuelle","Rencontrer des lecteurs","Créer un album","Travailler sur place"],"correct":"A","explanation":"Le passage indique : « La bibliothèque accueille un illustrateur en résidence. Il travaille sur son album et rencontre les lecteurs, sans assurer une permanence de dessin à la demande. » Cela justifie la réponse : Dessiner pour chaque demande individuelle."},{"number":14,"points":15,"passage":"Une école de musique propose des instruments en prêt pendant le premier trimestre. Les débutants peuvent essayer avant d'investir dans un achat.\n\nLes enseignants présentent plusieurs modèles et vérifient que leur taille convient à l'élève. Les familles reçoivent des consignes d'entretien et peuvent signaler une difficulté pendant la période d'essai. À la fin du trimestre, un échange permet de décider s'il faut poursuivre ou explorer une autre possibilité. Le conservatoire souhaite éviter qu'un achat important soit réalisé avant que la personne ait découvert les exigences réelles de la pratique.","question":"Quel avantage est offert ?","options":["Tester un instrument avant de l'acheter","Éviter toute pratique personnelle","Recevoir un instrument définitivement gratuit","Choisir sans jamais essayer"],"correct":"A","explanation":"Le passage indique : « Une école de musique propose des instruments en prêt pendant le premier trimestre. Les débutants peuvent essayer avant d'investir dans un achat. » Cela justifie la réponse : Tester un instrument avant de l'acheter."},{"number":15,"points":15,"passage":"Les sous-titres d'un spectacle sont projetés au-dessus de la scène. L'équipe recommande les places centrales pour les lire confortablement.\n\nLors des essais, certaines personnes voyaient bien les comédiens mais devaient tourner constamment la tête pour suivre le texte. La billetterie donnera désormais des informations sur ces différences de visibilité. Les clients pourront choisir selon leurs besoins et les places disponibles. Le théâtre ne présente pas tous les sièges comme équivalents pour chaque usage. Il veut limiter les déceptions qui apparaissent lorsqu'un service annoncé existe techniquement, mais reste difficile à utiliser depuis une partie de la salle.","question":"Quel critère guide cette recommandation ?","options":["Le prix du programme","La proximité du vestiaire","La lisibilité des sous-titres","L'accès aux coulisses"],"correct":"C","explanation":"Le passage indique : « Les sous-titres d'un spectacle sont projetés au-dessus de la scène. L'équipe recommande les places centrales pour les lire confortablement. » Cela justifie la réponse : La lisibilité des sous-titres."},{"number":16,"points":15,"passage":"Une exposition montre les brouillons d'un auteur. Les corrections révèlent des choix successifs plutôt qu'un texte apparu immédiatement sous sa forme finale.\n\nLes visiteurs observent des phrases déplacées, des mots remplacés et parfois des pages presque entièrement abandonnées. Des notes expliquent le contexte de ces modifications. Les commissaires ont voulu rendre sensible le temps de recherche derrière un ouvrage connu. Ils ne présentent pas le brouillon comme un texte moins valable à corriger une dernière fois, mais comme une étape permettant de comprendre des décisions.","question":"Que découvrent les visiteurs ?","options":["Le travail progressif de l'écriture","Les revenus exacts de l'auteur","Une version sans aucune modification","La disparition de tous les manuscrits"],"correct":"A","explanation":"Le passage indique : « Une exposition montre les brouillons d'un auteur. Les corrections révèlent des choix successifs plutôt qu'un texte apparu immédiatement sous sa forme finale. » Cela justifie la réponse : Le travail progressif de l'écriture."},{"number":17,"points":15,"passage":"Un festival réserve des billets à prix réduit aux habitants du quartier. Ils doivent présenter un justificatif de domicile, pas une carte d'association.\n\nLes bénéficiaires pourront présenter une facture ou un document courant, sans remplir un dossier compliqué. L'association de quartier aidera les personnes qui rencontrent une difficulté lors de la réservation. Le festival souhaite retrouver un public qui vit près des salles mais ne les fréquente pas toujours. Les organisateurs vérifieront si les billets sont réellement utilisés, car une réduction annoncée ne suffit pas à créer une habitude de sortie ou à faire connaître le programme aux habitants.","question":"Quelle pièce est demandée ?","options":["Une adhésion associative","Un justificatif de domicile","Une attestation de voyage","Une carte professionnelle"],"correct":"B","explanation":"Le passage indique : « Un festival réserve des billets à prix réduit aux habitants du quartier. Ils doivent présenter un justificatif de domicile, pas une carte d'association. » Cela justifie la réponse : Un justificatif de domicile."},{"number":18,"points":15,"passage":"Pour un film documentaire, les témoins relisent leurs propos avant diffusion. Ils peuvent corriger une erreur factuelle sans imposer le montage final.\n\nLes échanges portent notamment sur les noms, les dates et les faits précis mentionnés à l'oral. Le réalisateur peut expliquer pourquoi certains passages sont raccourcis pour être compris par le public. Il souhaite construire une relation claire avec les témoins sans leur attribuer la responsabilité de tout le film. L'accord sur une citation ne signifie donc pas que chacun approuve l'ensemble du récit.","question":"Quel contrôle leur est accordé ?","options":["Décider de toutes les images","Choisir tous les autres témoins","Remplacer le réalisateur","Vérifier l'exactitude de leurs propos"],"correct":"D","explanation":"Le passage indique : « Pour un film documentaire, les témoins relisent leurs propos avant diffusion. Ils peuvent corriger une erreur factuelle sans imposer le montage final. » Cela justifie la réponse : Vérifier l'exactitude de leurs propos."},{"number":19,"points":15,"passage":"Un atelier d'écriture réunit débutants et auteurs réguliers. Chacun lit s'il le souhaite ; écouter les textes des autres constitue aussi une participation.\n\nLes animateurs proposent d'abord de petites consignes puis laissent un temps d'écriture silencieuse. Les textes ne sont pas classés du meilleur au moins réussi. Les échanges portent sur ce que l'on comprend, sur les effets recherchés et sur les possibilités de reprise. Le groupe veut favoriser des essais sans transformer chaque séance en évaluation publique.","question":"Quelle règle favorise l'accueil ?","options":["Seuls les auteurs expérimentés peuvent écouter","Les débutants doivent se taire","Tous doivent publier un livre","La lecture de son texte reste facultative"],"correct":"D","explanation":"Le passage indique : « Un atelier d'écriture réunit débutants et auteurs réguliers. Chacun lit s'il le souhaite ; écouter les textes des autres constitue aussi une participation. » Cela justifie la réponse : La lecture de son texte reste facultative."},{"number":20,"points":21,"passage":"Une salle diffuse les représentations en ligne pour les personnes éloignées. Elle conserve cependant des rencontres sur place, car les échanges informels après le spectacle comptent pour les habitués. Les captations sont proposées sur une période limitée après les représentations. L'équipe améliore le son et les sous-titres, sans prétendre que l'écran remplace exactement la salle. Elle souhaite toucher les personnes empêchées de se déplacer, tout en maintenant des occasions de discussion pour celles qui peuvent venir. Le bilan distinguera ces usages plutôt que les opposer comme deux publics nécessairement concurrents.","question":"Que veut-elle préserver ?","options":["L'absence de contact avec le public","Une dimension sociale de la sortie","La suppression des échanges spontanés","Une exclusivité complète sur place"],"correct":"B","explanation":"Le passage indique : « Une salle diffuse les représentations en ligne pour les personnes éloignées. Elle conserve cependant des rencontres sur place, car les échanges informels après le spectacle comptent pour les habitués. » Cela justifie la réponse : Une dimension sociale de la sortie."},{"number":21,"points":21,"passage":"Une ville commande une sculpture après une consultation. Les habitants choisissent l'emplacement et discutent des usages du lieu ; ils ne votent pas sur chaque détail artistique. Les réunions commencent par une présentation du travail de l'artiste et des contraintes techniques. Les participants peuvent expliquer comment ils traversent la place et où ils aiment s'arrêter. Le comité veut ainsi éviter qu'une œuvre soit installée sans rapport avec la vie du lieu. L'auteur conserve toutefois la responsabilité de ses choix formels, dans le cadre de la commande discutée.","question":"Quelle est la portée de la consultation ?","options":["Elle supprime le travail de l'artiste","Elle concerne l'insertion de l'œuvre dans l'espace public","Elle fixe tous les gestes du sculpteur","Elle décide du prix des billets"],"correct":"B","explanation":"Le passage indique : « Une ville commande une sculpture après une consultation. Les habitants choisissent l'emplacement et discutent des usages du lieu ; ils ne votent pas sur chaque détail artistique. » Cela justifie la réponse : Elle concerne l'insertion de l'œuvre dans l'espace public."},{"number":22,"points":21,"passage":"Un conservatoire ouvre des ateliers sans examen d'entrée. Les inscriptions augmentent, mais certains créneaux restent inaccessibles aux personnes travaillant le soir. Une enquête est proposée aux familles et aux adultes inscrits, avec une version accessible par téléphone. Le conservatoire étudie aussi des séances ponctuelles le week-end. Il ne veut pas considérer les absences comme la preuve que les personnes ne s'intéressent pas à la musique. Le bilan portera sur les conditions qui permettent effectivement de venir, pas uniquement sur l'absence d'examen annoncée dans la brochure.","question":"Quelle limite subsiste ?","options":["Un examen est obligatoire partout","Les ateliers ne disposent d'aucun enseignant","Les horaires peuvent encore exclure des participants","Aucun adulte ne souhaite apprendre"],"correct":"C","explanation":"Le passage indique : « Un conservatoire ouvre des ateliers sans examen d'entrée. Les inscriptions augmentent, mais certains créneaux restent inaccessibles aux personnes travaillant le soir. » Cela justifie la réponse : Les horaires peuvent encore exclure des participants."},{"number":23,"points":21,"passage":"Une librairie fait découvrir des auteurs peu présents dans les médias. Les ventes sont modestes au début, mais les échanges réguliers créent progressivement un public fidèle. Les lecteurs rencontrent les écrivains plusieurs fois, suivent la préparation d'un livre et recommandent ensuite certains titres à leurs proches. La librairie réserve une petite table à ces découvertes pour qu'elles ne disparaissent pas immédiatement des rayons. Elle sait que les recettes doivent rester suffisantes pour faire vivre le lieu.","question":"Quel effet est décrit ?","options":["Un succès immédiat garanti","Un abandon de tous les petits éditeurs","La disparition des rencontres","La construction lente d'un lectorat"],"correct":"D","explanation":"Le passage indique : « Une librairie fait découvrir des auteurs peu présents dans les médias. Les ventes sont modestes au début, mais les échanges réguliers créent progressivement un public fidèle. » Cela justifie la réponse : La construction lente d'un lectorat."},{"number":24,"points":21,"passage":"Des comédiens improvisent à partir de souvenirs recueillis dans un quartier. Ils préviennent que les scènes sont des créations inspirées des récits, pas des reconstitutions exactes. Les personnes rencontrées sont informées de cette transformation et peuvent assister à une répétition. Certaines reconnaissent un détail, d'autres découvrent une scène qui rassemble plusieurs expériences. Le spectacle sera accompagné d'une discussion sur cette différence, afin que le public puisse apprécier le travail de création et comprendre la manière dont les témoignages l'ont nourri.","question":"Pourquoi cette précision importe-t-elle ?","options":["Distinguer création artistique et fidélité documentaire","Remplacer tous les témoignages","Interdire toute interprétation","Garantir l'exactitude de chaque dialogue"],"correct":"A","explanation":"Le passage indique : « Des comédiens improvisent à partir de souvenirs recueillis dans un quartier. Ils préviennent que les scènes sont des créations inspirées des récits, pas des reconstitutions exactes. » Cela justifie la réponse : Distinguer création artistique et fidélité documentaire."},{"number":25,"points":21,"passage":"Faute de budget de transport, une compagnie remplace ses décors par trois panneaux. Dans une première répétition, les acteurs parlent depuis trois points du plateau, puis sortent ; des techniciens changent les panneaux derrière le rideau. Les spectateurs reconnaissent les lieux grâce à la lumière et comprennent que les trois amis partent ensemble. Lors d'un second essai, les répliques et les éclairages restent les mêmes. Au moment du départ, deux acteurs entraînent un panneau, tandis que le troisième le retient brièvement avant de les suivre. Dans les retours recueillis, plusieurs spectateurs disent que ce personnage semblait céder à ses compagnons plutôt que partager leur projet. Une coproduction offre ensuite de financer les grands décors. Le metteur en scène garde les panneaux et demande de nouvelles répétitions autour du départ. Les comédiens proposent aussi de revoir les distances entre eux et la place du dialogue dans cette scène.","question":"Quel prolongement exploiterait le plus directement la différence observée entre les deux répétitions ?","options":["Faire varier la manipulation des panneaux avec les accords et les résistances entre les personnages.","Renforcer les différences de lumière pour que chaque lieu soit reconnu avant la première réplique.","Attribuer à chacun un espace distinct où ses déplacements suivent un rythme indépendant.","Stabiliser les panneaux pendant les échanges pour donner davantage de poids aux mots du dialogue."],"correct":"A","explanation":"Les lieux étaient déjà reconnus et les mots ne changent pas ; c'est la résistance physique dans un déplacement commun qui fait percevoir un désaccord. A prolonge donc le mécanisme révélé par la comparaison. B renforcerait un repérage spatial déjà obtenu. C développerait l'indépendance d'espaces, alors que le sens nouveau naît d'un geste en réponse aux autres. D privilégierait des mots restés identiques dans les deux essais."},{"number":26,"points":21,"passage":"Devant un portrait, Nora montre le menton relevé : « Il semble regarder les autres de haut. » Karim s'arrête sur l'ombre des paupières : « J'y vois plutôt quelqu'un d'épuisé. » La médiatrice note leurs remarques, puis lit deux documents : une commande passée lors de la nomination du modèle à une fonction publique et une lettre de son frère évoquant une longue convalescence. Nora reprend : « Je garde ce que j'ai vu dans la posture ; pour une entrée en fonction, on pouvait attendre cette tenue. Je ne lui prêterais plus aussi vite du mépris. » Karim revient à la lettre : « Ce que son frère raconte donne un appui à cette fatigue qui m'avait frappé. » La médiatrice conserve les deux prises de parole de chacun dans le carnet. Elle leur demande ensuite quels autres détails du tableau pourraient encore faire évoluer leurs lectures.","question":"Comment évoluent les deux lectures au cours de l'échange ?","options":["Nora conserve son jugement mais en déplace la preuve ; Karim change de jugement en gardant son premier indice.","Nora reprend le jugement de Karim avec les mêmes preuves ; Karim remplace l'observation du tableau par une lecture officielle.","Nora modifie son jugement sur un indice déjà observé ; Karim maintient le sien en lui ajoutant un appui nouveau.","Nora ajoute une lecture sans revenir sur la première ; Karim suspend la sienne devant deux informations qu'il juge incompatibles."],"correct":"C","explanation":"Nora garde son observation de la posture mais cesse d'y voir aussi vite du mépris ; Karim retrouve sa lecture de la fatigue dans une information nouvelle. C combine ces deux évolutions. A inverse le changement de Nora et prête à Karim un changement absent. B confond les deux jugements : Nora ne reprend pas la fatigue. D ignore le retrait du jugement de mépris et l'appui, plutôt que la suspension, exprimé par Karim."},{"number":27,"points":21,"passage":"Une collection de lettres fragiles limite les consultations sur place. Un généalogiste demandait à revoir un ajout au verso ; un agrandissement lui permet finalement de lire le nom corrigé. Une historienne compare, elle, deux lettres portant des dates éloignées, mais une écriture proche. Elle veut savoir si leurs feuilles pourraient provenir du même stock, ce qui modifierait l'hypothèse d'une copie tardive. Les encres paraissent voisines sur les images ; le conservateur rappelle que leur teinte évolue avec les conditions de conservation. Il montre un feuillet devant une fenêtre : un dessin pâle apparaît dans son épaisseur. Posé à plat sur la table, le même dessin devient difficile à distinguer. Le dossier numérique contient déjà les transcriptions et le classement des lettres par date. L'historienne souhaite comparer plusieurs pièces sans multiplier les sorties des originaux.","question":"Quelle évolution du dossier numérique répondrait le mieux à la question de l'historienne ?","options":["Photographier les encres dans des conditions de couleur identiques, puis comparer les teintes des lettres datées.","Photographier les feuillets en lumière traversante, puis comparer les motifs que cette prise de vue fait apparaître.","Assembler les images dans l'ordre des dates écrites, puis rechercher des changements progressifs dans la graphie.","Agrandir les zones corrigées au verso, puis comparer les noms et les ajouts entre les différentes lettres."],"correct":"B","explanation":"La question concerne l'origine du papier, et l'observation à la fenêtre révèle un indice dans son épaisseur que la vue à plat restitue mal : B réunit ces deux éléments. A étudie l'encre, dont la couleur varie avec la conservation. C exploite dates et graphie sans accéder à l'indice matériel recherché. D reprend la solution utile au généalogiste pour une autre question, portant sur le contenu écrit."},{"number":28,"points":21,"passage":"Une éditrice prépare les versions papier et audio d'un essai. Certains lecteurs l'écoutent dans les transports ; d'autres y reviennent pour retrouver un raisonnement. Dans le prototype, un repère mène au moment où le récit d'un trajet cède à une discussion du prix des billets. Dans un autre chapitre, un repère est placé lorsque l'auteur quitte un témoignage local pour examiner ses conséquences à l'échelle du territoire. Le comédien marque aussi des pauses et change de ton pour les citations. Les premières éditions papier n'ont pas toutes la même pagination. Un nouveau chapitre expose une règle générale, cite ensuite la lettre d'une usagère, puis analyse les situations où cette règle fonctionne mal. L'équipe prépare ses accès directs tout en conservant une écoute continue, et plusieurs auditeurs proposent également des séquences adaptées à leurs trajets de dix minutes.","question":"Quel emplacement d'un nouveau repère serait le plus cohérent avec les deux choix déjà retenus ?","options":["Au début du passage où l'auteur examine les limites de la règle qu'il vient d'exposer.","À la dixième minute du chapitre, pour retrouver une durée d'écoute correspondant au trajet proposé.","Au début de la lettre citée, lorsque le comédien adopte le ton de la voix rapportée.","Au changement de page de l'édition papier, pour retrouver le même emplacement dans les deux versions."],"correct":"A","explanation":"Les deux repères existants introduisent un changement d'échelle ou de fonction du raisonnement ; le passage de la règle à l'examen de ses limites remplit une fonction comparable : A. B répond à une autre demande d'usage, celle de la durée des trajets. C suit l'interprétation vocale d'une citation, qui peut rester intégrée au raisonnement en cours. D suit une mise en page variable plutôt que l'articulation observée dans les deux exemples."},{"number":29,"points":21,"passage":"Après une édition très fréquentée, un festival prépare déjà la suivante. Toutes les équipes reçoivent un lien pour annoncer leurs disponibilités de l'an prochain. Une fois les créneaux proposés validés, le dernier écran invite à donner une appréciation de l'édition passée. La direction relève une forte majorité d'avis favorables et propose de reconduire les horaires. La coordinatrice compare les listes : plusieurs personnes présentes l'été précédent n'ont encore proposé aucun créneau. Parmi les courriels reçus, l'une explique un changement d'emploi, une autre évoque des pauses régulièrement repoussées. À la réunion, des habitués racontent comment ils avaient échangé leurs postes pour souffler ; de nouveaux bénévoles décrivent aussi des expériences réussies. Deux récits de la soirée de clôture ont été lus en réunion; les fiches conservées évoquent aussi le montage, les premiers jours d'ouverture et plusieurs postes d'accueil. Avant de clore le bilan, la coordinatrice veut comprendre l'écart entre l'enthousiasme affiché et le nombre de personnes prêtes à revenir.","question":"Quelle limite faut-il prendre en compte avant de reconduire l'organisation sur la base des avis recueillis ?","options":["Les avis reflètent surtout les équipes d'accueil, tandis que l'expérience des postes techniques reste moins visible.","Les avis reflètent surtout les dernières journées, tandis que les difficultés rencontrées au début restent moins visibles.","Les avis reflètent surtout les nouveaux bénévoles, tandis que l'expérience des habitués reste moins visible.","Les avis reflètent surtout les personnes ayant déjà prévu de revenir, tandis que d'autres expériences restent moins visibles."],"correct":"D","explanation":"Pour accéder au dernier écran d'évaluation, il faut d'abord valider des disponibilités futures. D identifie donc une sélection liée au retour envisagé, sans supposer que toutes les personnes absentes seraient insatisfaites. A et C généralisent la visibilité de certains postes ou de nouveaux bénévoles, alors que d'autres expériences figurent dans le bilan. B confond les deux récits de clôture choisis pour la réunion avec l'ensemble des fiches, qui évoquent aussi le début du festival. Le parcours du formulaire établit directement le filtre de D."},{"number":30,"points":26,"passage":"Une ville offre un abonnement donnant accès à douze lieux culturels. Le réseau s'était agrandi l'année précédente, mais beaucoup de bénéficiaires ne l'utilisaient toujours pas. Ils disent ne pas savoir quelle activité choisir ni comment se déroule une première visite. La bibliothèque propose alors deux sorties accompagnées, suivies d'un échange sur la manière de consulter les programmes. Le prix, les lieux accessibles et les conditions d'entrée restent identiques. Quelques semaines plus tard, une partie des participants revient dans les établissements visités ; d'autres réservent seuls dans des lieux que le groupe n'a pas découverts. Les médiateurs ne choisissent pas ces nouvelles sorties à leur place. Les bénéficiaires qui ne pouvaient pas venir aux deux dates proposées sont interrogés séparément : leur absence ne permet pas de conclure qu'ils ne souhaitent aucune activité. Le bilan porte donc aussi sur la façon dont chacun peut transformer l'abonnement en projet concret.","question":"Que révèle le bilan des nouvelles réservations sur les participants après les sorties accompagnées ?","options":["Ils privilégient les établissements déjà présentés, dont les codes leur sont devenus plus familiers pendant les sorties.","Ils commencent à choisir dans une offre qui leur était déjà ouverte, en réutilisant les repères acquis pendant l'accompagnement.","Ils profitent de l'élargissement du réseau, qui a rendu de nouveaux établissements accessibles au cours de cette expérimentation.","Ils prolongent le programme du groupe, dont les médiateurs continuent de fixer les étapes après les premières visites."],"correct":"B","explanation":"Les participants utilisent seuls les repères acquis pour choisir ailleurs dans le réseau, sans modification de leurs droits d'entrée : B. A ne rend pas compte des lieux non visités. C attribue l'effet à un agrandissement antérieur à l'essai. D maintient un choix des médiateurs que le passage exclut."},{"number":31,"points":26,"passage":"Sous une fresque repeinte au XIXe siècle, des sondages révèlent une composition plus ancienne. Dégager entièrement celle-ci détruirait une partie du repeint, auquel les habitants associent l'histoire du bâtiment. Conserver chaque zone en l'état laisserait toutefois des lacunes récentes qui brouillent les figures visibles. L'équipe retient un parcours où l'on voit la scène du XIXe siècle, deux ouvertures montrant la couche ancienne et des retouches limitées aux manques qui empêchent de suivre certains contours. Ces retouches sont repérables de près; certaines portent sur les contours de la couche ancienne ainsi dégagée. Les notices indiquent la date de chaque intervention connue, y compris celle d'aujourd'hui. Des dessins documentent l'état supposé de la composition ancienne, sans que l'on cherche à le rétablir sur toute la surface. La fresque rouvre au public. Le comité ne présente ni la première couche ni l'apparence transmise aux habitants comme le seul état qui mériterait le nom d'œuvre.","question":"Quelle politique de présentation relie le traitement de la fresque et celui des notices ?","options":["Reconstituer la première composition sur la fresque et détailler les transformations ultérieures dans les notices.","Conserver la composition du XIXe siècle sur la fresque et réserver les couches anciennes aux documents explicatifs.","Montrer des états successifs sur la fresque et identifier dans les notices les retouches qui en facilitent la lecture.","Conserver les zones dégagées sans retouche sur la fresque et proposer dans les notices des reconstitutions qui en complètent la lecture."],"correct":"C","explanation":"C associe l'exposition directe de plusieurs couches aux retouches identifiables et datées. A correspondrait à un retour matériel à l'origine, qui n'est pas recherché sur toute la surface. B réserverait la couche ancienne aux documents, alors que deux ouvertures la montrent. D affirme que les zones dégagées restent sans retouche, alors que certains contours de cette couche ancienne sont effectivement retouchés."},{"number":32,"points":26,"passage":"Un groupe dont les refrains circulent beaucoup en ligne prépare un premier concert en grande salle. Il reprend d'abord l'ordre des morceaux les plus écoutés, puis répète devant un petit public comprenant des habitués et des personnes qui le découvrent. Les transitions paraissent brusques. Les musiciens réintroduisent un titre lent, peu consulté sur la plateforme, qui reprend une phrase d'un couplet du morceau précédent et annonce un motif instrumental du suivant. Il est joué sans pause entre les trois morceaux. Après l'essai, des spectateurs qui ne connaissaient pas le groupe décrivent précisément ce passage, bien qu'ils aient peu applaudi entre les titres. Ils décrivent les trois morceaux comme un seul mouvement plutôt que deux blocs contrastés. Les refrains les plus connus restent répartis entre le début et la fin du programme. L'ingénieure du son a par ailleurs réglé un problème d'écho pour l'ensemble du programme. Dans la suite du programme, un titre énergique précède une fin calme. Les musiciens conservent le titre lent et poursuivent leurs essais ; ils n'en déduisent pas qu'il deviendra leur morceau le plus populaire en ligne.","question":"Quelle fonction le titre lent remplit-il dans l'organisation du concert d'essai ?","options":["Il crée une rupture entre deux ensembles de morceaux, dont les climats gagnent ainsi en contraste.","Il fait entendre des liens entre les morceaux voisins, qui prennent sens dans leur enchaînement.","Il introduit un bloc central de morceaux aux refrains connus, qui rassemble les repères familiers aux habitués.","Il prépare une montée régulière de l'intensité, prolongée par les morceaux qui suivent jusqu'au final."],"correct":"B","explanation":"La phrase empruntée au couplet précédent et le motif qui annonce le suivant construisent une continuité perceptible : B. A ferait de ce passage une séparation entre deux blocs, lecture opposée à celle des spectateurs. C attribue au titre l'ouverture d'un bloc de refrains familiers, alors que ceux-ci restent répartis entre le début et la fin. D suppose une montée continue jusqu'au final, alors que le programme revient au calme."},{"number":33,"points":26,"passage":"Dans une exposition, les visiteurs choisissent des énigmes sur des écrans placés près des objets. Un livret propose des parcours thématiques et des explications historiques ; à une table, les médiateurs reprennent avec eux les réponses difficiles. Une nouvelle version du logiciel conserve les réponses provisoires et demande une justification avant la validation. Son compteur ne mesure que les périodes où l'écran est utilisé : une pause sans contact interrompt le chronométrage. Au bilan, le temps affiché baisse, tandis que les carnets contiennent autant de réponses et davantage de références à des détails matériels. Un observateur note de longs arrêts devant certaines vitrines. Une justification cite une fissure située au dos d'un vase, invisible sur la photographie de face et absente du livret. Le médiateur raconte qu'on lui demande maintenant de confirmer des remarques déjà formulées plutôt que de fournir le point de départ d'une réponse. L'équipe cherche à interpréter ces résultats avant de modifier de nouveau les écrans.","question":"Quelle explication relie le mieux les résultats du compteur et ceux des carnets ?","options":["Le livret fournit les éléments repris dans les justifications, tandis que le compteur suit seulement les échanges avec l'écran.","Les médiateurs fournissent les éléments repris dans les justifications, tandis que le compteur suit seulement les échanges avec l'écran.","Les visiteurs terminent moins d'énigmes, mais le temps libéré permet de discuter plus précisément les activités qu'ils conservent.","Les objets fournissent des indices utilisés dans les justifications, pendant des périodes qui échappent au compteur de l'écran."],"correct":"D","explanation":"Le compteur s'arrête hors interaction, alors que des observations devant les vitrines alimentent les justifications: D rapproche la mesure et la provenance des indices. A est limité par l'exemple de la fissure absente du livret. B confond les confirmations du médiateur avec l'origine des remarques déjà faites. C avance une baisse du nombre d'énigmes terminées que le bilan n'établit pas: le nombre de réponses conservées ne distingue pas les réponses provisoires des validations."},{"number":34,"points":26,"passage":"Pour une œuvre collective, les premiers participants avaient reçu des carrés identiques et un motif de vague à reprendre. La version suivante accueille des tissus, des mots et des formes apportés librement. Chaque auteur date son fragment au dos. Lors du montage, un grand collage bleu, très fini, recouvre l'extrémité d'une ligne orange tracée sur une pièce voisine. L'artiste le déplace : il quitte un groupe d'éléments bleus et se retrouve entre deux contributions plus anciennes ; la ligne orange rejoint désormais une découpe du collage. Plus loin, une bande de papier porte seulement « ici, encore… ». Son auteur propose de la retirer pour la terminer. L'artiste la garde à l'endroit où elle prolonge un mot laissé en suspens sur un tissu d'une autre couleur. Elle photographie les deux montages pour les discuter avec les participants. Le collage reste très travaillé, la bande reste provisoire, et les dates ne se suivent plus sur le mur.","question":"Quel critère rend le mieux compte des deux interventions de l'artiste ?","options":["La reprise de motifs communs permet d'unifier des apports dont les matériaux et les finitions diffèrent.","La succession des contributions permet de montrer comment le projet se transforme au fil de sa fabrication.","La relation perceptible entre les apports permet de lire chaque intervention comme une réponse à une autre.","Le regroupement de formes et de couleurs proches permet d'organiser des contributions venues d'auteurs différents."],"correct":"C","explanation":"Le collage est déplacé pour que la ligne voisine puisse le rejoindre ; la bande inachevée est conservée parce qu'elle prolonge un mot laissé ailleurs. C explique ensemble ces deux décisions. A reprend le principe du premier dispositif, mais la ligne et le fragment verbal ne reproduisent pas un motif commun. B ne rend pas compte de l'ordre des dates modifié. D est contredit par le déplacement hors du groupe bleu et le rapprochement de couleurs différentes."},{"number":35,"points":26,"passage":"Un musée cherche à évaluer cinq séances proposées à un petit groupe, à côté d'une exposition très fréquentée. Après la première séance, les participants se disent satisfaits et réemploient plusieurs expressions du médiateur sur les usages et les contextes d'origine des objets. Pendant le cycle, le médiateur fait aussi pratiquer une démarche: proposer un usage, l'appuyer sur des indices visibles et le discuter avec le groupe. Le service de communication souhaite y voir la preuve d'un regard devenu plus autonome. L'équipe éducative prépare un autre exercice un mois après la fin du cycle. Elle présente deux objets sortis des réserves, jamais montrés au groupe, sans notice et sans commentaire préalable. Les participants proposent des usages possibles, désignent des traces matérielles et révisent certaines hypothèses lorsqu'un autre membre leur signale un détail. Ils n'aboutissent pas tous à la même interprétation. Le musée conserve dans son bilan le nombre d'entrées de l'exposition et le nombre de personnes différentes accompagnées, sans additionner leurs cinq visites comme cinq nouveaux visiteurs. Il ne compare pas encore ce groupe volontaire à un groupe équivalent venu librement. Les responsables veulent distinguer ce qu'ils ont observé de ce qu'une évaluation plus large devrait encore établir.","question":"Quelle conclusion peut-on tirer du second exercice sans dépasser les éléments du bilan ?","options":["Le groupe transpose la démarche à des objets nouveaux, mais le bilan n’isole pas ce que le cycle a apporté à son autonomie.","Le groupe retrouve les usages d’origine d’objets nouveaux, mais le bilan ne montre pas si ces connaissances se maintiendront plus longtemps.","Le groupe converge vers une interprétation commune, mais le bilan ne permet pas de savoir si elle dépend des échanges entre participants.","Le groupe observe mieux que les visiteurs libres, mais le bilan ne sépare pas l’effet des séances de celui des visites répétées."],"correct":"A","explanation":"A. Une démarche pratiquée pendant le cycle réapparaît un mois plus tard sur des objets jamais montrés : les participants proposent des usages, les appuient sur des traces et discutent leurs hypothèses. Le bilan observe donc un transfert, sans comparaison permettant d’isoler l’effet du cycle sur leur autonomie. B transforme des usages possibles en usages d’origine retrouvés, que l’exercice ne vérifie pas. C affirme une convergence que le passage exclut : les interprétations ne sont pas toutes identiques. D conclut à une supériorité sur les visiteurs libres alors que ce groupe de comparaison n’a pas été évalué. Les réserves ajoutées à B, C et D ne rendent pas leurs constats initiaux établis."},{"number":36,"points":33,"passage":"Une ville finance un atelier ouvert au public. Après plusieurs mois, trois matinées par semaine sont réservées aux artistes. Les feuilles de présence montrent qu'elles sont utilisées ; l'équipe d'accueil prépare les visites de l'après-midi. Un carnet recueille les questions des visiteurs, notamment sur les essais abandonnés. Sur le site municipal, le journal de l'atelier prend la forme d'un calendrier : à chaque date correspond une image légendée, avec le nom d'un artiste. Les cases vides suscitent des demandes de complément. Les créateurs partagent pourtant un four et s'entraident pour certains matériaux. Dans les carnets de travail du premier mois, on trouve des pistes qui réclament plusieurs cuissons espacées. Quelques mois après l'aménagement des horaires, ces mêmes pistes portent encore des reports ; les photographies publiées montrent de nombreuses petites variations achevées successivement. Les visiteurs sont restés aussi nombreux, et le carnet de préparation ne signale pas de hausse du temps consacré à leur accueil. La ville prépare un nouveau modèle de bilan à partir de ces documents.","question":"Quelle révision du bilan répondrait le plus directement au risque suggéré par le rapprochement de ces documents ?","options":["Documenter, pour chaque séance publique, une interaction entre visiteur et artiste plutôt qu'une œuvre achevée.","Documenter, pour chaque lieu, une évolution collective plutôt qu'une production attribuée à chaque artiste.","Documenter, pour chaque semaine, les conditions de préparation plutôt que le nombre d'objets montrés.","Documenter, pour chaque piste, une succession d'essais plutôt qu'un résultat distinct par journée."],"correct":"D","explanation":"Les matinées de travail existent, mais le journal demande une image pour chaque jour, alors que des pistes longues restent reportées et que des variations courtes occupent les publications. D modifierait l'unité de preuve pour rendre visible l'avancement d'une recherche longue, sans prétendre que le calendrier est la cause démontrée de tous les reports. A traite les rencontres et B l'attribution collective. C décrit les conditions de préparation à l'échelle d'une semaine; cela ne retrace pas directement la succession d'essais d'une même piste. D répond donc le plus précisément au contraste entre durée des recherches et rythme du compte rendu."},{"number":37,"points":33,"passage":"Un documentaire recueille les souvenirs d'un quartier industriel. Un voisin raconte : « Pour moi, l'usine a fermé en 2001. Cette année-là, nous avons recommencé à dormir les fenêtres ouvertes. » Une ancienne salariée répond, dans un autre entretien : « Moi, je dis 2003. Jusqu'à cette date, je venais encore pour l'inventaire ; j'ai rendu mon vestiaire avec mon dernier contrat. » Le dossier préparé pour le montage contient trois pièces : l'annonce d'une réduction d'activité en 2000, le registre de la dernière mise à l'arrêt des machines en 2001 et les documents de fin des derniers contrats en 2003. La salariée décrit le bâtiment silencieux dans lequel son équipe continuait de travailler. Le voisin, lui, explique qu'il ne suivait guère ce qui se passait derrière les grilles une fois le bruit disparu. Un producteur propose de remplacer l'une des dates dans les sous-titres pour éviter que le public pense à une erreur. Le réalisateur remet les deux extraits côte à côte sur sa table de montage, avec leurs documents.","question":"Quelle lecture du désaccord est la mieux étayée par les entretiens et les documents ?","options":["Il oppose une date conservée dans les souvenirs à une date officielle que les documents conduisent à lui substituer.","Il oppose deux évaluations de la durée des effets, bien que les témoins retiennent le même moment de fermeture.","Il oppose deux seuils d'un même processus, auxquels les témoins donnent chacun le nom de fermeture.","Il oppose le calendrier initial d'une annonce à celui de sa réalisation, après un report confirmé par les documents."],"correct":"C","explanation":"Le voisin se repère à l'arrêt du bruit, confirmé par les machines arrêtées en 2001 ; la salariée se repère à la fin de sa présence contractuelle, documentée en 2003. C donne sens aux deux dates sans en transformer une en erreur. A suppose une seule date officielle à substituer. B confond la durée des effets avec les deux moments distincts retenus. D prend l'annonce de réduction d'activité pour une fermeture annoncée puis reportée, ce que les documents ne disent pas."},{"number":38,"points":33,"passage":"Une lectrice de romans policiers accepte deux conseils d'une libraire. Le premier est un roman ancien, composé de lettres entre un médecin, un journaliste et un éditeur. Les usages mondains et les règles de publication pèsent sur leurs décisions. La lectrice abandonne le livre, fatiguée par les noms et les retours dans le temps. Elle dit pourtant avoir aimé découvrir ce milieu. Elle a aussi marqué une lettre : l'éditeur y paraît protéger un auteur, puis le récit du journaliste l'a fait revenir sur les intérêts qu'elle lui prêtait. Le second livre, contemporain et plus court, raconte une crise familiale au cours de laquelle une fille prend en charge des décisions auparavant réservées à sa mère. La lectrice le termine. « Ce changement de place m'a touchée », dit-elle. Elle montre ensuite deux passages consacrés au même appel téléphonique : après le chapitre de la mère, elle a relu celui de la fille et compris autrement son silence. La libraire note ces appréciations positives, y compris celles du livre abandonné, avant de préparer un troisième conseil.","question":"Quel intérêt est attesté dans les deux retours de la lectrice ?","options":["La confrontation de récits qui invitent à réévaluer les mobiles et la crédibilité des personnages.","La construction d'une intrigue où chaque rebondissement relance une action tendue jusqu'au dénouement.","L'inscription des choix individuels dans un milieu historique dont les règles sociales deviennent progressivement compréhensibles.","L'évolution des liens familiaux à travers des conflits qui modifient durablement les rôles de chacun."],"correct":"A","explanation":"Dans le premier livre, un autre récit modifie le jugement porté sur les intérêts de l'éditeur ; dans le second, le point de vue de la mère change la lecture du silence de la fille. A est donc attesté dans les deux retours. B s'appuie sur l'habitude du roman policier, sans être le plaisir décrit ici. C est explicitement apprécié dans le roman ancien, et D dans le roman familial, mais ni l'un ni l'autre n'est établi comme point partagé par les deux retours."},{"number":39,"points":33,"passage":"Une petite salle culturelle réduit la taille de ses groupes pour laisser davantage de place aux questions. Le nombre de séances reste inchangé. Les médiateurs observent des échanges plus longs et les visiteurs présents décrivent plus précisément ce qu'ils ont découvert. La direction souhaite aussi accueillir des personnes qui ne viennent jamais. Pour répartir les places, elle ouvre les réservations en ligne un lundi matin et demande une confirmation rapide. Des noms nouveaux apparaissent sur la liste d'inscription, mais plusieurs places sont finalement reprises par des habitués. Des personnes travaillant à horaires variables expliquent qu'elles ne pouvaient confirmer si tôt ; auparavant, elles venaient parfois directement le jour même. Le nombre de premières visites diminue. Le mode de comptage des entrées n'a pas changé, et les retours des mêmes personnes sont toujours identifiés séparément ; leur nombre est resté stable. L'équipe tient au format qui facilite les échanges. Elle prépare néanmoins un second essai, avec quelques places accessibles sans réservation, afin de comprendre qui la nouvelle organisation permet effectivement de recevoir.","question":"Quelle lecture du bilan décrit le mieux l'évolution conjointe des échanges et du public accueilli ?","options":["La qualité progresse avec des groupes plus divers, mais la réservation éloigne une partie des habitués qui venaient spontanément.","La qualité progresse alors que la part des premières visites diminue, certaines places libérées étant reprises par des habitués.","La qualité progresse avec des groupes de composition stable, mais leur taille réduite fait baisser autant les premières visites que les retours.","La qualité progresse avec des groupes accueillant davantage de nouveaux venus, mais les annulations font diminuer le nombre total d'entrées."],"correct":"B","explanation":"Les échanges s'améliorent chez les présents. Le nombre de premières visites diminue tandis que celui des retours reste stable: la part des premières visites recule, et certaines places sont reprises par des habitués. B relie ces observations. A ajoute une diversité accrue que le bilan n'établit pas; la présence de nouveaux noms parmi les inscrits ne suffit pas à la démontrer chez les personnes venues. C suppose une baisse parallèle des retours alors que leur nombre reste stable. D confond les nouveaux inscrits avec les personnes effectivement accueillies, dont les premières visites diminuent."}]}$paper$::jsonb);

