do $verify$ begin
 if (select count(*) from academy_tcf_reading.published_papers)<>20 or
    (select count(*) from academy_tcf_reading.published_papers
      where test_id in ('tcf-reading-01','tcf-reading-02','tcf-reading-03','tcf-reading-04','tcf-reading-05','tcf-reading-06') and version='tcf-reading-2026-11-close-reading-v6')<>6 then
  raise exception 'Reading publication pointer verification failed'; end if;
 if (select count(*) from academy_tcf_reading.papers
      where id in ('tcf-reading-01','tcf-reading-02','tcf-reading-03','tcf-reading-04','tcf-reading-05','tcf-reading-06') and version='tcf-reading-2026-11-close-reading-v6')<>6 then
  raise exception 'Six immutable v6 papers must exist'; end if;
end $verify$;
commit;
